        user: 'System',
        content: text,
        timestamp: new Date().toISOString()
    };

    // Add to history
    const roomData = getRoom(roomName);
    roomData.messages.push(message);
    if (roomData.messages.length > MAX_HISTORY) {
        roomData.messages.shift();
    }

    broadcastToRoom(roomName, message);
}

const server = http.createServer((req, res) => {
    // Serve the client HTML
    if (req.url === '/' || req.url === '/index.html') {
        fs.readFile(path.join(__dirname, 'index.html'), (err, data) => {
            if (err) {
                res.writeHead(500);
                res.end('Error loading index.html');
                return;
            }
            res.writeHead(200, { 'Content-Type': 'text/html' });
            res.end(data);
        });
    } else {
        res.writeHead(404);
        res.end('Not Found');
    }
});

const wss = new WebSocket.Server({ server });

wss.on('connection', (ws) => {
    let currentRoom = null;
    let nickname = null;

    ws.on('message', (data) => {
        let message;
        try {
            message = JSON.parse(data);
        } catch (e) {
            ws.send(JSON.stringify({ type: 'error', content: 'Invalid JSON' }));
            return;
        }

        switch (message.type) {
            case 'join':
                // Leave previous room if any
                if (currentRoom) {
                    const prevRoomData = getRoom(currentRoom);
                    prevRoomData.users.delete(ws);
                    sendSystemMessage(currentRoom, `${nickname} left the room.`);
                }

                currentRoom = message.room || 'general';
                nickname = message.user || `Guest_${Math.floor(Math.random() * 1000)}`;

                const roomData = getRoom(currentRoom);
                roomData.users.set(ws, nickname);

                // Send history to the new user
                ws.send(JSON.stringify({
                    type: 'history',
                    room: currentRoom,
                    messages: roomData.messages
                }));

                sendSystemMessage(currentRoom, `${nickname} joined the room.`);
                break;

            case 'chat':
                if (!currentRoom || !nickname) return;

                const chatMessage = {
                    type: 'chat',
                    room: currentRoom,
                    user: nickname,
                    content: message.content,
                    timestamp: new Date().toISOString()
                };

                // Save to history
                roomData.messages.push(chatMessage);
                if (roomData.messages.length > MAX_HISTORY) {
                    roomData.messages.shift();
                }

                broadcastToRoom(currentRoom, chatMessage);
                break;

            case 'typing':
                if (!currentRoom || !nickname) return;
                broadcastToRoom(currentRoom, {
                    type: 'typing',
                    room: currentRoom,
                    user: nickname,
                    timestamp: new Date().toISOString()
                }, ws); // Exclude sender
                break;

            case 'leave':
                if (currentRoom) {
                    const roomData = getRoom(currentRoom);
                    roomData.users.delete(ws);
                    sendSystemMessage(currentRoom, `${nickname} left the room.`);
                    currentRoom = null;
                    nickname = null;
                }
                break;
        }
    });

    ws.on('close', () => {
        if (currentRoom && nickname) {
            const roomData = getRoom(currentRoom);
            roomData.users.delete(ws);
            sendSystemMessage(currentRoom, `${nickname} disconnected.`);
        }
    });

    ws.on('error', (err) => {
        console.error('WebSocket error:', err);
    });
});

server.listen(PORT, () => {
    console.log(`Server running at http://localhost:${PORT}`);
});
