            <button onclick="disconnect()" style="background:#dc3545;">Leave</button>
        </div>
        <div id="messages"></div>
        <div id="typing-indicator"></div>
        <input type="text" id="message-input" placeholder="Type a message..." onkeyup="handleTyping()">
        <button onclick="sendMessage()">Send</button>
    </div>
</div>

<script>
    let ws;
    let username = '';
    let currentRoom = '';
    let typingTimeout;

    const loginScreen = document.getElementById('login-screen');
    const chatScreen = document.getElementById('chat-screen');
    const messagesDiv = document.getElementById('messages');
    const typingDiv = document.getElementById('typing-indicator');
    const msgInput = document.getElementById('message-input');

    function connect() {
        username = document.getElementById('username-input').value.trim() || 'Guest';
        const room = document.getElementById('room-input').value.trim() || 'general';

        ws = new WebSocket(`ws://${location.host}`);

        ws.onopen = () => {
            loginScreen.classList.remove('active');
            chatScreen.classList.add('active');
            joinRoom(room);
        };

        ws.onmessage = (event) => {
            const data = JSON.parse(event.data);
            handleMessage(data);
        };

        ws.onclose = () => {
            alert('Disconnected from server');
            location.reload();
        };
    }

    function joinRoom(room) {
        currentRoom = room;
        messagesDiv.innerHTML = ''; // Clear UI for new room
        typingDiv.textContent = '';
        ws.send(JSON.stringify({ type: 'join', user: username, room: currentRoom }));
        document.getElementById('new-room-input').value = '';
    }

    function switchRoom() {
        const newRoom = document.getElementById('new-room-input').value.trim();
        if (newRoom && newRoom !== currentRoom) {
            joinRoom(newRoom);
        }
    }

    function disconnect() {
        if(ws) ws.send(JSON.stringify({ type: 'leave' }));
        ws.close();
    }

    function handleMessage(data) {
        if (data.type === 'history') {
            messagesDiv.innerHTML = '';
            data.messages.forEach(msg => renderMessage(msg));
            return;
        }

        if (data.room !== currentRoom) return;

        if (data.type === 'chat' || data.type === 'system') {
            renderMessage(data);
            scrollToBottom();
        } else if (data.type === 'typing') {
            showTyping(data.user);
        } else if (data.type === 'error') {
            alert(data.content);
        }
    }

    function renderMessage(msg) {
        const div = document.createElement('div');
        div.className = `message ${msg.type}`;

        const time = new Date(msg.timestamp).toLocaleTimeString();

        if (msg.type === 'system') {
            div.textContent = msg.content;
        } else {
            div.innerHTML = `
                <span class="meta">[${time}]</span>
                <span class="user">${escapeHtml(msg.user)}:</span>
                <span class="content">${escapeHtml(msg.content)}</span>
            `;
        }
        messagesDiv.appendChild(div);
    }

    function sendMessage() {
        const content = msgInput.value.trim();
        if (!content) return;

        ws.send(JSON.stringify({
            type: 'chat',
            content: content
        }));
        msgInput.value = '';
        ws.send(JSON.stringify({ type: 'typing', stop: true })); // Stop typing indicator
    }

    function handleTyping() {
        if (!ws || ws.readyState !== WebSocket.OPEN) return;

        ws.send(JSON.stringify({ type: 'typing' }));

        clearTimeout(typingTimeout);
        typingTimeout = setTimeout(() => {
            ws.send(JSON.stringify({ type: 'typing', stop: true }));
        }, 1000);
    }

    function showTyping(user) {
        if (user === username) return;
        typingDiv.textContent = `${user} is typing...`;
        clearTimeout(typingTimeout);
        typingTimeout = setTimeout(() => {
            typingDiv.textContent = '';
        }, 1500);
    }

    function scrollToBottom() {
        messagesDiv.scrollTop = messagesDiv.scrollHeight;
    }

    function escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    // Allow Enter key to send
    msgInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') sendMessage();
    });
</script>

</body>
</html>
