### How to Run

1.  Start the server:
    ```bash
    node server.js
    ```
2.  Open your browser and navigate to `http://localhost:8080`.
3.  Open multiple tabs or different browsers to simulate multiple users.
4.  Enter a nickname and room name to join.
5.  Try switching rooms, sending messages, and observing typing indicators.

### Features Implemented

*   **No Frameworks:** Uses only Node.js `http`, `fs`, `path` and the `ws` package.
*   **Rooms:** Users can join specific rooms. Messages are isolated per room.
*   **Nicknames:** Set upon joining.
*   **History:** The server stores the last 50 messages per room in memory. When a user joins, they immediately receive the history.
*   **Typing Indicators:** When a user types, others in the room see "User is typing..." for a short duration.
*   **System Messages:** Automatically broadcasts when users join, leave, or disconnect.
*   **JSON Protocol:** All communication is strictly typed JSON.
*   **Security:** Basic HTML escaping is implemented in the client to prevent XSS.

# WebSocket Chat Server with Multiple Rooms

## Server Code (`server.js`)

```javascript
const WebSocket = require('ws');
const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 3000;

// Create HTTP server to serve the client
const server = http.createServer((req, res) => {
  if (req.url === '/' || req.url === '/index.html') {
    fs.readFile(path.join(__dirname, 'client.html'), (err, data) => {
      if (err) {
        res.writeHead(500);
        res.end('Error loading client.html');
        return;
      }
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(data);
    });
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

// Create WebSocket server
const wss = new WebSocket.Server({ server });

// Data structures
const rooms = new Map(); // roomName -> { messages: [], users: Set() }
const clients = new Map(); // ws -> { nickname, currentRoom, typingTimeout }

// Initialize default rooms
['general', 'random', 'tech'].forEach(roomName => {
  rooms.set(roomName, { messages: [], users: new Set() });
});

// Helper functions
function getRoom(roomName) {
  if (!rooms.has(roomName)) {
    rooms.set(roomName, { messages: [], users: new Set() });
  }
  return rooms.get(roomName);
}

function addMessage(roomName, message) {
  const room = getRoom(roomName);
  room.messages.push(message);

  // Keep only last 50 messages
  if (room.messages.length > 50) {
    room.messages.shift();
  }
}

function broadcastToRoom(roomName, message, excludeWs = null) {
  const room = getRoom(roomName);

  clients.forEach((clientData, ws) => {
    if (ws !== excludeWs && 
        clientData.currentRoom === roomName && 
        ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify(message));
    }
  });
}

function sendToClient(ws, message) {
  if (ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify(message));
  }
}

function createMessage(type, room, user, content) {
  return {
    type,
    room,
    user,
    content,
    timestamp: new Date().toISOString()
  };
}

function getUsersInRoom(roomName) {
  const users = [];
  clients.forEach((clientData, ws) => {
    if (clientData.currentRoom === roomName) {
      users.push(clientData.nickname);
    }
  });
  return users;
}

function getRoomsList() {
  const roomsList = [];
  rooms.forEach((data, name) => {
    roomsList.push({
      name,
      userCount: getUsersInRoom(name).length
    });
  });
  return roomsList;
}

// WebSocket connection handler
wss.on('connection', (ws) => {
  console.log('New client connected');

  // Initialize client data
  clients.set(ws, {
    nickname: null,
    currentRoom: null,
    typingTimeout: null
  });

  ws.on('message', (data) => {
    try {
      const message = JSON.parse(data);
      const clientData = clients.get(ws);

      switch (message.type) {
        case 'set_nickname':
          handleSetNickname(ws, message.nickname);
          break;

        case 'join_room':
          handleJoinRoom(ws, message.room);
          break;

        case 'leave_room':
          handleLeaveRoom(ws);
          break;

        case 'chat_message':
          handleChatMessage(ws, message);
          break;

        case 'typing_start':
          handleTypingStart(ws);
          break;

        case 'typing_stop':
          handleTypingStop(ws);
          break;

        case 'get_rooms':
          handleGetRooms(ws);
          break;

        default:
          console.log('Unknown message type:', message.type);
      }
    } catch (error) {
      console.error('Error parsing message:', error);
    }
  });

  ws.on('close', () => {
    handleDisconnect(ws);
  });

  ws.on('error', (error) => {
    console.error('WebSocket error:', error);
  });

  // Send welcome message
  sendToClient(ws, {
    type: 'welcome',
    content: 'Welcome to the chat server! Please set your nickname.',
    timestamp: new Date().toISOString()
  });
});

// Message handlers
function handleSetNickname(ws, nickname) {
  const clientData = clients.get(ws);

  if (!nickname || nickname.trim().length === 0) {
    sendToClient(ws, {
      type: 'error',
      content: 'Nickname cannot be empty',
      timestamp: new Date().toISOString()
    });
    return;
  }

  // Check if nickname is already taken
  const nicknameTaken = Array.from(clients.values()).some(
    data => data.nickname === nickname.trim() && data !== clientData
  );

  if (nicknameTaken) {
    sendToClient(ws, {
      type: 'error',
      content: 'Nickname already taken',
      timestamp: new Date().toISOString()
    });
    return;
  }

  clientData.nickname = nickname.trim();

  sendToClient(ws, {
    type: 'nickname_set',
    nickname: clientData.nickname,
    timestamp: new Date().toISOString()
  });

  // Send available rooms
  handleGetRooms(ws);
}

function handleJoinRoom(ws, roomName) {
  const clientData = clients.get(ws);

  if (!clientData.nickname) {
    sendToClient(ws, {
      type: 'error',
      content: 'Please set a nickname first',
      timestamp: new Date().toISOString()
    });
    return;
  }

  // Leave current room if in one
  if (clientData.currentRoom) {
    handleLeaveRoom(ws);
  }

  // Join new room
  const room = getRoom(roomName);
  room.users.add(clientData.nickname);
  clientData.currentRoom = roomName;

  // Send room history to the user
  sendToClient(ws, {
    type: 'room_joined',
    room: roomName,
    messages: room.messages,
    users: getUsersInRoom(roomName),
    timestamp: new Date().toISOString()
  });

  // Broadcast system message to room
  const systemMessage = createMessage(
    'system',
    roomName,
    'System',
    `${clientData.nickname} joined the room`
  );

  addMessage(roomName, systemMessage);
  broadcastToRoom(roomName, systemMessage, ws);

  // Broadcast updated user list
  broadcastToRoom(roomName, {
    type: 'user_list',
    room: roomName,
    users: getUsersInRoom(roomName),
    timestamp: new Date().toISOString()
  });

  console.log(`${clientData.nickname} joined room: ${roomName}`);
}

function handleLeaveRoom(ws) {
  const clientData = clients.get(ws);

  if (!clientData.currentRoom) {
    return;
  }

  const roomName = clientData.currentRoom;
  const room = getRoom(roomName);

  room.users.delete(clientData.nickname);

  // Broadcast system message
  const systemMessage = createMessage(
    'system',
    roomName,
    'System',
    `${clientData.nickname} left the room`
  );

  addMessage(roomName, systemMessage);
  broadcastToRoom(roomName, systemMessage);

  // Broadcast updated user list
  broadcastToRoom(roomName, {
    type: 'user_list',
    room: roomName,
    users: getUsersInRoom(roomName),
    timestamp: new Date().toISOString()
  });

  clientData.currentRoom = null;

  sendToClient(ws, {
    type: 'room_left',
    room: roomName,
    timestamp: new Date().toISOString()
  });

  console.log(`${clientData.nickname} left room: ${roomName}`);
}

function handleChatMessage(ws, message) {
  const clientData = clients.get(ws);

  if (!clientData.currentRoom) {
    sendToClient(ws, {
      type: 'error',
      content: 'You must join a room first',
      timestamp: new Date().toISOString()
    });
    return;
  }

  if (!message.content || message.content.trim().length === 0) {
    return;
  }

  const chatMessage = createMessage(
    'chat',
    clientData.currentRoom,
    clientData.nickname,
    message.content.trim()
  );

  addMessage(clientData.currentRoom, chatMessage);

  // Send to sender
  sendToClient(ws, chatMessage);

  // Broadcast to room
  broadcastToRoom(clientData.currentRoom, chatMessage, ws);
}

function handleTypingStart(ws) {
  const clientData = clients.get(ws);

  if (!clientData.currentRoom) {
    return;
  }

  // Clear existing timeout
  if (clientData.typingTimeout) {
    clearTimeout(clientData.typingTimeout);
  }

  // Broadcast typing indicator
  broadcastToRoom(clientData.currentRoom, {
    type: 'typing',
    room: clientData.currentRoom,
    user: clientData.nickname,
    isTyping: true,
    timestamp: new Date().toISOString()
  }, ws);

  // Auto-stop typing after 3 seconds
  clientData.typingTimeout = setTimeout(() => {
    handleTypingStop(ws);
  }, 3000);
}

function handleTypingStop(ws) {
  const clientData = clients.get(ws);

  if (!clientData.currentRoom) {
    return;
  }

  if (clientData.typingTimeout) {
    clearTimeout(clientData.typingTimeout);
    clientData.typingTimeout = null;
  }

  broadcastToRoom(clientData.currentRoom, {
    type: 'typing',
    room: clientData.currentRoom,
    user: clientData.nickname,
    isTyping: false,
    timestamp: new Date().toISOString()
  }, ws);
}

function handleGetRooms(ws) {
  sendToClient(ws, {
    type: 'rooms_list',
    rooms: getRoomsList(),
    timestamp: new Date().toISOString()
  });
}

function handleDisconnect(ws) {
  const clientData = clients.get(ws);

  if (clientData) {
    if (clientData.currentRoom) {
      handleLeaveRoom(ws);
    }

    if (clientData.typingTimeout) {
      clearTimeout(clientData.typingTimeout);
    }

    console.log(`Client disconnected: ${clientData.nickname || 'unknown'}`);
  }

  clients.delete(ws);
}

// Start server
server.listen(PORT, () => {
  console.log(`Chat server running on http://localhost:${PORT}`);
});
