  <script>
    class ChatClient {
      constructor() {
        this.ws = null;
        this.nickname = null;
        this.currentRoom = null;
        this.typingUsers = new Set();
        this.typingTimeout = null;

        this.initializeElements();
        this.attachEventListeners();
        this.connect();
      }

      initializeElements() {
        // Screens
        this.nicknameScreen = document.getElementById('nickname-screen');
        this.chatScreen = document.getElementById('chat-screen');

        // Nickname screen
        this.nicknameInput = document.getElementById('nickname-input');
        this.setNicknameBtn = document.getElementById('set-nickname-btn');
        this.nicknameError = document.getElementById('nickname-error');

        // Chat screen
        this.currentUserEl = document.getElementById('current-user');
        this.roomsList = document.getElementById('rooms-list');
        this.usersList = document.getElementById('users-list');
        this.messagesContainer = document.getElementById('messages');
        this.typingIndicator = document.getElementById('typing-indicator');
        this.messageInput = document.getElementById('message-input');
        this.sendBtn = document.getElementById('send-btn');
      }

      attachEventListeners() {
        // Nickname screen
        this.setNicknameBtn.addEventListener('click', () => this.setNickname());
        this.nicknameInput.addEventListener('keypress', (e) => {
          if (e.key === 'Enter') this.setNickname();
        });

        // Chat screen
        this.sendBtn.addEventListener('click', () => this.sendMessage());
        this.messageInput.addEventListener('keypress', (e) => {
          if (e.key === 'Enter') this.sendMessage();
        });

        // Typing indicator
        this.messageInput.addEventListener('input', () => {
          this.handleTyping();
        });
      }

      connect() {
        const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        const wsUrl = `${protocol}//${window.location.host}`;

        this.ws = new WebSocket(wsUrl);

        this.ws.onopen = () => {
          console.log('Connected to server');
        };

        this.ws.onmessage = (event) => {
          const message = JSON.parse(event.data);
          this.handleMessage(message);
        };

        this.ws.onclose = () => {
          console.log('Disconnected from server');
          this.showError('Disconnected from server. Please refresh the page.');
        };

        this.ws.onerror = (error) => {
          console.error('WebSocket error:', error);
        };
      }

      handleMessage(message) {
        switch (message.type) {
          case 'welcome':
            console.log(message.content);
            break;

          case 'nickname_set':
            this.nickname = message.nickname;
            this.showChatScreen();
            break;

          case 'rooms_list':
            this.displayRooms(message.rooms);
            break;

          case 'room_joined':
            this.currentRoom = message.room;
            this.displayMessages(message.messages);
            this.displayUsers(message.users);
            this.enableChat();
            this.updateActiveRoom();
            break;

          case 'room_left':
            this.currentRoom = null;
            this.messagesContainer.innerHTML = '';
            this.usersList.innerHTML = '';
            this.disableChat();
            this.updateActiveRoom();
            break;

          case 'chat':
          case 'system':
            this.displayMessage(message);
            break;

          case 'user_list':
            if (message.room === this.currentRoom) {
              this.displayUsers(message.users);
            }
            break;

          case 'typing':
            this.handleTypingIndicator(message);
            break;

          case 'error':
            this.showError(message.content);
            break;
        }
      }

      setNickname() {
        const nickname = this.nicknameInput.value.trim();

        if (!nickname) {
          this.showNicknameError('Please enter a nickname');
          return;
        }

        this.send({
          type: 'set_nickname',
          nickname: nickname
        });
      }

      showChatScreen() {
        this.nicknameScreen.style.display = 'none';
        this.chatScreen.classList.add('active');
        this.currentUserEl.textContent = this.nickname;

        // Request rooms list
        this.send({ type: 'get_rooms' });
      }

      displayRooms(rooms) {
        this.roomsList.innerHTML = '';

        rooms.forEach(room => {
          const roomEl = document.createElement('div');
          roomEl.className = 'room-item';
          roomEl.innerHTML = `
            <span>${room.name}</span>
            <span class="user-count">${room.userCount} users</span>
          `;

          roomEl.addEventListener('click', () => {
            this.joinRoom(room.name);
          });

          this.roomsList.appendChild(roomEl);
        });
      }

      updateActiveRoom() {
        const roomItems = this.roomsList.querySelectorAll('.room-item');
        roomItems.forEach(item => {
          const roomName = item.querySelector('span').textContent;
          if (roomName === this.currentRoom) {
            item.classList.add('active');
          } else {
            item.classList.remove('active');
          }
        });
      }

      joinRoom(roomName) {
        this.send({
          type: 'join_room',
          room: roomName
        });
      }

      displayMessages(messages) {
        this.messagesContainer.innerHTML = '';
        messages.forEach(msg => this.displayMessage(msg));
        this.scrollToBottom();
      }

      displayMessage(message) {
        const messageEl = document.createElement('div');
        messageEl.className = `message ${message.type}`;

        const time = new Date(message.timestamp).toLocaleTimeString();

        if (message.type === 'system') {
          messageEl.innerHTML = `
            <div class="content">${message.content}</div>
          `;
        } else {
          messageEl.innerHTML = `
            <div class="meta">
              <span class="user">${message.user}</span>
              <span class="time">${time}</span>
            </div>
            <div class="content">${this.escapeHtml(message.content)}</div>
          `;
        }

        this.messagesContainer.appendChild(messageEl);
        this.scrollToBottom();
      }

      displayUsers(users) {
        this.usersList.innerHTML = '';
        users.forEach(user => {
          const userEl = document.createElement('div');
          userEl.className = 'user-item';
          userEl.textContent = user;
          this.usersList.appendChild(userEl);
        });
      }

      sendMessage() {
        const content = this.messageInput.value.trim();

        if (!content || !this.currentRoom) {
          return;
        }

        this.send({
          type: 'chat_message',
          content: content
        });

        this.messageInput.value = '';
        this.stopTyping();
      }

      handleTyping() {
        if (!this.currentRoom) return;

        // Send typing start
        this.send({ type: 'typing_start' });

        // Clear existing timeout
        if (this.typingTimeout) {
          clearTimeout(this.typingTimeout);
        }

        // Set timeout to stop typing
        this.typingTimeout = setTimeout(() => {
          this.stopTyping();
        }, 2000);
      }

      stopTyping() {
        if (this.typingTimeout) {
          clearTimeout(this.typingTimeout);
          this.typingTimeout = null;
        }

        if (this.currentRoom) {
          this.send({ type: 'typing_stop' });
        }
      }

      handleTypingIndicator(message) {
        if (message.isTyping) {
          this.typingUsers.add(message.user);
        } else {
          this.typingUsers.delete(message.user);
        }

        this.updateTypingIndicator();
      }

      updateTypingIndicator() {
        if (this.typingUsers.size === 0) {
          this.typingIndicator.textContent = '';
        } else if (this.typingUsers.size === 1) {
          const user = Array.from(this.typingUsers)[0];
          this.typingIndicator.textContent = `${user} is typing...`;
        } else if (this.typingUsers.size === 2) {
          const users = Array.from(this.typingUsers);
          this.typingIndicator.textContent = `${users[0]} and ${users[1]} are typing...`;
        } else {
          this.typingIndicator.textContent = 'Several people are typing...';
        }
      }

      enableChat() {
        this.messageInput.disabled = false;
        this.sendBtn.disabled = false;
        this.messageInput.focus();
      }

      disableChat() {
        this.messageInput.disabled = true;
        this.sendBtn.disabled = true;
      }

      send(data) {
        if (this.ws && this.ws.readyState === WebSocket.OPEN) {
          this.ws.send(JSON.stringify(data));
        }
      }

      scrollToBottom() {
        this.messagesContainer.scrollTop = this.messagesContainer.scrollHeight;
      }

      showError(message) {
        const errorEl = document.createElement('div');
        errorEl.className = 'error-message';
        errorEl.textContent = message;

        if (this.chatScreen.classList.contains('active')) {
          this.messagesContainer.insertBefore(errorEl, this.messagesContainer.firstChild);
          setTimeout(() => errorEl.remove(), 5000);
        }
      }

      showNicknameError(message) {
        this.nicknameError.textContent = message;
        this.nicknameError.style.display = 'block';
        setTimeout(() => {
          this.nicknameError.style.display = 'none';
        }, 3000);
      }

      escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
      }
    }

    // Initialize chat client
    const chat = new ChatClient();
  </script>
</body>
</html>
```

## Installation & Usage

