    """Format analysis results in specified format."""

    if output_format == 'json':
        result = {
            'total_files': stats.total_files,
            'total_size': stats.total_size,
            'total_size_formatted': format_size(stats.total_size),
            'count_by_extension': dict(stats.count_by_ext),
            'size_by_extension': {k: {'bytes': v, 'formatted': format_size(v)} 
                                  for k, v in stats.size_by_ext.items()},
            'largest_files': [{'path': p, 'size': s, 'size_formatted': format_size(s)} 
                             for p, s in stats.largest_files],
            'duplicates': {h: files for h, files in stats.duplicates.items()},
            'average_file_age_days': sum(stats.file_ages) / len(stats.file_ages) if stats.file_ages else 0
        }
