        lines.append("")

        # Summary
        lines.append(colorize("Summary:", Colors.BOLD + Colors.GREEN))
        lines.append(f"  Total Files: {colorize(str(stats.total_files), Colors.YELLOW)}")
        lines.append(f"  Total Size:  {colorize(format_size(stats.total_size), Colors.YELLOW)}")
        if stats.file_ages:
            avg_age = sum(stats.file_ages) / len(stats.file_ages)
            lines.append(f"  Average Age: {colorize(f'{avg_age:.2f} days', Colors.YELLOW)}")
        lines.append("")

