        for ext, count in sorted(stats.count_by_ext.items(), key=lambda x: x[1], reverse=True)[:10]:
            lines.append(f"  {ext:20s} {colorize(str(count), Colors.YELLOW):>10s}")
        lines.append("")

        # Size by extension
        lines.append(colorize("Total Size by Extension:", Colors.BOLD + Colors.GREEN))
        for ext, size in sorted(stats.size_by_ext.items(), key=lambda x: x[1], reverse=True)[:10]:
