        lines.append("")

        # Duplicates
        if stats.duplicates:
            lines.append(colorize(f"Duplicate Files ({len(stats.duplicates)} groups):", 
                                Colors.BOLD + Colors.GREEN))
            for i, (hash_val, files) in enumerate(list(stats.duplicates.items())[:5], 1):
                lines.append(f"  {colorize(f'Group {i}:', Colors.MAGENTA)} ({len(files)} files)")
                for file in files:
                    lines.append(f"    - {file}")
            if len(stats.duplicates) > 5:
                lines.append(f"  ... and {len(stats.duplicates) - 5} more groups")
        else:
            lines.append(colorize("No duplicate files found", Colors.GREEN))

        lines.append("")
        lines.append(colorize("=" * 80, Colors.BOLD))

        return '\n'.join(lines)


def compare_directories(path1: Path, path2: Path, exclude_patterns: List[str] = None) -> Dict:
    """Compare two directories and find differences."""
    if exclude_patterns is None:
        exclude_patterns = []

    progress = ProgressIndicator()

    def get_files_dict(base_path: Path) -> Dict[str, Tuple[int, str]]:
