```javascript
class EventEmitter {
  constructor() {
    // FIX 1: Prevent prototype pollution by using Object.create(null)
    // Without this, event names like '__proto__', 'toString', or 'constructor'
    // could access or modify Object prototype properties, leading to security issues.
    this.listeners = Object.create(null);
  }

  on(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
    return this; // Enables method chaining
  }

  off(event, callback) {
    if (this.listeners[event]) {
      // FIX 2: Use strict equality (!==) instead of loose equality (!=)
      // This ensures accurate function reference comparison.
      this.listeners[event] = this.listeners[event].filter(cb => cb !== callback);
    }
    // FIX 3: Return `this` for method chaining consistency with `on`
    return this;
  }

  emit(event, ...args) {
    if (this.listeners[event]) {
      // FIX 4: Copy the listeners array before iteration
      // Prevents issues if a callback modifies the listeners array during emission
      const listenersCopy = this.listeners[event].slice();
      listenersCopy.forEach(cb => cb(...args));
    }
  }

  once(event, callback) {
    // FIX 5: Create a wrapper that calls the callback once and then removes itself
    const wrapper = (...args) => {
      callback(...args);
      // FIX 6: Remove the wrapper function, not the original callback
      // The wrapper is what's actually registered, so it must be removed
      this.off(event, wrapper);
    };
    this.on(event, wrapper);
    // FIX 7: Return `this` for method chaining consistency
    return this;
  }
}

// Usage that should work:
const emitter = new EventEmitter();

let count = 0;
const increment = () => count++;
const decrement = () => count--;

emitter.on('tick', increment);
emitter.on('tick', decrement);
emitter.emit('tick');
console.log(count); // Should be 0

emitter.off('tick', decrement);
emitter.emit('tick');
console.log(count); // Should be 1

// once should fire exactly once
let onceCount = 0;
emitter.once('special', () => onceCount++);
emitter.emit('special');
emitter.emit('special');
console.log(onceCount); // Should be 1

// FIX 8: Prototype pollution attempt is now safely handled
// '__proto__' is treated as a regular event name, not a prototype property
emitter.on('__proto__', () => console.log('oops'));
emitter.emit('toString'); // No unintended side effects
```

### Summary of Bugs Fixed:

1. **Prototype Pollution Vulnerability** – Used `Object.create(null)` to prevent event names from accessing or modifying Object prototype properties.
2. **Loose Equality in `off`** – Replaced `!=` with `!==` for accurate function reference comparison.
3. **Missing Return in `off`** – Added `return this` to support method chaining.
4. **Unsafe Listeners Mutation During `emit`** – Copied the listeners array before iteration to avoid issues if callbacks modify the list.
5. **Incorrect Callback Removal in `once`** – Ensured the wrapper function (not the original callback) is removed after one invocation.
6. **Missing Return in `once`** – Added `return this` for chaining consistency.
7. **Security Hardening** – Event names like `'__proto__'` and `'toString'` are now safely handled without affecting the object's prototype.

These fixes ensure the EventEmitter is secure, consistent, and robust against common pitfalls.

