### 1. Server Code (`server.js`)

This server handles connection state, room management, message history, and broadcasting.

```javascript
const WebSocket = require('ws');

const wss = new WebSocket.Server({ port: 8080 });

// In-memory storage
const rooms = {}; // { roomId: [socket, socket, ...] }
const history = {}; // { roomId: [messageObj, messageObj, ...] }
const userSockets = new Map(); // { socket: nickname }

const MAX_HISTORY = 50;

wss.on('connection', (ws) => {
    console.log('New client connected');

    // Initialize socket state
    ws.nickname = null;
    ws.rooms = new Set();

    ws.on('message', (data) => {
        let message;
        try {
            message = JSON.parse(data);
        } catch (e) {
            ws.send(JSON.stringify({ type: 'error', content: 'Invalid JSON' }));
            return;
        }

        switch (message.type) {
            case 'set_nickname':
                ws.nickname = message.content;
                userSockets.set(ws, message.content);
                break;

            case 'join_room':
                handleJoinRoom(ws, message.room);
                break;

            case 'leave_room':
                handleLeaveRoom(ws, message.room);
                break;

            case 'chat_message':
                handleChatMessage(ws, message.room, message.content);
                break;

            case 'typing':
                handleTyping(ws, message.room);
                break;
        }
    });

    ws.on('close', () => {
        console.log('Client disconnected');
        // Remove from all rooms and notify
        ws.rooms.forEach(roomId => handleLeaveRoom(ws, roomId, true));
        userSockets.delete(ws);
    });
});

function handleJoinRoom(ws, roomId) {
    if (!ws.nickname) {
        ws.send(JSON.stringify({ type: 'error', content: 'Set a nickname first' }));
        return;
    }

    // Create room if it doesn't exist
    if (!rooms[roomId]) {
        rooms[roomId] = [];
        history[roomId] = [];
    }

    // Add user to room
    if (!rooms[roomId].includes(ws)) {
        rooms[roomId].push(ws);
        ws.rooms.add(roomId);
    }

    // Send existing history to the new user
    if (history[roomId].length > 0) {
        ws.send(JSON.stringify({
            type: 'history_update',
            room: roomId,
            messages: history[roomId]
        }));
    }

    // Broadcast system message
    broadcast(roomId, {
        type: 'system_message',
        room: roomId,
        content: `${ws.nickname} has joined the room`,
        timestamp: new Date().toISOString()
    }, ws);
}

function handleLeaveRoom(ws, roomId, isDisconnect = false) {
    if (!rooms[roomId]) return;

    // Remove socket from room array
    rooms[roomId] = rooms[roomId].filter(socket => socket !== ws);
    ws.rooms.delete(roomId);

    // Broadcast system message only if they were actually in the room and didn't just crash
    if (!isDisconnect || rooms[roomId].length > 0) {
        broadcast(roomId, {
            type: 'system_message',
            room: roomId,
            content: `${ws.nickname} has left the room`,
            timestamp: new Date().toISOString()
        });
    }

    // Clean up empty rooms
    if (rooms[roomId].length === 0) {
        delete rooms[roomId];
        delete history[roomId];
    }
}

function handleChatMessage(ws, roomId, content) {
    if (!ws.rooms.has(roomId)) return;

    const messageObj = {
        type: 'chat_message',
        room: roomId,
        user: ws.nickname,
        content: content,
        timestamp: new Date().toISOString()
    };

    // Add to history
    if (!history[roomId]) history[roomId] = [];
    history[roomId].unshift(messageObj); // Add to beginning

    // Limit history size
    if (history[roomId].length > MAX_HISTORY) {
        history[roomId].pop();
    }

    // Broadcast to room
    broadcast(roomId, messageObj);
}

function handleTyping(ws, roomId) {
    if (!ws.rooms.has(roomId)) return;

    // Broadcast typing indicator (exclude sender)
    broadcast(roomId, {
        type: 'typing',
        room: roomId,
        user: ws.nickname
    }, ws);
}

function broadcast(roomId, data, excludeSocket = null) {
    if (!rooms[roomId]) return;

    const payload = JSON.stringify(data);
    rooms[roomId].forEach(client => {
        if (client !== excludeSocket && client.readyState === WebSocket.OPEN) {
            client.send(payload);
        }
    });
}

console.log('WebSocket server running on ws://localhost:8080');
```

