        if (!nickname || !currentRoom) return alert('Please fill in all fields');

        ws = new WebSocket('ws://localhost:8080');

        ws.onopen = () => {
            // Set nickname
            ws.send(JSON.stringify({ type: 'set_nickname', content: nickname }));
            // Join room
