        const messagesDiv = document.getElementById('messages');

        if (data.type === 'history_update') {
            messagesDiv.innerHTML = ''; // Clear current
            // History comes newest first, reverse for display
            data.messages.slice().reverse().forEach(msg => renderMessage(msg));
            return;
        }

        if (data.type === 'chat_message' || data.type === 'system_message') {
            renderMessage(data);
            // Auto scroll to bottom
            messagesDiv.scrollTop = messagesDiv.scrollHeight;
        }

        if (data.type === 'typing') {
            const indicator = document.getElementById('typing-indicator');
            indicator.textContent = `${data.user} is typing...`;
            setTimeout(() => { indicator.textContent = ''; }, 2000);
        }

        if (data.type === 'error') {
            alert('Server Error: ' + data.content);
        }
    }

    function renderMessage(msg) {
        const messagesDiv = document.getElementById('messages');
        const div = document.createElement('div');

        if (msg.type === 'system_message') {
            div.className = 'msg system';
            div.textContent = msg.content;
        } else {
            div.className = 'msg chat';
            const time = new Date(msg.timestamp).toLocaleTimeString();
            div.innerHTML = `
                <div class="meta"><b>${msg.user}</b> • ${time}</div>
                <div>${escapeHtml(msg.content)}</div>
            `;
        }
        messagesDiv.appendChild(div);
    }

    function sendMessage() {
        const input = document.getElementById('message-input');
        const content = input.value.trim();
        if (!content) return;

        ws.send(JSON.stringify({
            type: 'chat_message',
            room: currentRoom,
            content: content
        }));
        input.value = '';
    }

    function handleTyping() {
        ws.send(JSON.stringify({
            type: 'typing',
            room: currentRoom
        }));
    }

    function leaveRoom() {
        ws.send(JSON.stringify({ type: 'leave_room', room: currentRoom }));
        document.getElementById('messages').innerHTML = '<div style="text-align:center; color:#888; margin-top:20px;">You left the room.</div>';
        document.getElementById('message-input').disabled = true;
    }

    // Security helper
    function escapeHtml(text) {
        return text
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }

    // Allow Enter key to send
    document.getElementById('message-input').addEventListener('keypress', function (e) {
        if (e.key === 'Enter') sendMessage();
    });
</script>

