            if (err) {
                res.writeHead(500);
                res.end('Error loading client');
                return;
            }
            res.writeHead(200, { 'Content-Type': 'text/html' });
            res.end(data);
        });
    } else {
        res.writeHead(404);
        res.end('Not found');
    }
});

// Create WebSocket server
const wss = new WebSocket.Server({ server });

// In-memory storage
const rooms = new Map(); // roomName -> Set of client IDs
const clients = new Map(); // clientId -> { ws, nickname, currentRoom, isTyping }
const messageHistory = new Map(); // roomName -> Array of messages (max 50)
const typingTimeouts = new Map(); // clientId -> timeout

// Generate unique client ID
let clientIdCounter = 0;
function generateClientId() {
    return `client_${++clientIdCounter}_${Date.now()}`;
}

// Get or create room
function getRoom(roomName) {
    if (!rooms.has(roomName)) {
        rooms.set(roomName, new Set());
        messageHistory.set(roomName, []);
    }
    return rooms.get(roomName);
}

// Add message to history (keep last 50)
function addToHistory(roomName, message) {
    if (!messageHistory.has(roomName)) {
        messageHistory.set(roomName, []);
    }
    const history = messageHistory.get(roomName);
    history.push(message);
    if (history.length > 50) {
        history.shift();
    }
}

// Create message object
function createMessage(type, room, user, content) {
    return {
        type,
        room,
        user,
        content,
        timestamp: new Date().toISOString()
    };
}

// Broadcast to room
function broadcastToRoom(roomName, message, excludeClientId = null) {
    const room = rooms.get(roomName);
    if (!room) return;

    const messageStr = JSON.stringify(message);
    room.forEach(clientId => {
        if (clientId !== excludeClientId) {
            const client = clients.get(clientId);
            if (client && client.ws.readyState === WebSocket.OPEN) {
                client.ws.send(messageStr);
            }
        }
    });
}

// Send to specific client
function sendToClient(clientId, message) {
    const client = clients.get(clientId);
    if (client && client.ws.readyState === WebSocket.OPEN) {
        client.ws.send(JSON.stringify(message));
    }
}

// Get users in room
function getRoomUsers(roomName) {
    const room = rooms.get(roomName);
    if (!room) return [];

    const users = [];
    room.forEach(clientId => {
        const client = clients.get(clientId);
        if (client) {
            users.push({
                id: clientId,
                nickname: client.nickname,
                isTyping: client.isTyping
            });
        }
    });
    return users;
}

// Get available rooms with user counts
function getAvailableRooms() {
    const roomList = [];
    rooms.forEach((clientSet, roomName) => {
        roomList.push({
            name: roomName,
            userCount: clientSet.size
        });
    });
    return roomList;
}

// Handle client joining a room
function joinRoom(clientId, roomName) {
    const client = clients.get(clientId);
    if (!client) return;

    // Leave current room if in one
    if (client.currentRoom) {
        leaveRoom(clientId);
    }

    // Join new room
    const room = getRoom(roomName);
    room.add(clientId);
    client.currentRoom = roomName;

    // Send room history to client
    const history = messageHistory.get(roomName) || [];
    sendToClient(clientId, {
        type: 'history',
        room: roomName,
        messages: history
    });

    // Send current users list
    sendToClient(clientId, {
        type: 'userList',
        room: roomName,
        users: getRoomUsers(roomName)
    });

    // Broadcast join message
    const joinMessage = createMessage('system', roomName, 'System', 
        `${client.nickname} has joined the room`);
    addToHistory(roomName, joinMessage);
    broadcastToRoom(roomName, joinMessage, clientId);

    // Notify client of successful join
    sendToClient(clientId, {
        type: 'joinedRoom',
        room: roomName,
        user: client.nickname
    });

    // Broadcast updated user list to room
    broadcastToRoom(roomName, {
        type: 'userList',
        room: roomName,
        users: getRoomUsers(roomName)
    });

    console.log(`${client.nickname} joined room: ${roomName}`);
}

// Handle client leaving a room
function leaveRoom(clientId) {
    const client = clients.get(clientId);
    if (!client || !client.currentRoom) return;

    const roomName = client.currentRoom;
    const room = rooms.get(roomName);

    if (room) {
        room.delete(clientId);

        // Broadcast leave message
        const leaveMessage = createMessage('system', roomName, 'System',
            `${client.nickname} has left the room`);
        addToHistory(roomName, leaveMessage);
        broadcastToRoom(roomName, leaveMessage);

        // Broadcast updated user list
        broadcastToRoom(roomName, {
            type: 'userList',
            room: roomName,
            users: getRoomUsers(roomName)
        });

        // Clean up empty rooms (except default ones)
        if (room.size === 0 && !['general', 'random', 'tech'].includes(roomName)) {
            rooms.delete(roomName);
            messageHistory.delete(roomName);
        }
    }

    client.currentRoom = null;
    client.isTyping = false;
    clearTypingTimeout(clientId);

    console.log(`${client.nickname} left room: ${roomName}`);
}

// Handle typing indicator
function clearTypingTimeout(clientId) {
    if (typingTimeouts.has(clientId)) {
        clearTimeout(typingTimeouts.get(clientId));
        typingTimeouts.delete(clientId);
    }
}

function handleTyping(clientId, isTyping) {
    const client = clients.get(clientId);
    if (!client || !client.currentRoom) return;

    clearTypingTimeout(clientId);

    client.isTyping = isTyping;

    if (isTyping) {
        // Auto-clear typing after 3 seconds
        typingTimeouts.set(clientId, setTimeout(() => {
            client.isTyping = false;
            broadcastTypingStatus(client.currentRoom);
        }, 3000));
    }

    broadcastTypingStatus(client.currentRoom);
}

function broadcastTypingStatus(roomName) {
    const room = rooms.get(roomName);
    if (!room) return;

    const typingUsers = [];
    room.forEach(clientId => {
        const client = clients.get(clientId);
        if (client && client.isTyping) {
            typingUsers.push(client.nickname);
        }
    });

    broadcastToRoom(roomName, {
        type: 'typing',
        room: roomName,
        users: typingUsers
    });
}

// Handle chat message
function handleChatMessage(clientId, content) {
    const client = clients.get(clientId);
    if (!client || !client.currentRoom) {
        sendToClient(clientId, {
            type: 'error',
            content: 'You must join a room first'
        });
        return;
    }

    // Clear typing status
    client.isTyping = false;
    clearTypingTimeout(clientId);
    broadcastTypingStatus(client.currentRoom);

    const message = createMessage('message', client.currentRoom, client.nickname, content);
    addToHistory(client.currentRoom, message);
    broadcastToRoom(client.currentRoom, message);
}

// Handle nickname change
function handleNicknameChange(clientId, newNickname) {
    const client = clients.get(clientId);
    if (!client) return;

    const oldNickname = client.nickname;
    client.nickname = newNickname.trim().substring(0, 20) || oldNickname;

    if (client.currentRoom) {
        const message = createMessage('system', client.currentRoom, 'System',
            `${oldNickname} is now known as ${client.nickname}`);
        addToHistory(client.currentRoom, message);
        broadcastToRoom(client.currentRoom, message);

        // Update user list
        broadcastToRoom(client.currentRoom, {
            type: 'userList',
            room: client.currentRoom,
            users: getRoomUsers(client.currentRoom)
        });
    }

    sendToClient(clientId, {
        type: 'nicknameChanged',
        user: client.nickname
    });
}

// Initialize default rooms
['general', 'random', 'tech'].forEach(roomName => {
    rooms.set(roomName, new Set());
    messageHistory.set(roomName, []);
});

// WebSocket connection handler
wss.on('connection', (ws, req) => {
    const clientId = generateClientId();
    const defaultNickname = `User${clientIdCounter}`;

    // Store client info
    clients.set(clientId, {
        ws,
        nickname: defaultNickname,
        currentRoom: null,
        isTyping: false
    });

    console.log(`Client connected: ${clientId} (${defaultNickname})`);

    // Send welcome message with client info
    sendToClient(clientId, {
        type: 'welcome',
        clientId,
        nickname: defaultNickname,
        rooms: getAvailableRooms()
    });

    // Handle incoming messages
    ws.on('message', (data) => {
        try {
            const message = JSON.parse(data.toString());

            switch (message.type) {
                case 'setNickname':
                    handleNicknameChange(clientId, message.nickname);
                    break;

                case 'join':
                    if (message.room) {
                        joinRoom(clientId, message.room.toLowerCase().trim());
                    }
                    break;

                case 'leave':
                    leaveRoom(clientId);
                    sendToClient(clientId, {
                        type: 'leftRoom',
                        rooms: getAvailableRooms()
                    });
                    break;

                case 'message':
                    if (message.content && message.content.trim()) {
                        handleChatMessage(clientId, message.content.trim());
                    }
                    break;

                case 'typing':
                    handleTyping(clientId, message.isTyping);
                    break;

                case 'getRooms':
                    sendToClient(clientId, {
                        type: 'roomList',
                        rooms: getAvailableRooms()
                    });
                    break;

                case 'createRoom':
                    if (message.room) {
                        const roomName = message.room.toLowerCase().trim().substring(0, 30);
                        if (roomName && !rooms.has(roomName)) {
                            getRoom(roomName);
                        }
                        joinRoom(clientId, roomName);
                    }
                    break;

                default:
                    sendToClient(clientId, {
                        type: 'error',
                        content: `Unknown message type: ${message.type}`
                    });
            }
        } catch (error) {
            console.error('Error processing message:', error);
            sendToClient(clientId, {
                type: 'error',
                content: 'Invalid message format'
            });
        }
    });

    // Handle client disconnect
    ws.on('close', () => {
        console.log(`Client disconnected: ${clientId}`);
        leaveRoom(clientId);
        clearTypingTimeout(clientId);
        clients.delete(clientId);
    });

    // Handle errors
    ws.on('error', (error) => {
        console.error(`WebSocket error for ${clientId}:`, error);
    });
});

// Start server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Chat server running on http://localhost:${PORT}`);
    console.log(`WebSocket server ready on ws://localhost:${PORT}`);
});

// Graceful shutdown
process.on('SIGINT', () => {
    console.log('\nShutting down server...');
    wss.clients.forEach(client => {
        client.close();
    });
    server.close(() => {
        console.log('Server closed');
        process.exit(0);
    });
});
