                <div class="message-input-container">
                    <form class="message-form" id="messageForm">
                        <input type="text" id="messageInput" placeholder="Type a message..." autocomplete="off" maxlength="1000">
                        <button type="submit" id="sendBtn" disabled>Send</button>
                    </form>
                </div>
            </div>
        </main>

        <!-- Users Panel -->
        <aside class="users-panel" id="usersPanel" style="display: none;">
            <h3>Online — <span id="userCount">0</span></h3>
            <ul class="user-list" id="userList">
                <!-- Users will be populated here -->
            </ul>
        </aside>
    </div>

    <script>
        // Chat Application
        class ChatApp {
            constructor() {
                this.ws = null;
                this.clientId = null;
                this.nickname = '';
                this.currentRoom = null;
                this.reconnectAttempts = 0;
                this.maxReconnectAttempts = 5;
                this.typingTimeout = null;
                this.isTyping = false;

                this.initElements();
                this.initEventListeners();
                this.connect();
            }

            initElements() {
                this.connectionStatus = document.getElementById('connectionStatus');
                this.nicknameInput = document.getElementById('nicknameInput');
                this.userAvatar = document.getElementById('userAvatar');
                this.roomList = document.getElementById('roomList');
                this.createRoomForm = document.getElementById('createRoomForm');
                this.newRoomInput = document.getElementById('newRoomInput');
                this.welcomeScreen = document.getElementById('welcomeScreen');
                this.chatInterface = document.getElementById('chatInterface');
                this.currentRoomName = document.getElementById('currentRoomName');
                this.leaveBtn = document.getElementById('leaveBtn');
                this.messagesContainer = document.getElementById('messagesContainer');
                this.typingIndicator = document.getElementById('typingIndicator');
                this.messageForm = document.getElementById('messageForm');
                this.messageInput = document.getElementById('messageInput');
                this.sendBtn = document.getElementById('sendBtn');
                this.usersPanel = document.getElementById('usersPanel');
                this.userList = document.getElementById('userList');
                this.userCount = document.getElementById('userCount');
            }

            initEventListeners() {
                // Nickname change
                this.nicknameInput.addEventListener('change', () => {
                    const newNickname = this.nicknameInput.value.trim();
                    if (newNickname && newNickname !== this.nickname) {
                        this.send({ type: 'setNickname', nickname: newNickname });
                    }
                });

                // Create room
                this.createRoomForm.addEventListener('submit', (e) => {
                    e.preventDefault();
                    const roomName = this.newRoomInput.value.trim();
                    if (roomName) {
                        this.send({ type: 'createRoom', room: roomName });
                        this.newRoomInput.value = '';
                    }
                });

                // Leave room
                this.leaveBtn.addEventListener('click', () => {
                    this.send({ type: 'leave' });
                });

                // Send message
                this.messageForm.addEventListener('submit', (e) => {
                    e.preventDefault();
                    const content = this.messageInput.value.trim();
                    if (content) {
                        this.send({ type: 'message', content });
                        this.messageInput.value = '';
                        this.sendBtn.disabled = true;
                        this.stopTyping();
                    }
                });

                // Message input
                this.messageInput.addEventListener('input', () => {
                    this.sendBtn.disabled = !this.messageInput.value.trim();
                    this.handleTyping();
                });

                // Stop typing on blur
                this.messageInput.addEventListener('blur', () => {
                    this.stopTyping();
                });
            }

            connect() {
                const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
                const wsUrl = `${protocol}//${window.location.host}`;

                this.updateConnectionStatus('connecting');

                this.ws = new WebSocket(wsUrl);

                this.ws.onopen = () => {
                    console.log('Connected to server');
                    this.updateConnectionStatus('connected');
                    this.reconnectAttempts = 0;
                };

                this.ws.onmessage = (event) => {
                    try {
                        const message = JSON.parse(event.data);
                        this.handleMessage(message);
                    } catch (error) {
                        console.error('Error parsing message:', error);
                    }
                };

                this.ws.onclose = () => {
                    console.log('Disconnected from server');
                    this.updateConnectionStatus('disconnected');
                    this.attemptReconnect();
                };

                this.ws.onerror = (error) => {
                    console.error('WebSocket error:', error);
                };
            }

            attemptReconnect() {
                if (this.reconnectAttempts < this.maxReconnectAttempts) {
                    this.reconnectAttempts++;
                    const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempts), 30000);
                    console.log(`Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts})`);
                    setTimeout(() => this.connect(), delay);
                }
            }

            updateConnectionStatus(status) {
                this.connectionStatus.className = `connection-status ${status}`;
                const statusText = {
                    connected: 'Connected',
                    disconnected: 'Disconnected',
                    connecting: 'Connecting...'
                };
                this.connectionStatus.innerHTML = `
                    <span class="status-indicator"></span>
                    <span>${statusText[status]}</span>
                `;
            }

            send(data) {
                if (this.ws && this.ws.readyState === WebSocket.OPEN) {
                    this.ws.send(JSON.stringify(data));
                }
            }

            handleMessage(message) {
                switch (message.type) {
                    case 'welcome':
                        this.handleWelcome(message);
                        break;
                    case 'roomList':
                        this.updateRoomList(message.rooms);
                        break;
                    case 'joinedRoom':
                        this.handleJoinedRoom(message);
                        break;
                    case 'leftRoom':
                        this.handleLeftRoom(message);
                        break;
                    case 'history':
                        this.handleHistory(message);
                        break;
                    case 'message':
                    case 'system':
                        this.addMessage(message);
                        break;
                    case 'userList':
                        this.updateUserList(message.users);
                        break;
                    case 'typing':
                        this.updateTypingIndicator(message.users);
                        break;
                    case 'nicknameChanged':
                        this.handleNicknameChanged(message);
                        break;
                    case 'error':
                        this.showError(message.content);
                        break;
                }
            }

            handleWelcome(message) {
                this.clientId = message.clientId;
                this.nickname = message.nickname;
                this.nicknameInput.value = this.nickname;
                this.userAvatar.textContent = this.nickname.charAt(0).toUpperCase();
                this.updateRoomList(message.rooms);
            }

            handleNicknameChanged(message) {
                this.nickname = message.user;
                this.nicknameInput.value = this.nickname;
                this.userAvatar.textContent = this.nickname.charAt(0).toUpperCase();
            }

            updateRoomList(rooms) {
                this.roomList.innerHTML = rooms.map(room => `
                    <li class="room-item ${this.currentRoom === room.name ? 'active' : ''}" 
                        data-room="${room.name}">
                        <span class="room-name">${this.escapeHtml(room.name)}</span>
                        <span class="user-count">${room.userCount}</span>
                    </li>
                `).join('');

                // Add click handlers
                this.roomList.querySelectorAll('.room-item').forEach(item => {
                    item.addEventListener('click', () => {
                        const roomName = item.dataset.room;
                        if (roomName !== this.currentRoom) {
                            this.send({ type: 'join', room: roomName });
                        }
                    });
                });
            }

            handleJoinedRoom(message) {
                this.currentRoom = message.room;
                this.currentRoomName.textContent = message.room;
                this.welcomeScreen.style.display = 'none';
                this.chatInterface.style.display = 'flex';
                this.usersPanel.style.display = 'block';
                this.messagesContainer.innerHTML = '';
                this.messageInput.focus();

                // Update room list to show active room
                this.roomList.querySelectorAll('.room-item').forEach(item => {
                    item.classList.toggle('active', item.dataset.room === this.currentRoom);
                });
            }

            handleLeftRoom(message) {
                this.currentRoom = null;
                this.welcomeScreen.style.display = 'flex';
                this.chatInterface.style.display = 'none';
                this.usersPanel.style.display = 'none';
                this.updateRoomList(message.rooms);
            }

            handleHistory(message) {
                message.messages.forEach(msg => this.addMessage(msg, false));
                this.scrollToBottom();
            }

            addMessage(message, scroll = true) {
                const messageEl = document.createElement('div');
                messageEl.className = `message ${message.type}`;

                const time = new Date(message.timestamp).toLocaleTimeString([], { 
                    hour: '2-digit', 
                    minute: '2-digit' 
                });

                if (message.type === 'system') {
                    messageEl.innerHTML = `
                        <div class="message-content">${this.escapeHtml(message.content)}</div>
                    `;
                } else {
                    const avatarLetter = message.user.charAt(0).toUpperCase();
                    messageEl.innerHTML = `
                        <div class="message-header">
                            <div class="message-avatar">${avatarLetter}</div>
                            <span class="message-user">${this.escapeHtml(message.user)}</span>
                            <span class="message-time">${time}</span>
                        </div>
                        <div class="message-content">${this.escapeHtml(message.content)}</div>
                    `;
                }

                this.messagesContainer.appendChild(messageEl);

                if (scroll) {
                    this.scrollToBottom();
                }
            }

            updateUserList(users) {
                this.userCount.textContent = users.length;
                this.userList.innerHTML = users.map(user => `
                    <li class="user-list-item ${user.isTyping ? 'typing' : ''}">
                        <span class="status-dot"></span>
                        <span>${this.escapeHtml(user.nickname)}</span>
                    </li>
                `).join('');
            }

            updateTypingIndicator(users) {
                // Filter out current user
                const typingUsers = users.filter(u => u !== this.nickname);

                if (typingUsers.length === 0) {
                    this.typingIndicator.innerHTML = '';
                } else if (typingUsers.length === 1) {
                    this.typingIndicator.innerHTML = `
                        ${this.escapeHtml(typingUsers[0])} is typing
                        <span class="dots"><span>.</span><span>.</span><span>.</span></span>
                    `;
                } else if (typingUsers.length === 2) {
                    this.typingIndicator.innerHTML = `
                        ${this.escapeHtml(typingUsers[0])} and ${this.escapeHtml(typingUsers[1])} are typing
                        <span class="dots"><span>.</span><span>.</span><span>.</span></span>
                    `;
                } else {
                    this.typingIndicator.innerHTML = `
                        ${typingUsers.length} people are typing
                        <span class="dots"><span>.</span><span>.</span><span>.</span></span>
                    `;
                }
            }

            handleTyping() {
                if (!this.isTyping) {
                    this.isTyping = true;
                    this.send({ type: 'typing', isTyping: true });
                }

                // Reset typing timeout
                clearTimeout(this.typingTimeout);
                this.typingTimeout = setTimeout(() => {
                    this.stopTyping();
                }, 2000);
            }

            stopTyping() {
                if (this.isTyping) {
                    this.isTyping = false;
                    this.send({ type: 'typing', isTyping: false });
                }
                clearTimeout(this.typingTimeout);
            }

            scrollToBottom() {
                this.messagesContainer.scrollTop = this.messagesContainer.scrollHeight;
            }

            showError(message) {
                console.error('Error:', message);
                // Could add a toast notification here
            }

            escapeHtml(text) {
                const div = document.createElement('div');
                div.textContent = text;
                return div.innerHTML;
            }
        }

        // Initialize app when DOM is ready
        document.addEventListener('DOMContentLoaded', () => {
            window.chatApp = new ChatApp();
        });
    </script>
</body>
</html>
