# WebSocket Chat Server with Multiple Rooms

## Server Code (`server.js`)

```javascript
const { WebSocketServer, WebSocket } = require('ws');
const http = require('http');
const fs = require('fs');
const path = require('path');

// --- Configuration ---
const PORT = 8080;
const MAX_HISTORY = 50;
const TYPING_TIMEOUT_MS = 3000;

// --- State ---
const rooms = new Map();          // roomName -> { clients: Set<ws>, history: [], typingUsers: Map<ws, timeout> }
const clients = new Map();        // ws -> { nickname, currentRoom }

// --- Room Management ---
function getOrCreateRoom(roomName) {
  if (!rooms.has(roomName)) {
    rooms.set(roomName, {
      clients: new Set(),
      history: [],
      typingUsers: new Map(),
    });
  }
  return rooms.get(roomName);
}

function addMessageToHistory(roomName, message) {
  const room = getOrCreateRoom(roomName);
  room.history.push(message);
  if (room.history.length > MAX_HISTORY) {
    room.history.shift();
  }
}

function broadcastToRoom(roomName, message, excludeWs = null) {
  const room = rooms.get(roomName);
  if (!room) return;

  const payload = JSON.stringify(message);
  for (const client of room.clients) {
    if (client !== excludeWs && client.readyState === WebSocket.OPEN) {
      client.send(payload);
    }
  }
}

function sendToClient(ws, message) {
  if (ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify(message));
  }
}

function createSystemMessage(roomName, content) {
  return {
    type: 'system',
    room: roomName,
    user: null,
    content,
    timestamp: Date.now(),
  };
}

function createChatMessage(roomName, user, content) {
  return {
    type: 'message',
    room: roomName,
    user,
    content,
    timestamp: Date.now(),
  };
}

function getTypingUsers(roomName, excludeWs = null) {
  const room = rooms.get(roomName);
  if (!room) return [];

  const users = [];
  for (const [ws] of room.typingUsers) {
    if (ws !== excludeWs) {
      const clientInfo = clients.get(ws);
      if (clientInfo) users.push(clientInfo.nickname);
    }
  }
  return users;
}

function broadcastTypingIndicator(roomName, excludeWs = null) {
  const room = rooms.get(roomName);
  if (!room) return;

  // Build per-client typing lists (each client sees everyone else typing, not themselves)
  for (const client of room.clients) {
    if (client.readyState === WebSocket.OPEN) {
      const typingUsers = getTypingUsers(roomName, client);
      sendToClient(client, {
        type: 'typing',
        room: roomName,
        user: null,
        content: typingUsers,
        timestamp: Date.now(),
      });
    }
  }
}

function clearTyping(ws, roomName) {
  const room = rooms.get(roomName);
  if (!room) return;

  const existingTimeout = room.typingUsers.get(ws);
  if (existingTimeout) {
    clearTimeout(existingTimeout);
    room.typingUsers.delete(ws);
    broadcastTypingIndicator(roomName);
  }
}

function joinRoom(ws, roomName) {
  const clientInfo = clients.get(ws);
  if (!clientInfo) return;

  // Leave current room first
  if (clientInfo.currentRoom) {
    leaveRoom(ws);
  }

  const room = getOrCreateRoom(roomName);
  room.clients.add(ws);
  clientInfo.currentRoom = roomName;

  // Send room history to the joining client
  sendToClient(ws, {
    type: 'history',
    room: roomName,
    user: null,
    content: room.history,
    timestamp: Date.now(),
  });

  // Send current room user list
  broadcastUserList(roomName);

  // Broadcast system message
  const sysMsg = createSystemMessage(roomName, `${clientInfo.nickname} joined the room.`);
  addMessageToHistory(roomName, sysMsg);
  broadcastToRoom(roomName, sysMsg, ws);

  // Confirm join to the client
  sendToClient(ws, {
    type: 'joined',
    room: roomName,
    user: clientInfo.nickname,
    content: `You joined #${roomName}`,
    timestamp: Date.now(),
  });

  console.log(`[${clientInfo.nickname}] joined #${roomName} (${room.clients.size} users)`);
}

function leaveRoom(ws) {
  const clientInfo = clients.get(ws);
  if (!clientInfo || !clientInfo.currentRoom) return;

  const roomName = clientInfo.currentRoom;
  const room = rooms.get(roomName);
  if (!room) return;

  // Clear typing indicator
  clearTyping(ws, roomName);

  // Remove from room
  room.clients.delete(ws);
  clientInfo.currentRoom = null;

  // Broadcast system message
  const sysMsg = createSystemMessage(roomName, `${clientInfo.nickname} left the room.`);
  addMessageToHistory(roomName, sysMsg);
  broadcastToRoom(roomName, sysMsg);

  // Update user list
  broadcastUserList(roomName);

  console.log(`[${clientInfo.nickname}] left #${roomName} (${room.clients.size} users)`);

  // Clean up empty rooms
  if (room.clients.size === 0) {
    rooms.delete(roomName);
    console.log(`Room #${roomName} deleted (empty)`);
  }
}

function broadcastUserList(roomName) {
  const room = rooms.get(roomName);
  if (!room) return;

  const users = [];
  for (const client of room.clients) {
    const info = clients.get(client);
    if (info) users.push(info.nickname);
  }

  broadcastToRoom(roomName, {
    type: 'userlist',
    room: roomName,
    user: null,
    content: users,
    timestamp: Date.now(),
  });
}

function getRoomList() {
  const list = [];
  for (const [name, room] of rooms) {
    list.push({ name, users: room.clients.size });
  }
  return list;
}

// --- HTTP Server (serves the client HTML) ---
const httpServer = http.createServer((req, res) => {
  if (req.url === '/' || req.url === '/index.html') {
    fs.readFile(path.join(__dirname, 'client.html'), (err, data) => {
      if (err) {
        res.writeHead(500);
        res.end('Error loading client');
        return;
      }
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(data);
    });
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

// --- WebSocket Server ---
const wss = new WebSocketServer({ server: httpServer });

wss.on('connection', (ws) => {
  console.log('New WebSocket connection');

  // Client starts without a nickname — must set one first
  clients.set(ws, { nickname: null, currentRoom: null });

  sendToClient(ws, {
    type: 'welcome',
    room: null,
    user: null,
    content: 'Welcome! Please set your nickname using {"type":"setNick","content":"yourname"}',
    timestamp: Date.now(),
  });

  ws.on('message', (raw) => {
    let data;
    try {
      data = JSON.parse(raw.toString());
    } catch {
      sendToClient(ws, {
        type: 'error',
        room: null,
        user: null,
        content: 'Invalid JSON',
        timestamp: Date.now(),
      });
      return;
    }

    const clientInfo = clients.get(ws);
    if (!clientInfo) return;

    switch (data.type) {
      // --- Set Nickname ---
      case 'setNick': {
        const nick = (data.content || '').trim().replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 20);
        if (!nick) {
          sendToClient(ws, {
            type: 'error',
            room: null,
            user: null,
            content: 'Invalid nickname. Use alphanumeric characters, hyphens, underscores (max 20 chars).',
            timestamp: Date.now(),
          });
          return;
        }

        // Check for duplicate nicknames
        for (const [otherWs, otherInfo] of clients) {
          if (otherWs !== ws && otherInfo.nickname === nick) {
            sendToClient(ws, {
              type: 'error',
              room: null,
              user: null,
              content: `Nickname "${nick}" is already taken.`,
              timestamp: Date.now(),
            });
            return;
          }
        }

        const oldNick = clientInfo.nickname;
        clientInfo.nickname = nick;

        sendToClient(ws, {
          type: 'nickSet',
          room: null,
          user: nick,
          content: `Nickname set to "${nick}"`,
          timestamp: Date.now(),
        });

        // If already in a room, broadcast the name change
        if (clientInfo.currentRoom && oldNick) {
          const sysMsg = createSystemMessage(
            clientInfo.currentRoom,
            `${oldNick} is now known as ${nick}`
          );
          addMessageToHistory(clientInfo.currentRoom, sysMsg);
          broadcastToRoom(clientInfo.currentRoom, sysMsg);
          broadcastUserList(clientInfo.currentRoom);
        }

        // Send room list
        sendToClient(ws, {
          type: 'roomList',
          room: null,
          user: null,
          content: getRoomList(),
          timestamp: Date.now(),
        });

        console.log(`Nickname set: ${oldNick || '(new)'} -> ${nick}`);
        break;
      }

      // --- Join Room ---
      case 'join': {
        if (!clientInfo.nickname) {
          sendToClient(ws, {
            type: 'error',
            room: null,
            user: null,
            content: 'Set a nickname first.',
            timestamp: Date.now(),
          });
          return;
        }

        const roomName = (data.room || data.content || '').trim().toLowerCase().replace(/[^a-z0-9_-]/g, '').slice(0, 30);
        if (!roomName) {
          sendToClient(ws, {
            type: 'error',
            room: null,
            user: null,
            content: 'Invalid room name.',
            timestamp: Date.now(),
          });
          return;
        }

        joinRoom(ws, roomName);
        break;
      }

      // --- Leave Room ---
      case 'leave': {
        if (!clientInfo.currentRoom) {
          sendToClient(ws, {
            type: 'error',
            room: null,
            user: null,
            content: 'You are not in any room.',
            timestamp: Date.now(),
          });
          return;
        }

        const leftRoom = clientInfo.currentRoom;
        leaveRoom(ws);

        sendToClient(ws, {
          type: 'left',
          room: leftRoom,
          user: clientInfo.nickname,
          content: `You left #${leftRoom}`,
          timestamp: Date.now(),
        });

        // Send updated room list
        sendToClient(ws, {
          type: 'roomList',
          room: null,
          user: null,
          content: getRoomList(),
          timestamp: Date.now(),
        });
        break;
      }

      // --- Chat Message ---
      case 'message': {
        if (!clientInfo.nickname) {
          sendToClient(ws, { type: 'error', room: null, user: null, content: 'Set a nickname first.', timestamp: Date.now() });
          return;
        }
        if (!clientInfo.currentRoom) {
          sendToClient(ws, { type: 'error', room: null, user: null, content: 'Join a room first.', timestamp: Date.now() });
          return;
        }

        const content = (data.content || '').trim().slice(0, 1000);
        if (!content) return;

        // Clear typing indicator for this user
        clearTyping(ws, clientInfo.currentRoom);

        const chatMsg = createChatMessage(clientInfo.currentRoom, clientInfo.nickname, content);
        addMessageToHistory(clientInfo.currentRoom, chatMsg);
        broadcastToRoom(clientInfo.currentRoom, chatMsg);

        // Also send to the sender (so they see it in the chat)
        // Actually broadcastToRoom already includes the sender, so this is fine.
        break;
      }

      // --- Typing Indicator ---
      case 'typing': {
        if (!clientInfo.currentRoom) return;

        const room = rooms.get(clientInfo.currentRoom);
        if (!room) return;

        // Clear existing timeout
        const existingTimeout = room.typingUsers.get(ws);
        if (existingTimeout) clearTimeout(existingTimeout);

        // Set new timeout to auto-clear typing
        const timeout = setTimeout(() => {
          room.typingUsers.delete(ws);
          broadcastTypingIndicator(clientInfo.currentRoom);
        }, TYPING_TIMEOUT_MS);

        room.typingUsers.set(ws, timeout);
        broadcastTypingIndicator(clientInfo.currentRoom);
        break;
      }

      // --- Stop Typing ---
      case 'stopTyping': {
        if (!clientInfo.currentRoom) return;
        clearTyping(ws, clientInfo.currentRoom);
        break;
      }

      // --- Get Room List ---
      case 'getRooms': {
        sendToClient(ws, {
          type: 'roomList',
          room: null,
          user: null,
          content: getRoomList(),
          timestamp: Date.now(),
        });
        break;
      }

      default: {
        sendToClient(ws, {
          type: 'error',
          room: null,
          user: null,
          content: `Unknown message type: ${data.type}`,
          timestamp: Date.now(),
        });
      }
    }
  });

  ws.on('close', () => {
    const clientInfo = clients.get(ws);
    if (clientInfo) {
      if (clientInfo.currentRoom) {
        leaveRoom(ws);
      }
      console.log(`Disconnected: ${clientInfo.nickname || '(unnamed)'}`);
    }
    clients.delete(ws);
  });

  ws.on('error', (err) => {
    console.error('WebSocket error:', err.message);
  });
});

// --- Start ---
httpServer.listen(PORT, () => {
  console.log(`Chat server running on http://localhost:${PORT}`);
  console.log(`WebSocket server on ws://localhost:${PORT}`);
});
```

