<body>

<!-- Nickname Overlay -->
<div class="overlay" id="nickOverlay">
  <div class="overlay-card">
    <h2>Welcome to Chat</h2>
    <p>Choose a nickname to get started</p>
    <div class="form-row">
      <input type="text" id="nickInput" placeholder="Enter nickname..." maxlength="20"
             autofocus autocomplete="off">
      <button id="nickBtn" onclick="setNickname()">Join</button>
    </div>
    <div class="error-text" id="nickError"></div>
  </div>
</div>

<!-- Main App -->
<div class="header">
  <h1>WebSocket Chat</h1>
  <span class="connection-status disconnected" id="connStatus">Disconnected</span>
</div>

<div class="main">
  <!-- Sidebar -->
  <div class="sidebar">
    <div class="sidebar-section">
      <h3>Join a Room</h3>
      <div class="room-join-form">
        <input type="text" id="roomInput" placeholder="room name" maxlength="30" autocomplete="off">
        <button onclick="joinRoom()" class="secondary">Join</button>
      </div>
    </div>

    <div class="sidebar-section">
      <h3>Active Rooms</h3>
      <ul class="room-list" id="roomList">
        <li style="color: var(--text-muted); font-size: 0.8rem; cursor: default;">No rooms yet</li>
      </ul>
    </div>

    <div class="sidebar-section" style="flex:1; display:flex; flex-direction:column;">
      <h3>Users in Room</h3>
      <ul class="user-list" id="userList"></ul>
    </div>
  </div>

  <!-- Chat Area -->
  <div class="chat-area" id="chatArea">
    <div class="no-room" id="noRoom">
      <div class="icon">💬</div>
      <p>Join a room to start chatting</p>
    </div>

    <div id="chatView" style="display:none; flex:1; flex-direction:column;">
      <div class="chat-header">
        <span class="room-name" id="currentRoomName">general</span>
        <button class="secondary" onclick="leaveRoom()">Leave</button>
      </div>
      <div class="messages" id="messages"></div>
      <div class="typing-indicator" id="typingIndicator"></div>
      <div class="input-area">
        <input type="text" id="msgInput" placeholder="Type a message..."
               autocomplete="off" disabled>
        <button id="sendBtn" onclick="sendMessage()" disabled>Send</button>
      </div>
    </div>
  </div>
</div>

<script>
  // --- State ---
  let ws = null;
  let nickname = null;
  let currentRoom = null;
  let typingTimeout = null;
  let isTyping = false;
  let reconnectAttempts = 0;
  const MAX_RECONNECT = 5;

  // --- DOM Elements ---
  const nickOverlay = document.getElementById('nickOverlay');
  const nickInput = document.getElementById('nickInput');
  const nickError = document.getElementById('nickError');
  const connStatus = document.getElementById('connStatus');
  const roomInput = document.getElementById('roomInput');
  const roomList = document.getElementById('roomList');
  const userList = document.getElementById('userList');
  const noRoom = document.getElementById('noRoom');
  const chatView = document.getElementById('chatView');
  const currentRoomName = document.getElementById('currentRoomName');
  const messagesDiv = document.getElementById('messages');
  const typingIndicator = document.getElementById('typingIndicator');
  const msgInput = document.getElementById('msgInput');
  const sendBtn = document.getElementById('sendBtn');

  // --- WebSocket Connection ---
  function connect() {
    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
    ws = new WebSocket(`${protocol}//${location.host}`);

    ws.onopen = () => {
      console.log('Connected');
      reconnectAttempts = 0;
      connStatus.textContent = 'Connected';
      connStatus.className = 'connection-status connected';

      // If we already have a nickname (reconnecting), re-set it
      if (nickname) {
        ws.send(JSON.stringify({ type: 'setNick', content: nickname }));
      }
    };

    ws.onclose = () => {
      console.log('Disconnected');
      connStatus.textContent = 'Disconnected';
      connStatus.className = 'connection-status disconnected';
      msgInput.disabled = true;
      sendBtn.disabled = true;

      // Auto-reconnect
      if (reconnectAttempts < MAX_RECONNECT) {
        reconnectAttempts++;
        const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 10000);
        console.log(`Reconnecting in ${delay}ms (attempt ${reconnectAttempts})`);
        setTimeout(connect, delay);
      }
    };

    ws.onerror = (err) => {
      console.error('WebSocket error:', err);
    };

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);
      handleMessage(data);
    };
  }

  // --- Message Handler ---
  function handleMessage(data) {
    switch (data.type) {
      case 'welcome':
        // Show nickname overlay if no nickname set
        if (!nickname) {
          nickOverlay.classList.remove('hidden');
        }
        break;

      case 'nickSet':
        nickname = data.user;
        nickOverlay.classList.add('hidden');
        nickError.textContent = '';
        break;

      case 'error':
        // Show error in nickname overlay if visible
        if (!nickOverlay.classList.contains('hidden')) {
          nickError.textContent = data.content;
        } else {
          appendSystemMessage(data.content);
        }
        break;

      case 'roomList':
        renderRoomList(data.content);
        break;

      case 'joined':
        currentRoom = data.room;
        showChatView(data.room);
        // If reconnecting, we already joined
        if (data.room) {
          msgInput.disabled = false;
          sendBtn.disabled = false;
          msgInput.focus();
        }
        break;

      case 'left':
        currentRoom = null;
        hideChatView();
        break;

      case 'history':
        messagesDiv.innerHTML = '';
        if (data.content && data.content.length > 0) {
          for (const msg of data.content) {
            appendMessage(msg, false);
          }
          scrollToBottom();
        }
        break;

      case 'message':
        appendMessage(data, true);
        break;

      case 'system':
        appendSystemMessage(data.content, true);
        break;

      case 'userlist':
        renderUserList(data.content);
        break;

      case 'typing':
        renderTypingIndicator(data.content);
        break;
    }
  }

  // --- UI Rendering ---
  function showChatView(roomName) {
    noRoom.style.display = 'none';
    chatView.style.display = 'flex';
    currentRoomName.textContent = roomName;
    messagesDiv.innerHTML = '';
    typingIndicator.textContent = '';
  }

  function hideChatView() {
    noRoom.style.display = 'flex';
    chatView.style.display = 'none';
    msgInput.disabled = true;
    sendBtn.disabled = true;
    userList.innerHTML = '';
  }

  function renderRoomList(rooms) {
    if (!rooms || rooms.length === 0) {
      roomList.innerHTML = '<li style="color: var(--text-muted); font-size: 0.8rem; cursor: default;">No rooms yet</li>';
      return;
    }

    roomList.innerHTML = '';
    for (const room of rooms) {
      const li = document.createElement('li');
      li.className = room.name === currentRoom ? 'active' : '';
      li.innerHTML = `
        <span># ${escapeHtml(room.name)}</span>
        <span class="room-count">${room.users}</span>
      `;
      li.onclick = () => {
        if (room.name !== currentRoom) {
          ws.send(JSON.stringify({ type: 'join', room: room.name }));
        }
      };
      roomList.appendChild(li);
    }
  }

  function renderUserList(users) {
    userList.innerHTML = '';
    if (!users) return;

    const sorted = [...users].sort((a, b) => {
      if (a === nickname) return -1;
      if (b === nickname) return 1;
      return a.localeCompare(b);
    });

    for (const user of sorted) {
      const li = document.createElement('li');
      li.className = user === nickname ? 'self' : '';
      li.textContent = user + (user === nickname ? ' (you)' : '');
      userList.appendChild(li);
    }
  }

  function appendMessage(msg, scroll = true) {
    const div = document.createElement('div');
    const isOwn = msg.user === nickname;
    div.className = `message ${isOwn ? 'own' : 'other'}`;

    const time = new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    div.innerHTML = `
      <div class="msg-header">
        <span class="msg-user">${escapeHtml(msg.user)}</span>
        <span class="msg-time">${time}</span>
      </div>
      <div class="msg-content">${escapeHtml(msg.content)}</div>
    `;

    messagesDiv.appendChild(div);
    if (scroll) scrollToBottom();
  }

  function appendSystemMessage(content, scroll = true) {
    const div = document.createElement('div');
    div.className = 'message system';
    div.textContent = content;
    messagesDiv.appendChild(div);
    if (scroll) scrollToBottom();
  }

  function renderTypingIndicator(users) {
    if (!users || users.length === 0) {
      typingIndicator.innerHTML = '';
      return;
    }

    let text;
    if (users.length === 1) {
      text = `${escapeHtml(users[0])} is typing`;
    } else if (users.length === 2) {
      text = `${escapeHtml(users[0])} and ${escapeHtml(users[1])} are typing`;
    } else {
      text = `${users.length} people are typing`;
    }

    typingIndicator.innerHTML = `${text}<span class="dots">...</span>`;
  }

  function scrollToBottom() {
    requestAnimationFrame(() => {
      messagesDiv.scrollTop = messagesDiv.scrollHeight;
    });
  }

  function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // --- Actions ---
  function setNickname() {
    const nick = nickInput.value.trim();
    if (!nick) {
      nickError.textContent = 'Please enter a nickname';
      return;
    }
    ws.send(JSON.stringify({ type: 'setNick', content: nick }));
  }

  function joinRoom() {
    const room = roomInput.value.trim().toLowerCase();
    if (!room) return;
    ws.send(JSON.stringify({ type: 'join', room }));
    roomInput.value = '';
  }

  function leaveRoom() {
    ws.send(JSON.stringify({ type: 'leave' }));
  }

  function sendMessage() {
    const content = msgInput.value.trim();
    if (!content) return;
    ws.send(JSON.stringify({ type: 'message', content }));
    msgInput.value = '';

    // Stop typing indicator
    if (isTyping) {
      isTyping = false;
      ws.send(JSON.stringify({ type: 'stopTyping' }));
    }
    if (typingTimeout) {
      clearTimeout(typingTimeout);
      typingTimeout = null;
    }

    msgInput.focus();
  }

  // --- Event Listeners ---
  nickInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') setNickname();
  });

  roomInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') joinRoom();
  });

  msgInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      sendMessage();
      return;
    }

    // Send typing indicator
    if (!isTyping && ws && ws.readyState === WebSocket.OPEN && currentRoom) {
      isTyping = true;
      ws.send(JSON.stringify({ type: 'typing' }));
    }

    // Reset typing timeout
    if (typingTimeout) clearTimeout(typingTimeout);
    typingTimeout = setTimeout(() => {
      if (isTyping) {
        isTyping = false;
        if (ws && ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({ type: 'stopTyping' }));
        }
      }
    }, 2000);
  });

  // --- Initialize ---
  connect();
</script>
</body>
</html>
```

