    // --- WebSocket and State ---
    let ws;
    let typingTimeout;
    let currentNickname = '';
    let currentRoom = '';

    // Set a default random nickname
    nicknameInput.value += Math.floor(Math.random() * 1000);

    // --- Event Listeners ---
    joinBtn.addEventListener('click', joinChat);
    sendBtn.addEventListener('click', sendMessage);
    messageInput.addEventListener('keypress', (e) => {
