    });
    messageInput.addEventListener('input', handleTyping);

    // --- Functions ---
    function joinChat() {
        currentNickname = nicknameInput.value.trim();
        currentRoom = roomInput.value.trim();

        if (!currentNickname || !currentRoom) {
            alert('Nickname and Room Name are required.');
            return;
        }

        // Connect to WebSocket server
        ws = new WebSocket(`ws://${window.location.hostname}:8080`);

        ws.onopen = () => {
            console.log('Connected to WebSocket server.');
            // Set nickname first, then join room
            ws.send(JSON.stringify({ type: 'setNickname', content: currentNickname }));
            ws.send(JSON.stringify({ type: 'joinRoom', room: currentRoom }));

            // Switch UI
            setupDiv.style.display = 'none';
            chatRoomDiv.style.display = 'flex';
            chatHeader.textContent = `Room: ${currentRoom} | User: ${currentNickname}`;
            messageInput.focus();
        };

        ws.onmessage = (event) => {
            const message = JSON.parse(event.data);
            switch (message.type) {
                case 'history':
                    messagesDiv.innerHTML = ''; // Clear previous messages
                    message.content.forEach(addMessageToUI);
                    break;
                case 'chatMessage':
                case 'system':
                    addMessageToUI(message);
                    break;
                case 'typing':
                    showTypingIndicator(message.user);
                    break;
                case 'error':
                    alert(`Server error: ${message.content}`);
                    break;
            }
        };

        ws.onclose = () => {
            console.log('Disconnected from WebSocket server.');
            alert('Connection lost. Please refresh to reconnect.');
            setupDiv.style.display = 'block';
            chatRoomDiv.style.display = 'none';
        };


        ws.onerror = (error) => {
            console.error('WebSocket error:', error);
            alert('An error occurred with the connection.');
        };
    }

    function addMessageToUI(msg) {
        const msgElement = document.createElement('div');

        if (msg.type === 'system') {
            msgElement.className = 'system-message';
            msgElement.textContent = msg.content;
        } else { // chatMessage
            msgElement.className = 'message';
            const timestamp = new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

            const meta = document.createElement('div');
            meta.className = 'meta';

            const userSpan = document.createElement('span');
            userSpan.className = 'user';
            userSpan.textContent = msg.user === currentNickname ? 'You' : msg.user;

            meta.appendChild(userSpan);
            meta.append(` @ ${timestamp}`);

            const content = document.createElement('div');
            content.className = 'content';
            content.textContent = msg.content;

            msgElement.appendChild(meta);
            msgElement.appendChild(content);
        }

        messagesDiv.appendChild(msgElement);
        messagesDiv.scrollTop = messagesDiv.scrollHeight; // Auto-scroll to bottom
    }

    function sendMessage() {
        const content = messageInput.value.trim();
        if (content && ws && ws.readyState === WebSocket.OPEN) {
            ws.send(JSON.stringify({ type: 'chatMessage', content: content }));
            messageInput.value = '';
        }
    }

    function handleTyping() {
        if (ws && ws.readyState === WebSocket.OPEN) {
            // Send a typing event immediately
            ws.send(JSON.stringify({ type: 'typing' }));
        }
    }

    function showTypingIndicator(user) {
        typingIndicator.textContent = `${user} is typing...`;
        // Clear the indicator after a short period
        clearTimeout(typingTimeout);
        typingTimeout = setTimeout(() => {
            typingIndicator.textContent = '';
        }, 2000); // Indicator will disappear after 2 seconds of inactivity
    }
</script>

