            padding: 0 20px;
            height: 100%;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        /* --- LOGO --- */
        .logo {
            font-size: 1.5rem;
            font-weight: 800;
            color: var(--text-color);
            text-decoration: none;
            letter-spacing: -0.5px;
            z-index: 1001; /* Above mobile menu */
        }

        .logo span {
            color: var(--accent-color);
        }

        /* --- DESKTOP MENU --- */
        .nav-menu {
            display: flex;
            align-items: center;
            gap: 30px;
            list-style: none;
        }

        .nav-item {
            position: relative;
        }

        .nav-link {
            text-decoration: none;
            color: var(--text-color);
            font-weight: 500;
            font-size: 0.95rem;
            padding: 10px 0;
            position: relative;
            transition: color 0.2s ease;
        }

        /* Active State Indicator */
        .nav-link::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            width: 0;
            height: 2px;
            background-color: var(--accent-color);
            transition: width 0.3s ease;
        }

        .nav-link:hover, .nav-link.active {
            color: var(--accent-color);
        }

        .nav-link:hover::after, .nav-link.active::after {
            width: 100%;
        }

        /* --- DROPDOWN (DESKTOP) --- */
        .dropdown {
            position: absolute;
            top: 100%;
            left: 50%;
            transform: translateX(-50%) translateY(10px);
            background: white;
            min-width: 200px;
            padding: 10px 0;
            border-radius: 12px;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
            list-style: none;
            border: 1px solid rgba(0,0,0,0.05);
        }

        /* Show Dropdown on Hover */
        .nav-item:hover .dropdown {
            opacity: 1;
            visibility: visible;
            transform: translateX(-50%) translateY(0);
        }

        .dropdown li a {
            display: block;
            padding: 12px 20px;
            text-decoration: none;
            color: #4b5563;
            font-size: 0.9rem;
            transition: background 0.2s, color 0.2s;
        }

        .dropdown li a:hover {
            background-color: #f3f4f6;
            color: var(--accent-color);
        }

        /* --- CTA BUTTON --- */
        .btn-cta {
            background-color: var(--accent-color);
            color: white;
            padding: 10px 24px;
            border-radius: 50px;
            text-decoration: none;
            font-weight: 600;
            font-size: 0.9rem;
            transition: all 0.3s ease;
            box-shadow: 0 4px 14px rgba(37, 99, 235, 0.3);
        }

        .btn-cta:hover {
            background-color: var(--accent-hover);
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(37, 99, 235, 0.4);
        }

        /* --- MOBILE TOGGLE (HAMBURGER) --- */
        .hamburger {
            display: none;
            cursor: pointer;
            width: 30px;
            height: 20px;
            position: relative;
            z-index: 1001;
            background: none;
            border: none;
        }

        .hamburger span {
            display: block;
            width: 100%;
            height: 2px;
            background-color: var(--text-color);
            position: absolute;
            transition: all 0.3s ease;
        }

        .hamburger span:nth-child(1) { top: 0; }
        .hamburger span:nth-child(2) { top: 9px; }
        .hamburger span:nth-child(3) { top: 18px; }

        /* Hamburger Animation to X */
        .hamburger.active span:nth-child(1) {
            top: 9px;
            transform: rotate(45deg);
        }
        .hamburger.active span:nth-child(2) {
            opacity: 0;
        }
        .hamburger.active span:nth-child(3) {
            top: 9px;
            transform: rotate(-45deg);
        }

        /* --- MOBILE MENU OVERLAY --- */
        .mobile-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100vh;
            background: rgba(0, 0, 0, 0.4);
            backdrop-filter: blur(4px);
            z-index: 998;
            opacity: 0;
            visibility: hidden;
            transition: opacity 0.3s ease;
        }

        .mobile-overlay.open {
            opacity: 1;
            visibility: visible;
        }

        /* --- MOBILE MENU DRAWER --- */
        .mobile-nav {
            position: fixed;
            top: 0;
            right: 0;
            width: 100%;
            height: 100vh;
            background: white;
            z-index: 999;
            transform: translateX(100%);
            transition: transform 0.4s cubic-bezier(0.77, 0, 0.175, 1);
            display: flex;
            flex-direction: column;
            padding: 100px 30px 40px;
            overflow-y: auto;
        }

        .mobile-nav.open {
            transform: translateX(0);
        }

        .mobile-nav-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .mobile-nav-link {
            font-size: 1.5rem;
            font-weight: 700;
            text-decoration: none;
            color: var(--text-color);
            display: block;
            opacity: 0; /* For stagger animation */
            transform: translateY(20px);
            transition: opacity 0.3s ease, transform 0.3s ease, color 0.2s;
        }

        .mobile-nav.open .mobile-nav-link {
            opacity: 1;
            transform: translateY(0);
        }

        /* Stagger Delays */
        .mobile-nav.open .mobile-nav-link:nth-child(1) { transition-delay: 0.1s; }
        .mobile-nav.open .mobile-nav-link:nth-child(2) { transition-delay: 0.15s; }
        .mobile-nav.open .mobile-nav-link:nth-child(3) { transition-delay: 0.2s; }
        .mobile-nav.open .mobile-nav-link:nth-child(4) { transition-delay: 0.25s; }
        .mobile-nav.open .mobile-nav-link:nth-child(5) { transition-delay: 0.3s; }

        .mobile-cta {
            margin-top: 30px;
            text-align: center;
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 0.3s ease 0.4s, transform 0.3s ease 0.4s;
        }

        .mobile-nav.open .mobile-cta {
            opacity: 1;
            transform: translateY(0);
        }

        /* --- MOBILE ACCORDION --- */
        .accordion-item {
            border-bottom: 1px solid #eee;
        }

        .accordion-header {
            width: 100%;
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: none;
            border: none;
            padding: 15px 0;
            font-size: 1.5rem;
            font-weight: 700;
            color: var(--text-color);
            cursor: pointer;
            text-align: left;
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 0.3s ease, transform 0.3s ease;
        }

        .mobile-nav.open .accordion-header {
            opacity: 1;
            transform: translateY(0);
        }

        /* Specific delay for accordion header if it's the 3rd item */
        .mobile-nav.open .accordion-header { transition-delay: 0.2s; }

        .accordion-icon {
            font-size: 1.2rem;
            transition: transform 0.3s ease;
        }

        .accordion-header[aria-expanded="true"] .accordion-icon {
            transform: rotate(180deg);
        }

        .accordion-content {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.4s cubic-bezier(0, 1, 0, 1);
            padding-left: 10px;
        }

        .accordion-content.open {
            max-height: 300px; /* Arbitrary large height */
            transition: max-height 0.4s ease-in-out;
        }

        .accordion-content a {
            display: block;
            padding: 10px 0;
            text-decoration: none;
            color: #666;
            font-size: 1.1rem;
        }

        /* --- RESPONSIVE QUERIES --- */
        @media (max-width: 900px) {
            .nav-menu, .btn-cta {
                display: none;
            }

            .hamburger {
                display: block;
            }
        }

        @media (min-width: 901px) {
            .mobile-overlay, .mobile-nav, .hamburger {
                display: none;
            }
        }

        /* --- ACCESSIBILITY FOCUS --- */
        :focus-visible {
            outline: 2px solid var(--accent-color);
            outline-offset: 4px;
        }

        button:focus-visible, a:focus-visible {
            outline: 2px solid var(--accent-color);
            outline-offset: 4px;
        }

        /* Screen reader only class */
        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            white-space: nowrap;
            border: 0;
        }
    </style>
