        document.addEventListener('DOMContentLoaded', () => {
            const navbar = document.getElementById('navbar');
            const hamburger = document.getElementById('hamburger');
            const mobileNav = document.getElementById('mobile-nav');
            const mobileOverlay = document.getElementById('mobile-overlay');
            const accordionHeaders = document.querySelectorAll('.accordion-header');
            const body = document.body;

            // --- Sticky Navigation on Scroll ---
            window.addEventListener('scroll', () => {
                if (window.scrollY > 50) {
                    navbar.classList.add('scrolled');
                } else {
                    navbar.classList.remove('scrolled');
                }
            });

            // --- Mobile Menu Toggle ---
            function toggleMenu() {
                const isOpen = hamburger.getAttribute('aria-expanded') === 'true';

                hamburger.classList.toggle('active');
                hamburger.setAttribute('aria-expanded', !isOpen);
                mobileNav.classList.toggle('open');
                mobileOverlay.classList.toggle('open');

                // Prevent body scroll when menu is open
                if (!isOpen) {
                    body.style.overflow = 'hidden';
                    // Focus trap start (optional enhancement)
                    mobileNav.querySelector('a, button').focus();
                } else {
                    body.style.overflow = '';
                    hamburger.focus();
                }
            }

            hamburger.addEventListener('click', toggleMenu);
            mobileOverlay.addEventListener('click', toggleMenu);

            // Close menu on Escape key
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && mobileNav.classList.contains('open')) {
                    toggleMenu();
                }
            });

            // --- Mobile Accordion Logic ---
            accordionHeaders.forEach(header => {
                header.addEventListener('click', () => {
                    const content = document.getElementById(header.getAttribute('aria-controls'));
                    const isExpanded = header.getAttribute('aria-expanded') === 'true';

                    // Close other open accordions (optional - for single open state)
                    // accordionHeaders.forEach(otherHeader => {
                    //     if (otherHeader !== header) {
                    //         otherHeader.setAttribute('aria-expanded', 'false');
                    //         otherHeader.nextElementSibling.classList.remove('open');
                    //     }
                    // });

                    // Toggle current
                    header.setAttribute('aria-expanded', !isExpanded);
                    content.classList.toggle('open');
                });
            });

            // Handle Window Resize Cleanup
            window.addEventListener('resize', () => {
                if (window.innerWidth > 900 && mobileNav.classList.contains('open')) {
                    toggleMenu();
                }
            });
        });
    </script>
