    <script>
        // Sticky navigation on scroll
        const navContainer = document.getElementById('navContainer');
        let lastScroll = 0;

        window.addEventListener('scroll', () => {
            const currentScroll = window.pageYOffset;

            if (currentScroll > 50) {
                navContainer.classList.add('scrolled');
            } else {
                navContainer.classList.remove('scrolled');
            }

            lastScroll = currentScroll;
        });

        // Mobile menu toggle
        const mobileMenuToggle = document.getElementById('mobileMenuToggle');
        const mobileMenu = document.getElementById('mobileMenu');
        const mobileOverlay = document.getElementById('mobileOverlay');

        function toggleMobileMenu() {
            const isActive = mobileMenu.classList.contains('active');

            mobileMenuToggle.classList.toggle('active');
            mobileMenu.classList.toggle('active');
            mobileOverlay.classList.toggle('active');

            // Update ARIA attributes
            mobileMenuToggle.setAttribute('aria-expanded', !isActive);
            mobileOverlay.setAttribute('aria-hidden', isActive);

            // Prevent body scroll when menu is open
            document.body.style.overflow = isActive ? '' : 'hidden';
        }

        mobileMenuToggle.addEventListener('click', toggleMobileMenu);
        mobileOverlay.addEventListener('click', toggleMobileMenu);

        // Close mobile menu on escape key
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && mobileMenu.classList.contains('active')) {
                toggleMobileMenu();
            }
        });

        // Mobile accordion functionality
        const accordionToggles = document.querySelectorAll('.accordion-toggle');

        accordionToggles.forEach(toggle => {
            toggle.addEventListener('click', (e) => {
                e.stopPropagation();
                const accordionId = toggle.getAttribute('data-accordion');
                const content = document.getElementById(`accordion-${accordionId}`);
                const isActive = content.classList.contains('active');

                // Close all accordions
                document.querySelectorAll('.accordion-content').forEach(acc => {
                    acc.classList.remove('active');
                });
                document.querySelectorAll('.accordion-toggle').forEach(tog => {
                    tog.classList.remove('active');
                    tog.setAttribute('aria-expanded', 'false');
                });

                // Open clicked accordion if it wasn't active
                if (!isActive) {
                    content.classList.add('active');
                    toggle.classList.add('active');
                    toggle.setAttribute('aria-expanded', 'true');
                }
            });
        });

        // Close mobile menu when clicking on a link
        const mobileNavLinks = document.querySelectorAll('.mobile-nav-link, .mobile-submenu-link');
        mobileNavLinks.forEach(link => {
            link.addEventListener('click', () => {
                if (mobileMenu.classList.contains('active')) {
                    toggleMobileMenu();
                }
            });
        });

        // Keyboard navigation for desktop dropdowns
        const navItems = document.querySelectorAll('.nav-item');

        navItems.forEach(item => {
            const link = item.querySelector('.nav-link');
            const dropdown = item.querySelector('.dropdown-menu');

            if (dropdown) {
                link.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        const isExpanded = link.getAttribute('aria-expanded') === 'true';
                        link.setAttribute('aria-expanded', !isExpanded);
                    }
                });
            }
        });

        // Active link highlighting based on scroll position
        const sections = document.querySelectorAll('main > div');
        const navLinks = document.querySelectorAll('.nav-link, .mobile-nav-link');

        window.addEventListener('scroll', () => {
            let current = '';

            sections.forEach(section => {
                const sectionTop = section.offsetTop;
                const sectionHeight = section.clientHeight;
                if (pageYOffset >= sectionTop - 200) {
                    current = section.getAttribute('id');
                }
            });

            navLinks.forEach(link => {
                link.classList.remove('active');
                if (link.getAttribute('href') === `#${current}`) {
                    link.classList.add('active');
                }
            });
        });
    </script>
