            justify-content: space-between;
            margin-bottom: 2rem;
            padding-bottom: 1rem;
            border-bottom: 1px solid var(--border);
        }

        .mobile-close {
            width: 44px;
            height: 44px;
            display: flex;
            align-items: center;
            justify-content: center;
            background: none;
            border: none;
            cursor: pointer;
            border-radius: 8px;
            transition: var(--transition);
        }

        .mobile-close:hover {
            background: rgba(99, 102, 241, 0.08);
        }

        .mobile-close svg {
            width: 24px;
            height: 24px;
            color: var(--text);
        }

        /* Mobile Menu Items */
        .mobile-nav {
            list-style: none;
        }

        .mobile-nav-item {
            opacity: 0;
            transform: translateX(20px);
            transition: var(--transition);
        }

        .mobile-menu.active .mobile-nav-item {
            opacity: 1;
            transform: translateX(0);
        }

        .mobile-menu.active .mobile-nav-item:nth-child(1) { transition-delay: 0.1s; }
        .mobile-menu.active .mobile-nav-item:nth-child(2) { transition-delay: 0.15s; }
        .mobile-menu.active .mobile-nav-item:nth-child(3) { transition-delay: 0.2s; }
        .mobile-menu.active .mobile-nav-item:nth-child(4) { transition-delay: 0.25s; }
        .mobile-menu.active .mobile-nav-item:nth-child(5) { transition-delay: 0.3s; }
        .mobile-menu.active .mobile-nav-item:nth-child(6) { transition-delay: 0.35s; }

        .mobile-nav-link {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 1rem 0;
            text-decoration: none;
            color: var(--text);
            font-weight: 500;
            font-size: 1.1rem;
            border-bottom: 1px solid var(--border);
            transition: var(--transition);
        }

        .mobile-nav-link:hover,
        .mobile-nav-link:focus {
            color: var(--primary);
        }

        .mobile-nav-link.active {
            color: var(--primary);
        }

        .mobile-nav-link svg {
            width: 20px;
            height: 20px;
            transition: transform var(--transition);
        }

        /* Mobile Accordion */
        .mobile-accordion {
            border-bottom: 1px solid var(--border);
        }

        .mobile-accordion-btn {
            display: flex;
            align-items: center;
            justify-content: space-between;
            width: 100%;
            padding: 1rem 0;
            background: none;
            border: none;
            cursor: pointer;
            color: var(--text);
            font-weight: 500;
            font-size: 1.1rem;
            text-align: left;
            transition: var(--transition);
        }

        .mobile-accordion-btn:hover,
        .mobile-accordion-btn:focus {
            color: var(--primary);
        }

        .mobile-accordion-btn svg {
            width: 20px;
            height: 20px;
            transition: transform var(--transition);
        }

        .mobile-accordion-btn[aria-expanded="true"] svg {
            transform: rotate(180deg);
        }

        .mobile-accordion-content {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease-out;
        }

        .mobile-accordion-content.active {
            max-height: 500px;
        }

        .mobile-submenu {
            list-style: none;
            padding: 0.5rem 0 1rem 1rem;
        }

        .mobile-submenu-link {
            display: flex;
            align-items: center;
            gap: 0.75rem;
            padding: 0.75rem;
