  }

  body {
    font-family: var(--font-family);
    background-color: var(--color-bg);
    color: var(--color-text);
    line-height: 1.6;
    overflow-x: hidden;
  }

  /* ========== NAVBAR ========== */
  .navbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: var(--nav-height);
    z-index: 1000;
    transition: background var(--transition-medium), box-shadow var(--transition-medium), backdrop-filter var(--transition-medium);
  }

  .navbar.scrolled {
    background: var(--color-surface);
    backdrop-filter: blur(20px) saturate(180%);
    -webkit-backdrop-filter: blur(20px) saturate(180%);
    box-shadow: 0 1px 0 var(--color-border), 0 4px 20px rgba(0, 0, 0, 0.3);
  }

  .navbar-inner {
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 24px;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  /* ========== LOGO ========== */
  .logo {
    display: flex;
    align-items: center;
    gap: 10px;
    text-decoration: none;
    color: var(--color-text);
    font-weight: 700;
    font-size: 1.25rem;
    letter-spacing: -0.02em;
    flex-shrink: 0;
    z-index: 1001;
  }

  .logo-icon {
    width: 36px;
    height: 36px;
    background: linear-gradient(135deg, var(--color-accent), #a855f7);
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 1.1rem;
    color: white;
    transition: transform var(--transition-bounce);
  }

  .logo:hover .logo-icon {
    transform: rotate(-5deg) scale(1.05);
  }

  /* ========== DESKTOP NAV ========== */
  .nav-desktop {
    display: flex;
    align-items: center;
    gap: 4px;
    height: 100%;
  }

  .nav-item {
    position: relative;
    height: 100%;
    display: flex;
    align-items: center;
  }

  .nav-link {
    display: flex;
    align-items: center;
    gap: 5px;
    padding: 8px 16px;
    color: var(--color-text-muted);
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 500;
    border-radius: 8px;
    transition: color var(--transition-fast), background var(--transition-fast);
    white-space: nowrap;
    position: relative;
    cursor: pointer;
    border: none;
    background: none;
    font-family: inherit;
  }

  .nav-link:hover,
  .nav-link:focus-visible {
    color: var(--color-text);
    background: var(--color-surface-hover);
  }

  .nav-link:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
  }

  .nav-link.active {
    color: var(--color-text);
  }

  .nav-link.active::after {
    content: '';
    position: absolute;
    bottom: -6px;
    left: 50%;
    transform: translateX(-50%);
    width: 20px;
    height: 2px;
    background: var(--color-accent);
    border-radius: 1px;
  }

  .nav-link .chevron {
    width: 14px;
    height: 14px;
    transition: transform var(--transition-fast);
    opacity: 0.5;
  }

  /* ========== DROPDOWN ========== */
  .dropdown {
    position: absolute;
    top: calc(100% - 8px);
    left: 50%;
    transform: translateX(-50%) translateY(8px);
    min-width: 240px;
    background: rgba(22, 22, 26, 0.98);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid var(--color-border);
    border-radius: 14px;
    padding: 8px;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity var(--transition-medium), transform var(--transition-medium), visibility var(--transition-medium);
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.05) inset;
  }

  .nav-item:hover .dropdown,
  .nav-item:focus-within .dropdown {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transform: translateX(-50%) translateY(0);
  }

  .nav-item:hover .nav-link .chevron,
  .nav-item:focus-within .nav-link .chevron {
    transform: rotate(180deg);
  }

  .dropdown-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 14px;
    color: var(--color-text-muted);
    text-decoration: none;
    border-radius: 8px;
    transition: all var(--transition-fast);
    font-size: 0.875rem;
    font-weight: 500;
  }

  .dropdown-item:hover,
  .dropdown-item:focus-visible {
    color: var(--color-text);
    background: var(--color-surface-hover);
  }

  .dropdown-item:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
  }

  .dropdown-icon {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    flex-shrink: 0;
    background: var(--color-surface-hover);
    transition: background var(--transition-fast);
  }

  .dropdown-item:hover .dropdown-icon {
    background: rgba(99, 102, 241, 0.15);
  }

  .dropdown-text {
    display: flex;
    flex-direction: column;
  }

  .dropdown-label {
    font-weight: 600;
    color: var(--color-text);
    font-size: 0.875rem;
  }

  .dropdown-desc {
    font-size: 0.75rem;
    color: var(--color-text-muted);
    font-weight: 400;
  }

  .dropdown-divider {
    height: 1px;
    background: var(--color-border);
    margin: 6px 0;
  }

  /* ========== MEGA DROPDOWN ========== */
  .dropdown.mega {
    min-width: 520px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4px;
  }

  .dropdown.mega .dropdown-section-title {
    grid-column: 1 / -1;
    padding: 8px 14px 4px;
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--color-text-muted);
    opacity: 0.6;
  }

  .dropdown.mega .dropdown-divider {
    grid-column: 1 / -1;
  }

  .dropdown.mega .dropdown-full {
    grid-column: 1 / -1;
  }

  /* ========== CTA BUTTON ========== */
  .nav-cta {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 9px 20px;
    background: var(--color-accent);
    color: white;
    text-decoration: none;
    font-size: 0.875rem;
    font-weight: 600;
    border-radius: 10px;
    transition: all var(--transition-fast);
    white-space: nowrap;
    border: none;
    cursor: pointer;
    font-family: inherit;
    box-shadow: 0 0 20px var(--color-accent-glow);
  }

  .nav-cta:hover {
    background: var(--color-accent-hover);
    transform: translateY(-1px);
    box-shadow: 0 4px 24px var(--color-accent-glow);
  }

  .nav-cta:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  .nav-cta:active {
    transform: translateY(0);
  }

  .nav-actions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-shrink: 0;
  }

  /* ========== HAMBURGER ========== */
  .hamburger {
    display: none;
    width: 44px;
    height: 44px;
    border: none;
    background: none;
    cursor: pointer;
    padding: 10px;
    border-radius: 10px;
    transition: background var(--transition-fast);
    z-index: 1001;
    position: relative;
  }

  .hamburger:hover {
    background: var(--color-surface-hover);
  }

  .hamburger:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
  }

  .hamburger-line {
    display: block;
    width: 24px;
    height: 2px;
    background: var(--color-text);
    border-radius: 2px;
    transition: all var(--transition-medium);
    position: absolute;
    left: 10px;
  }

  .hamburger-line:nth-child(1) {
    top: 15px;
  }

  .hamburger-line:nth-child(2) {
    top: 21px;
    width: 18px;
  }

  .hamburger-line:nth-child(3) {
    top: 27px;
  }

  .hamburger[aria-expanded="true"] .hamburger-line:nth-child(1) {
    top: 21px;
    transform: rotate(45deg);
  }

  .hamburger[aria-expanded="true"] .hamburger-line:nth-child(2) {
    opacity: 0;
    transform: translateX(-8px);
  }

  .hamburger[aria-expanded="true"] .hamburger-line:nth-child(3) {
    top: 21px;
    transform: rotate(-45deg);
  }

  /* ========== MOBILE OVERLAY ========== */
  .mobile-overlay {
    display: none;
    position: fixed;
    inset: 0;
    background: var(--color-overlay);
    z-index: 999;
    opacity: 0;
    visibility: hidden;
    transition: opacity var(--transition-medium), visibility var(--transition-medium);
    backdrop-filter: blur(4px);
  }

  .mobile-overlay.active {
    opacity: 1;
    visibility: visible;
  }

  /* ========== MOBILE MENU ========== */
  .mobile-menu {
    display: none;
    position: fixed;
    top: 0;
    right: 0;
    width: min(380px, 90vw);
    height: 100vh;
    height: 100dvh;
    background: rgba(14, 14, 16, 0.98);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    z-index: 1000;
    transform: translateX(100%);
    transition: transform var(--transition-slow);
    overflow-y: auto;
    overscroll-behavior: contain;
    border-left: 1px solid var(--color-border);
  }

  .mobile-menu.active {
    transform: translateX(0);
  }

  .mobile-menu-inner {
    padding: calc(var(--nav-height) + 16px) 24px 40px;
  }

  /* ========== MOBILE NAV ITEMS ========== */
  .mobile-nav-item {
    opacity: 0;
    transform: translateX(30px);
    transition: opacity var(--transition-medium), transform var(--transition-medium);
  }

  .mobile-menu.active .mobile-nav-item:nth-child(1) { transition-delay: 0.1s; }
  .mobile-menu.active .mobile-nav-item:nth-child(2) { transition-delay: 0.15s; }
  .mobile-menu.active .mobile-nav-item:nth-child(3) { transition-delay: 0.2s; }
  .mobile-menu.active .mobile-nav-item:nth-child(4) { transition-delay: 0.25s; }
  .mobile-menu.active .mobile-nav-item:nth-child(5) { transition-delay: 0.3s; }
  .mobile-menu.active .mobile-nav-item:nth-child(6) { transition-delay: 0.35s; }
  .mobile-menu.active .mobile-nav-item:nth-child(7) { transition-delay: 0.4s; }
  .mobile-menu.active .mobile-nav-item:nth-child(8) { transition-delay: 0.45s; }

  .mobile-menu.active .mobile-nav-item {
    opacity: 1;
    transform: translateX(0);
  }

  .mobile-nav-link {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 0;
    color: var(--color-text);
    text-decoration: none;
    font-size: 1.1rem;
    font-weight: 600;
    border-bottom: 1px solid var(--color-border);
    transition: color var(--transition-fast);
    cursor: pointer;
    background: none;
    border-top: none;
    border-left: none;
    border-right: none;
    width: 100%;
    font-family: inherit;
    text-align: left;
  }

  .mobile-nav-link:hover {
    color: var(--color-accent-hover);
  }

  .mobile-nav-link:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
    border-radius: 4px;
  }

  .mobile-nav-link .chevron-mobile {
    width: 20px;
    height: 20px;
    transition: transform var(--transition-medium);
    color: var(--color-text-muted);
  }

  .mobile-nav-link[aria-expanded="true"] .chevron-mobile {
    transform: rotate(180deg);
  }

  /* ========== MOBILE ACCORDION ========== */
  .mobile-submenu {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-slow);
  }

  .mobile-submenu.open {
    max-height: 500px;
  }

  .mobile-submenu-inner {
    padding: 8px 0 16px;
  }

  .mobile-submenu-link {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 16px;
    color: var(--color-text-muted);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 500;
    border-radius: 10px;
    transition: all var(--transition-fast);
  }

  .mobile-submenu-link:hover {
    color: var(--color-text);
    background: var(--color-surface-hover);
  }

  .mobile-submenu-link:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
  }

  .mobile-submenu-icon {
    font-size: 1.2rem;
    width: 32px;
    text-align: center;
  }

  .mobile-cta {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    padding: 14px 24px;
    margin-top: 24px;
    background: var(--color-accent);
    color: white;
    text-decoration: none;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 12px;
    transition: all var(--transition-fast);
    border: none;
    cursor: pointer;
    font-family: inherit;
    box-shadow: 0 0 30px var(--color-accent-glow);
  }

  .mobile-cta:hover {
    background: var(--color-accent-hover);
  }

  .mobile-cta:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  /* ========== SKIP LINK ========== */
  .skip-link {
    position: absolute;
    top: -100%;
    left: 16px;
    padding: 12px 24px;
    background: var(--color-accent);
    color: white;
    text-decoration: none;
    border-radius: 8px;
    font-weight: 600;
    z-index: 10000;
    transition: top var(--transition-fast);
  }

  .skip-link:focus {
    top: 16px;
  }

  /* ========== RESPONSIVE ========== */
  @media (max-width: 900px) {
    .nav-desktop {
      display: none;
    }

    .nav-actions .nav-cta {
      display: none;
    }

    .hamburger {
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .mobile-overlay {
      display: block;
    }

    .mobile-menu {
      display: block;
    }
  }

  @media (min-width: 901px) {
    .mobile-menu,
    .mobile-overlay,
    .hamburger {
      display: none !important;
    }
  }

  /* ========== BODY LOCK ========== */
  body.menu-open {
    overflow: hidden;
  }

  /* ========== DEMO CONTENT ========== */
  .hero {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 120px 24px 80px;
    background: radial-gradient(ellipse at 50% 0%, rgba(99, 102, 241, 0.12) 0%, transparent 60%);
  }

  .hero h1 {
    font-size: clamp(2.5rem, 6vw, 4.5rem);
    font-weight: 800;
    letter-spacing: -0.03em;
    line-height: 1.1;
    margin-bottom: 20px;
    background: linear-gradient(135deg, #fff 0%, #a5a5b5 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .hero p {
    font-size: 1.2rem;
    color: var(--color-text-muted);
    max-width: 540px;
    margin-bottom: 40px;
  }

  .section {
    min-height: 80vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 80px 24px;
    border-top: 1px solid var(--color-border);
  }

  .section h2 {
    font-size: 2rem;
    font-weight: 700;
    color: var(--color-text-muted);
  }
</style>
</head>
