<script>
  // ========== Minimal Vanilla JS for Toggle Functionality ==========

  const hamburger = document.getElementById('hamburger');
  const mobileMenu = document.getElementById('mobile-menu');
  const mobileOverlay = document.getElementById('mobile-overlay');
  const navbar = document.querySelector('.navbar');

  // Mobile menu toggle
  function openMobileMenu() {
    hamburger.setAttribute('aria-expanded', 'true');
    hamburger.setAttribute('aria-label', 'Close menu');
    mobileMenu.classList.add('active');
    mobileMenu.setAttribute('aria-hidden', 'false');
    mobileOverlay.classList.add('active');
    mobileOverlay.setAttribute('aria-hidden', 'false');
    document.body.classList.add('menu-open');

    // Focus first link after animation
    setTimeout(() => {
      const firstLink = mobileMenu.querySelector('.mobile-nav-link');
      if (firstLink) firstLink.focus();
    }, 400);
  }

  function closeMobileMenu() {
    hamburger.setAttribute('aria-expanded', 'false');
    hamburger.setAttribute('aria-label', 'Open menu');
    mobileMenu.classList.remove('active');
    mobileMenu.setAttribute('aria-hidden', 'true');
    mobileOverlay.classList.remove('active');
    mobileOverlay.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('menu-open');

    // Close all submenus
    document.querySelectorAll('.mobile-submenu.open').forEach(sub => {
      sub.classList.remove('open');
      const btn = sub.previousElementSibling;
      if (btn) btn.setAttribute('aria-expanded', 'false');
    });

    hamburger.focus();
  }

  hamburger.addEventListener('click', () => {
    const isOpen = hamburger.getAttribute('aria-expanded') === 'true';
    if (isOpen) {
      closeMobileMenu();
    } else {
      openMobileMenu();
    }
  });

  mobileOverlay.addEventListener('click', closeMobileMenu);

  // Escape key closes menu
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && hamburger.getAttribute('aria-expanded') === 'true') {
      closeMobileMenu();
    }
  });

  // Mobile accordion toggles
  document.querySelectorAll('.mobile-nav-link[aria-controls]').forEach(btn => {
    btn.addEventListener('click', () => {
      const submenu = document.getElementById(btn.getAttribute('aria-controls'));
      const isOpen = btn.getAttribute('aria-expanded') === 'true';

      // Close other open submenus
      document.querySelectorAll('.mobile-nav-link[aria-controls]').forEach(otherBtn => {
        if (otherBtn !== btn) {
          otherBtn.setAttribute('aria-expanded', 'false');
          const otherSub = document.getElementById(otherBtn.getAttribute('aria-controls'));
          if (otherSub) otherSub.classList.remove('open');
        }
      });

      btn.setAttribute('aria-expanded', isOpen ? 'false' : 'true');
      submenu.classList.toggle('open', !isOpen);
    });
  });

  // Desktop dropdown aria-expanded management
  document.querySelectorAll('.nav-desktop .nav-item').forEach(item => {
    const btn = item.querySelector('.nav-link[aria-haspopup]');
    if (!btn) return;

    item.addEventListener('mouseenter', () => btn.setAttribute('aria-expanded', 'true'));
    item.addEventListener('mouseleave', () => btn.setAttribute('aria-expanded', 'false'));
    btn.addEventListener('focus', () => btn.setAttribute('aria-expanded', 'true'));
    item.addEventListener('focusout', (e) => {
      if (!item.contains(e.relatedTarget)) {
        btn.setAttribute('aria-expanded', 'false');
      }
    });
  });

  // Sticky navbar on scroll
  let lastScroll = 0;
  window.addEventListener('scroll', () => {
    const scrollY = window.scrollY;
    if (scrollY > 20) {
      navbar.classList.add('scrolled');
    } else {
      navbar.classList.remove('scrolled');
    }
    lastScroll = scrollY;
  }, { passive: true });

  // Trap focus in mobile menu when open
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab' || hamburger.getAttribute('aria-expanded') !== 'true') return;

    const focusableElements = mobileMenu.querySelectorAll(
      'a[href], button, [tabindex]:not([tabindex="-1"])'
    );
    const allFocusable = [hamburger, ...focusableElements];
    const firstEl = allFocusable[0];
    const lastEl = allFocusable[allFocusable.length - 1];

    if (e.shiftKey) {
      if (document.activeElement === firstEl) {
        e.preventDefault();
        lastEl.focus();
      }
    } else {
      if (document.activeElement === lastEl) {
        e.preventDefault();
        firstEl.focus();
      }
    }
  });
</script>

