        document.addEventListener('DOMContentLoaded', function () {
            const siteHeader = document.getElementById('site-header');
            const hamburgerMenu = document.getElementById('hamburger-menu');
            const mainNav = document.getElementById('main-nav');
            const navCloseBtn = document.getElementById('nav-close-btn');
            const navOverlay = document.getElementById('nav-overlay');
            const dropdownToggles = document.querySelectorAll('.dropdown-toggle');

            // --- 1. STICKY HEADER ---
            const handleScroll = () => {
                if (window.scrollY > 50) {
                    siteHeader.classList.add('is-sticky');
                } else {
                    siteHeader.classList.remove('is-sticky');
                }
            };
            window.addEventListener('scroll', handleScroll);

            // --- 2. MOBILE MENU TOGGLE ---
            const toggleMobileMenu = () => {
                const isMenuOpen = mainNav.classList.contains('is-open');
                mainNav.classList.toggle('is-open');
                hamburgerMenu.classList.toggle('is-active');
                navOverlay.classList.toggle('is-visible');
                document.body.classList.toggle('no-scroll');
                hamburgerMenu.setAttribute('aria-expanded', !isMenuOpen);
            };

            hamburgerMenu.addEventListener('click', toggleMobileMenu);
            navCloseBtn.addEventListener('click', toggleMobileMenu);
            navOverlay.addEventListener('click', toggleMobileMenu);

            // --- 3. ACCORDION SUBMENUS (for mobile) ---
            dropdownToggles.forEach(toggle => {
                toggle.addEventListener('click', () => {
                    // Only run accordion logic on smaller screens
                    if (window.innerWidth < 992) {
                        const isExpanded = toggle.getAttribute('aria-expanded') === 'true';
                        const targetMenuId = toggle.getAttribute('aria-controls');
                        const targetMenu = document.getElementById(targetMenuId);

                        toggle.setAttribute('aria-expanded', !isExpanded);

                        if (!isExpanded) {
                            // Use scrollHeight to get the full height of the content
                            targetMenu.style.maxHeight = targetMenu.scrollHeight + 'px';
                        } else {
                            targetMenu.style.maxHeight = '0';
                        }
                    }
                });
            });

            // Reset accordion styles on resize to desktop
            window.addEventListener('resize', () => {
                if (window.innerWidth >= 992) {
                    // Reset any inline max-height styles from the accordion JS
                    document.querySelectorAll('.dropdown-menu, .nested-menu').forEach(menu => {
                        menu.style.maxHeight = '';
                    });
                    // Ensure main nav is not in open state on desktop
                    if (mainNav.classList.contains('is-open')) {
                        toggleMobileMenu();
                    }
                }
            });
        });
    </script>

