                get passwordStrength() {
                    const pw = this.security.newPassword;
                    if (!pw) return 0;
                    let strength = 0;
                    if (pw.length >= 8) strength++;
                    if (/[a-z]/.test(pw) && /[A-Z]/.test(pw)) strength++;
                    if (/\d/.test(pw)) strength++;
                    if (/[^a-zA-Z0-9]/.test(pw)) strength++;
                    return strength;
                },

                handleAvatarUpload(event) {
                    const file = event.target.files[0];
                    if (file) {
                        if (file.size > 2 * 1024 * 1024) {
                            this.addToast('error', 'Upload Failed', 'File size must be less than 2MB');
                            return;
                        }
                        const reader = new FileReader();
                        reader.onload = (e) => {
                            this.avatarPreview = e.target.result;
                            this.addToast('success', 'Photo Updated', 'Your profile photo has been updated');
                        };
                        reader.readAsDataURL(file);
                    }
                },

                saveProfile() {
                    if (!this.profile.name.trim()) {
                        this.addToast('error', 'Validation Error', 'Name is required');
                        return;
                    }
                    if (!this.profile.email.trim() || !this.profile.email.includes('@')) {
                        this.addToast('error', 'Validation Error', 'Please enter a valid email');
                        return;
                    }
                    if (this.profile.bio.length > 250) {
                        this.addToast('error', 'Validation Error', 'Bio must be 250 characters or less');
                        return;
                    }
                    this.addToast('success', 'Profile Saved', 'Your profile has been updated successfully');
                },

                resetProfile() {
                    this.profile = { name: 'John Doe', email: 'john.doe@example.com', bio: 'Full-stack developer passionate about building great user experiences.' };
                    this.addToast('info', 'Profile Reset', 'Your profile has been reset to defaults');
                },

                saveNotifications() {
                    this.addToast('success', 'Preferences Saved', 'Notification preferences updated');
                },

                saveAppearance() {
                    this.addToast('success', 'Appearance Saved', 'Your display preferences have been saved');
                },

                changePassword() {
                    if (!this.security.currentPassword) {
                        this.addToast('error', 'Error', 'Please enter your current password');
                        return;
                    }
                    if (this.security.newPassword.length < 8) {
                        this.addToast('error', 'Error', 'New password must be at least 8 characters');
                        return;
                    }
                    if (this.security.newPassword !== this.security.confirmPassword) {
                        this.addToast('error', 'Error', 'Passwords do not match');
                        return;
                    }
                    this.security.currentPassword = '';
                    this.security.newPassword = '';
                    this.security.confirmPassword = '';
                    this.addToast('success', 'Password Changed', 'Your password has been updated successfully');
                },

                toggle2FA() {
                    if (this.security.twoFactor) {
                        this.addToast('success', '2FA Enabled', 'Two-factor authentication is now active');
                    } else {
                        this.addToast('info', '2FA Disabled', 'Two-factor authentication has been turned off');
                    }
                },

                revokeSession(id) {
                    this.sessions = this.sessions.filter(s => s.id !== id);
                    this.addToast('success', 'Session Revoked', 'The session has been terminated');
                },

                revokeAllSessions() {
                    this.sessions = this.sessions.filter(s => s.current);
                    this.addToast('success', 'All Sessions Revoked', 'All other sessions have been terminated');
                },

                deleteAccount() {
                    if (this.deleteConfirmText === 'DELETE') {
                        this.showDeleteModal = false;
                        this.deleteConfirmText = '';
                        this.addToast('error', 'Account Deleted', 'Your account has been permanently deleted');
                    }
                },

                addToast(type, title, message) {
                    const id = ++this.toastCounter;
                    const toast = { id, type, title, message, visible: true };
                    this.toasts.push(toast);
                    setTimeout(() => {
                        this.removeToast(id);
                    }, 4000);
                },

                removeToast(id) {
                    const toast = this.toasts.find(t => t.id === id);
                    if (toast) {
                        toast.visible = false;
                        setTimeout(() => {
                            this.toasts = this.toasts.filter(t => t.id !== id);
                        }, 300);
                    }
                }
            }
        }
    </script>
