    <script>
        // State
        let currentStep = 1;
        const totalSteps = 4;
        const userData = {
            name: '',
            role: '',
            photo: null,
            interests: [],
            connections: []
        };

        // DOM Elements
        const progressBar = document.getElementById('progress-bar');
        const stepTitle = document.getElementById('step-title');
        const stepSubtitle = document.getElementById('step-subtitle');
        const btnBack = document.getElementById('btn-back');
        const btnNext = document.getElementById('btn-next');

        // Step Content Containers
        const steps = {
            1: document.getElementById('step-1'),
            2: document.getElementById('step-2'),
            3: document.getElementById('step-3'),
            4: document.getElementById('step-4')
        };

        // --- Event Listeners ---

        // Photo Upload Preview
        document.getElementById('photo-input').addEventListener('change', function(e) {
            const file = e.target.files[0];
            if (file) {
                const reader = new FileReader();
                reader.onload = function(e) {
                    const img = document.getElementById('photo-preview');
                    const icon = document.getElementById('photo-icon');
                    img.src = e.target.result;
                    img.classList.remove('hidden');
                    icon.classList.add('hidden');
                    userData.photo = file;
                }
                reader.readAsDataURL(file);
            }
        });

        // Interest Cards Selection
        const interestCards = document.querySelectorAll('.interest-card');
        interestCards.forEach(card => {
            card.addEventListener('click', () => {
                const value = card.dataset.value;
                const index = userData.interests.indexOf(value);

                if (index > -1) {
                    // Deselect
                    userData.interests.splice(index, 1);
                    card.classList.remove('border-indigo-500', 'bg-indigo-50', 'ring-2', 'ring-indigo-500');
                    card.classList.add('border-slate-200');
                } else {
                    // Select
                    userData.interests.push(value);
                    card.classList.remove('border-slate-200');
                    card.classList.add('border-indigo-500', 'bg-indigo-50', 'ring-2', 'ring-indigo-500');
                }

                // Hide error if visible
                document.getElementById('error-interests').classList.add('hidden');
            });
        });

        // Connect Buttons Logic
        const connectBtns = document.querySelectorAll('.connect-btn');
        connectBtns.forEach(btn => {
            btn.addEventListener('click', function() {
                if (this.classList.contains('connected')) return;

                const statusSpan = this.querySelector('.connect-status');
                const originalText = statusSpan.innerText;

                // Simulate API call
                statusSpan.innerText = 'Connecting...';
                this.classList.add('opacity-75', 'cursor-wait');

                setTimeout(() => {
                    const service = this.dataset.service;
                    userData.connections.push(service);

                    this.classList.remove('opacity-75', 'cursor-wait', 'hover:bg-slate-50', 'border-slate-200');
                    this.classList.add('bg-green-50', 'border-green-200', 'connected');

                    statusSpan.innerText = 'Connected';
                    statusSpan.classList.remove('text-slate-400', 'group-hover:text-indigo-600');
                    statusSpan.classList.add('text-green-600', 'font-bold');

                    // Add checkmark icon
                    const checkIcon = document.createElement('svg');
                    checkIcon.className = 'w-5 h-5 text-green-600';
                    checkIcon.innerHTML = '<path fill="currentColor" d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/>';
                    statusSpan.parentNode.insertBefore(checkIcon, statusSpan.nextSibling);
                }, 800);
            });
        });

        // Navigation Buttons
        btnNext.addEventListener('click', handleNext);
        btnBack.addEventListener('click', () => {
            if (currentStep > 1) {
                changeStep(currentStep - 1);
            }
        });

        // --- Functions ---

        function handleNext() {
            // Validation
            if (currentStep === 1) {
                const nameInput = document.getElementById('input-name');
                const roleInput = document.getElementById('input-role');
                const nameError = document.getElementById('error-name');
                const roleError = document.getElementById('error-role');
                let valid = true;

                if (!nameInput.value.trim()) {
                    nameInput.classList.add('border-red-500', 'focus:ring-red-500');
                    nameError.classList.remove('hidden');
                    valid = false;
                } else {
                    nameInput.classList.remove('border-red-500', 'focus:ring-red-500');
                    nameError.classList.add('hidden');
                    userData.name = nameInput.value;
                }

                if (!roleInput.value) {
                    roleInput.classList.add('border-red-500', 'focus:ring-red-500');
                    roleError.classList.remove('hidden');
                    valid = false;
                } else {
                    roleInput.classList.remove('border-red-500', 'focus:ring-red-500');
                    roleError.classList.add('hidden');
                    userData.role = roleInput.value;
                }

                if (!valid) return;
            }

            if (currentStep === 2) {
                const error = document.getElementById('error-interests');
                if (userData.interests.length === 0) {
                    error.classList.remove('hidden');
                    return;
                }
                error.classList.add('hidden');
            }

            if (currentStep === 3) {
                // No validation needed, proceed to finish
                finishOnboarding();
                return;
            }

            changeStep(currentStep + 1);
        }

        function changeStep(step) {
            // Hide current
            steps[currentStep].classList.remove('active');

            // Update state
            currentStep = step;

            // Show new
            steps[currentStep].classList.add('active');

            // Update UI
            updateUI();
        }

        function updateUI() {
            // Progress Bar
            const progress = (currentStep / totalSteps) * 100;
            progressBar.style.width = `${progress}%`;

            // Titles
            const titles = {
                1: { title: "Welcome Aboard", sub: "Let's get your profile set up." },
                2: { title: "Your Interests", sub: "What would you like to focus on?" },
                3: { title: "Connect Accounts", sub: "Link your favorite tools." },
                4: { title: "All Done!", sub: "You are ready to start." }
            };
            stepTitle.innerText = titles[currentStep].title;
            stepSubtitle.innerText = titles[currentStep].sub;

            // Buttons
            btnBack.disabled = currentStep === 1;
            btnBack.classList.toggle('opacity-50', currentStep === 1);

            if (currentStep === 3) {
                btnNext.innerText = "Finish";
            } else if (currentStep === 4) {
                btnNext.classList.add('hidden');
                btnBack.classList.add('hidden');
            } else {
                btnNext.innerText = "Next Step";
            }
        }

        function finishOnboarding() {
            // Populate Summary
            document.getElementById('summary-name').innerText = userData.name;
            document.getElementById('summary-role').innerText = userData.role;
            document.getElementById('summary-interests').innerText = userData.interests.map(i => i.charAt(0).toUpperCase() + i.slice(1)).join(', ');

            // Trigger Confetti
            createConfetti();

            // Move to step 4
            changeStep(4);
        }

        function createConfetti() {
            const container = document.getElementById('confetti-container');
            const colors = ['#ef4444', '#3b82f6', '#10b981', '#f59e0b', '#8b5cf6'];

            for (let i = 0; i < 30; i++) {
                const confetti = document.createElement('div');
                confetti.classList.add('confetti');
                confetti.style.left = Math.random() * 100 + '%';
                confetti.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
                confetti.style.animationDuration = (Math.random() * 2 + 2) + 's';
                confetti.style.animationDelay = (Math.random() * 1) + 's';
                container.appendChild(confetti);
            }
        }
    </script>
</body>
</html>
