                <div class="bg-slate-50 p-4 rounded-lg w-full max-w-xs text-left mb-8 border border-slate-100">
                    <h4 class="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Summary</h4>
                    <div class="space-y-2 text-sm">
                        <div class="flex justify-between">
                            <span class="text-slate-600">Name:</span>
                            <span class="font-medium text-slate-900" id="summary-name">-</span>
                        </div>
