            <!-- Navigation Buttons -->
            <div class="mt-8 pt-6 border-t border-slate-100 flex justify-between items-center" id="nav-buttons">
                <button type="button" id="btn-back" onclick="changeStep(-1)" class="px-6 py-2.5 rounded-lg text-slate-600 font-medium hover:bg-slate-100 transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
                    Back
                </button>
                <button type="button" id="btn-next" onclick="changeStep(1)" class="px-8 py-2.5 rounded-lg bg-indigo-600 text-white font-medium hover:bg-indigo-700 shadow-md hover:shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed">
                    Next Step
