    <script>
        // State
        let currentStep = 1;
        const totalSteps = 4;
        const selectedInterests = new Set();
        const interestsData = [
            { id: 'tech', label: 'Technology', icon: 'fa-laptop-code' },
            { id: 'design', label: 'Design', icon: 'fa-paint-brush' },
            { id: 'business', label: 'Business', icon: 'fa-briefcase' },
            { id: 'marketing', label: 'Marketing', icon: 'fa-bullhorn' },
            { id: 'finance', label: 'Finance', icon: 'fa-chart-line' },
            { id: 'health', label: 'Health', icon: 'fa-heartbeat' },
            { id: 'travel', label: 'Travel', icon: 'fa-plane' },
            { id: 'food', label: 'Food', icon: 'fa-utensils' },
            { id: 'music', label: 'Music', icon: 'fa-music' },
        ];

        // DOM Elements
        const progressBar = document.getElementById('progress-bar');
        const stepTitle = document.getElementById('step-title');
        const stepCounter = document.getElementById('step-counter');
        const btnBack = document.getElementById('btn-back');
        const btnNext = document.getElementById('btn-next');
        const navButtons = document.getElementById('nav-buttons');

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            renderInterests();
            updateUI();
        });

        // Render Interest Cards
        function renderInterests() {
            const container = document.getElementById('interests-container');
            container.innerHTML = interestsData.map(item => `
                <div class="interest-card cursor-pointer border border-slate-200 rounded-xl p-4 flex flex-col items-center justify-center gap-2 transition-all hover:shadow-md hover:border-indigo-300" 
                     data-id="${item.id}" onclick="toggleInterest('${item.id}', this)">
                    <i class="fas ${item.icon} text-2xl text-slate-400 transition-colors"></i>
                    <span class="text-sm font-medium text-slate-600">${item.label}</span>
                </div>
            `).join('');
        }

        // Toggle Interest Selection
        function toggleInterest(id, element) {
            const icon = element.querySelector('i');
            const text = element.querySelector('span');

            if (selectedInterests.has(id)) {
                selectedInterests.delete(id);
                element.classList.remove('bg-indigo-50', 'border-indigo-500', 'ring-2', 'ring-indigo-200');
                icon.classList.remove('text-indigo-600');
                icon.classList.add('text-slate-400');
                text.classList.remove('text-indigo-700', 'font-bold');
                text.classList.add('text-slate-600', 'font-medium');
            } else {
                selectedInterests.add(id);
                element.classList.add('bg-indigo-50', 'border-indigo-500', 'ring-2', 'ring-indigo-200');
                icon.classList.remove('text-slate-400');
                icon.classList.add('text-indigo-600');
                text.classList.remove('text-slate-600', 'font-medium');
                text.classList.add('text-indigo-700', 'font-bold');
            }

            // Clear error if exists
            document.getElementById('error-interests').classList.add('hidden');
        }

        // Image Preview
        function previewImage(input) {
            if (input.files && input.files[0]) {
                const reader = new FileReader();
                reader.onload = function(e) {
                    const img = document.getElementById('photo-preview');
                    const placeholder = document.getElementById('photo-placeholder');
                    img.src = e.target.result;
                    img.classList.remove('hidden');
                    placeholder.classList.add('hidden');
                }
                reader.readAsDataURL(input.files[0]);
            }
        }

        // Connect Button Toggle
        function toggleConnect(btn) {
            const isConnecting = btn.innerText === 'Connect';

            if (isConnecting) {
                // Simulate loading
                const originalText = btn.innerText;
                btn.innerHTML = '<i class="fas fa-circle-notch fa-spin"></i>';
                btn.disabled = true;

                setTimeout(() => {
                    btn.classList.remove('text-slate-600', 'bg-white', 'border-slate-300');
                    btn.classList.add('text-green-700', 'bg-green-50', 'border-green-200');
                    btn.innerHTML = '<i class="fas fa-check mr-1"></i> Connected';
                    btn.disabled = false;
                }, 800);
            } else {
                // Disconnect
                btn.classList.add('text-slate-600', 'bg-white', 'border-slate-300');
                btn.classList.remove('text-green-700', 'bg-green-50', 'border-green-200');
                btn.innerText = 'Connect';
            }
        }

        // Validation Logic
        function validateStep(step) {
            let isValid = true;

            if (step === 1) {
                const name = document.getElementById('name').value.trim();
                const role = document.getElementById('role').value;
                const nameError = document.getElementById('error-name');
                const roleError = document.getElementById('error-role');

                if (!name) {
                    nameError.classList.remove('hidden');
                    document.getElementById('name').classList.add('border-red-500', 'focus:ring-red-500');
                    isValid = false;
                } else {
                    nameError.classList.add('hidden');
                    document.getElementById('name').classList.remove('border-red-500', 'focus:ring-red-500');
                }

                if (!role) {
                    roleError.classList.remove('hidden');
                    document.getElementById('role').classList.add('border-red-500', 'focus:ring-red-500');
                    isValid = false;
                } else {
                    roleError.classList.add('hidden');
                    document.getElementById('role').classList.remove('border-red-500', 'focus:ring-red-500');
                }
            }

            if (step === 2) {
                const error = document.getElementById('error-interests');
                if (selectedInterests.size < 2) {
                    error.classList.remove('hidden');
                    isValid = false;
                } else {
                    error.classList.add('hidden');
                }
            }

            return isValid;
        }

        // Navigation Logic
        function changeStep(direction) {
            // Validate current step before moving forward
            if (direction === 1 && !validateStep(currentStep)) {
                // Shake animation for error feedback could go here
                return;
            }

            // If moving forward from Step 3, populate summary
            if (direction === 1 && currentStep === 3) {
                populateSummary();
            }

            currentStep += direction;

            // Hide all steps
            document.querySelectorAll('.step-content').forEach(el => el.classList.remove('active'));

            // Show new step
            document.getElementById(`step-${currentStep}`).classList.add('active');

            updateUI();

            if (currentStep === 4) {
                startConfetti();
            }
        }

        function updateUI() {
            // Update Progress Bar
            const progress = (currentStep / totalSteps) * 100;
            progressBar.style.width = `${progress}%`;

            // Update Text
            stepCounter.innerText = `Step ${currentStep} of ${totalSteps}`;

            const titles = ["Welcome Aboard", "Your Interests", "Connect Accounts", "All Done!"];
            stepTitle.innerText = titles[currentStep - 1];

            // Update Buttons
            btnBack.disabled = currentStep === 1;
            btnBack.classList.toggle('opacity-50', currentStep === 1);
            btnBack.classList.toggle('cursor-not-allowed', currentStep === 1);

            if (currentStep === totalSteps) {
                navButtons.classList.add('hidden');
            } else {
                navButtons.classList.remove('hidden');
                btnNext.innerText = currentStep === 3 ? "Finish" : "Next Step";
            }
        }

        function populateSummary() {
            document.getElementById('summary-name').innerText = document.getElementById('name').value || 'User';

            const roleSelect = document.getElementById('role');
            const roleText = roleSelect.options[roleSelect.selectedIndex].text;
            document.getElementById('summary-role').innerText = roleText !== 'Select your role' ? roleText : 'Not specified';

            const interestsList = Array.from(selectedInterests).map(id => {
                const item = interestsData.find(i => i.id === id);
                return item ? item.label : '';
            }).join(', ');

            document.getElementById('summary-interests').innerText = interestsList || 'None';
        }

        function finishOnboarding() {
            alert("Redirecting to Dashboard...");
            // window.location.href = '/dashboard';
        }

        // Confetti Animation
        function startConfetti() {
            const colors = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#3b82f6'];

            for (let i = 0; i < 50; i++) {
                const confetti = document.createElement('div');
                confetti.classList.add('confetti');

                // Random properties
                const bg = colors[Math.floor(Math.random() * colors.length)];
                const left = Math.random() * 100 + '%';
                const animDuration = Math.random() * 2 + 2 + 's';
                const size = Math.random() * 10 + 5 + 'px';

                confetti.style.backgroundColor = bg;
                confetti.style.left = left;
                confetti.style.animationDuration = animDuration;
                confetti.style.width = size;
                confetti.style.height = size;

                document.body.appendChild(confetti);

                // Cleanup
                setTimeout(() => {
                    confetti.remove();
                }, 4000);
            }
        }
    </script>
</body>
</html>
