                            <circle class="checkmark-circle" cx="50" cy="50" r="45" fill="none" stroke="#10b981" stroke-width="4"/>
                            <path class="checkmark-check" fill="none" stroke="#10b981" stroke-width="4" stroke-linecap="round" d="M30 50 L45 65 L70 35"/>
                        </svg>
                        <div id="confetti-container" class="absolute inset-0"></div>
                    </div>

                    <h1 class="text-3xl md:text-4xl font-bold text-gray-900 mb-2">You're All Set! 🎉</h1>
                    <p class="text-gray-600 mb-8">Here's a summary of your choices</p>

                    <div class="bg-gray-50 rounded-lg p-6 text-left mb-8 space-y-4">
                        <div>
                            <h3 class="text-sm font-medium text-gray-500 mb-1">Name</h3>
                            <p class="text-gray-900 font-medium" id="summary-name">-</p>
                        </div>
                        <div>
                            <h3 class="text-sm font-medium text-gray-500 mb-1">Role</h3>
                            <p class="text-gray-900 font-medium" id="summary-role">-</p>
                        </div>
                        <div>
                            <h3 class="text-sm font-medium text-gray-500 mb-1">Interests</h3>
                            <div class="flex flex-wrap gap-2 mt-2" id="summary-interests"></div>
                        </div>
                        <div>
                            <h3 class="text-sm font-medium text-gray-500 mb-1">Connected Accounts</h3>
                            <div class="flex flex-wrap gap-2 mt-2" id="summary-connections"></div>
                        </div>
                    </div>

                    <button id="dashboard-btn" class="w-full md:w-auto px-8 py-4 bg-indigo-600 text-white rounded-lg font-semibold text-lg hover:bg-indigo-700 transition-all shadow-lg hover:shadow-xl">
                        Go to Dashboard →
                    </button>
                </div>
            </div>

            <!-- Navigation Buttons -->
            <div class="flex justify-between mt-8 pt-6 border-t border-gray-200">
                <button id="back-btn" class="px-6 py-3 text-gray-700 font-medium rounded-lg hover:bg-gray-100 transition-all disabled:opacity-50 disabled:cursor-not-allowed" disabled>
                    ← Back
                </button>
                <button id="next-btn" class="px-6 py-3 bg-indigo-600 text-white font-medium rounded-lg hover:bg-indigo-700 transition-all disabled:opacity-50 disabled:cursor-not-allowed">
                    Next →
                </button>
            </div>
        </div>
    </div>

    <script>
        // State management
        const state = {
            currentStep: 1,
            totalSteps: 4,
            direction: 'forward',
            data: {
                name: '',
                role: '',
                photo: null,
                interests: [],
                connections: []
            }
        };

        // DOM elements
        const steps = {
            1: document.getElementById('step-1'),
            2: document.getElementById('step-2'),
            3: document.getElementById('step-3'),
            4: document.getElementById('step-4')
        };

        const backBtn = document.getElementById('back-btn');
        const nextBtn = document.getElementById('next-btn');
        const nameInput = document.getElementById('name');
        const roleSelect = document.getElementById('role');
        const photoInput = document.getElementById('photo-input');
        const photoUploadArea = document.getElementById('photo-upload-area');
        const uploadPlaceholder = document.getElementById('upload-placeholder');
        const photoPreview = document.getElementById('photo-preview');
        const previewImage = document.getElementById('preview-image');
        const removePhotoBtn = document.getElementById('remove-photo');

        // Initialize
        function init() {
            setupEventListeners();
            updateUI();
        }

        // Event listeners
        function setupEventListeners() {
            backBtn.addEventListener('click', goBack);
            nextBtn.addEventListener('click', goNext);

            // Step 1: Welcome
            nameInput.addEventListener('input', () => {
                state.data.name = nameInput.value;
                hideError('name-error');
            });

            roleSelect.addEventListener('change', () => {
                state.data.role = roleSelect.value;
                hideError('role-error');
            });

            photoUploadArea.addEventListener('click', () => photoInput.click());
            photoInput.addEventListener('change', handlePhotoUpload);
            removePhotoBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                removePhoto();
            });

            // Step 2: Interests
            const interestCards = document.querySelectorAll('.interest-card');
            interestCards.forEach(card => {
                card.addEventListener('click', () => toggleInterest(card));
            });

            // Step 3: Connect
            const connectBtns = document.querySelectorAll('.connect-btn');
            connectBtns.forEach(btn => {
                btn.addEventListener('click', () => toggleConnection(btn));
            });

            // Step 4: Complete
            document.getElementById('dashboard-btn').addEventListener('click', () => {
                alert('Redirecting to dashboard...');
            });
        }

        // Photo upload handling
        function handlePhotoUpload(e) {
            const file = e.target.files[0];
            if (file && file.type.startsWith('image/')) {
                const reader = new FileReader();
                reader.onload = (e) => {
                    state.data.photo = e.target.result;
                    previewImage.src = e.target.result;
                    uploadPlaceholder.classList.add('hidden');
                    photoPreview.classList.remove('hidden');
                };
                reader.readAsDataURL(file);
            }
        }

        function removePhoto() {
            state.data.photo = null;
            photoInput.value = '';
            uploadPlaceholder.classList.remove('hidden');
            photoPreview.classList.add('hidden');
        }

        // Interest selection
        function toggleInterest(card) {
            const interest = card.dataset.interest;
            const index = state.data.interests.indexOf(interest);

            if (index > -1) {
                state.data.interests.splice(index, 1);
                card.classList.remove('selected', 'border-indigo-600', 'bg-indigo-50');
                card.classList.add('border-gray-200');
            } else {
                state.data.interests.push(interest);
                card.classList.add('selected', 'border-indigo-600', 'bg-indigo-50');
                card.classList.remove('border-gray-200');
            }

            updateInterestsCount();
            hideError('interests-error');
        }

        function updateInterestsCount() {
            const count = state.data.interests.length;
            const countEl = document.getElementById('interests-count');
            countEl.textContent = `${count} selected`;
            countEl.className = count >= 3 ? 'text-green-600 text-sm mt-4 text-center' : 'text-indigo-600 text-sm mt-4 text-center';
        }

        // Connection handling
        function toggleConnection(btn) {
            const service = btn.dataset.service;
            const connectedBtn = btn.parentElement.querySelector('.connected-btn');

            // Simulate connection
            btn.classList.add('hidden');
            connectedBtn.classList.remove('hidden');

            if (!state.data.connections.includes(service)) {
                state.data.connections.push(service);
            }
        }

        // Validation
        function validateStep(step) {
            switch(step) {
                case 1:
                    let valid = true;
                    if (!state.data.name.trim()) {
                        showError('name-error');
                        nameInput.classList.add('error-shake', 'border-red-500');
                        setTimeout(() => nameInput.classList.remove('error-shake'), 300);
                        valid = false;
                    }
                    if (!state.data.role) {
                        showError('role-error');
                        roleSelect.classList.add('error-shake', 'border-red-500');
                        setTimeout(() => roleSelect.classList.remove('error-shake'), 300);
                        valid = false;
                    }
                    return valid;

                case 2:
                    if (state.data.interests.length < 3) {
                        showError('interests-error');
                        return false;
                    }
                    return true;

                case 3:
                    return true; // Optional step

                default:
                    return true;
            }
        }

        function showError(errorId) {
            document.getElementById(errorId).classList.remove('hidden');
        }

        function hideError(errorId) {
            const errorEl = document.getElementById(errorId);
            if (errorEl) {
                errorEl.classList.add('hidden');
            }
            // Remove error styling
            nameInput.classList.remove('border-red-500');
            roleSelect.classList.remove('border-red-500');
        }

        // Navigation
        function goNext() {
            if (state.currentStep === state.totalSteps) return;

            if (!validateStep(state.currentStep)) return;

            state.direction = 'forward';
            state.currentStep++;
            updateUI();
        }

        function goBack() {
            if (state.currentStep === 1) return;

            state.direction = 'backward';
            state.currentStep--;
            updateUI();
        }

        // UI Updates
        function updateUI() {
            // Update steps visibility
            Object.keys(steps).forEach(stepNum => {
                const step = steps[stepNum];
                if (parseInt(stepNum) === state.currentStep) {
                    step.classList.remove('hidden');
                    step.classList.add('step-content');
                    step.classList.add(state.direction === 'forward' ? 'slide-right' : 'slide-left');
                } else {
                    step.classList.add('hidden');
                }
            });

            // Update progress indicator
            updateProgressIndicator();

            // Update buttons
            backBtn.disabled = state.currentStep === 1;

            if (state.currentStep === state.totalSteps) {
                nextBtn.classList.add('hidden');
                updateSummary();
                createConfetti();
            } else {
                nextBtn.classList.remove('hidden');
            }

            // Scroll to top
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

        function updateProgressIndicator() {
            const indicators = document.querySelectorAll('.step-indicator');

            indicators.forEach((indicator, index) => {
                const stepNum = index + 1;
                const circle = indicator.querySelector('div');
                const label = indicator.querySelector('span');

                if (stepNum < state.currentStep) {
                    // Completed
                    circle.className = 'w-10 h-10 rounded-full bg-indigo-600 text-white flex items-center justify-center font-semibold transition-all';
                    if (label) label.className = 'text-xs mt-1 hidden sm:block font-medium text-indigo-600';
                } else if (stepNum === state.currentStep) {
                    // Active
                    circle.className = 'w-10 h-10 rounded-full bg-indigo-600 text-white flex items-center justify-center font-semibold transition-all';
                    if (label) label.className = 'text-xs mt-1 hidden sm:block font-medium text-indigo-600';
                } else {
                    // Upcoming
                    circle.className = 'w-10 h-10 rounded-full bg-gray-200 text-gray-500 flex items-center justify-center font-semibold transition-all';
                    if (label) label.className = 'text-xs mt-1 hidden sm:block font-medium text-gray-500';
                }
            });

            // Update progress bars
            for (let i = 1; i < state.totalSteps; i++) {
                const progressBar = document.getElementById(`progress-bar-${i}`);
                if (i < state.currentStep) {
                    progressBar.style.width = '100%';
                } else {
                    progressBar.style.width = '0%';
                }
            }
        }

        function updateSummary() {
            // Name
            document.getElementById('summary-name').textContent = state.data.name;

            // Role
            const roleText = roleSelect.options[roleSelect.selectedIndex].text;
            document.getElementById('summary-role').textContent = roleText;

            // Interests
            const interestsContainer = document.getElementById('summary-interests');
            interestsContainer.innerHTML = '';
            state.data.interests.forEach(interest => {
                const badge = document.createElement('span');
                badge.className = 'px-3 py-1 bg-indigo-100 text-indigo-700 rounded-full text-sm font-medium';
                badge.textContent = interest.charAt(0).toUpperCase() + interest.slice(1);
                interestsContainer.appendChild(badge);
            });

            // Connections
            const connectionsContainer = document.getElementById('summary-connections');
            connectionsContainer.innerHTML = '';
            if (state.data.connections.length === 0) {
                connectionsContainer.innerHTML = '<span class="text-gray-500 text-sm">None connected</span>';
            } else {
                state.data.connections.forEach(connection => {
                    const badge = document.createElement('span');
                    badge.className = 'px-3 py-1 bg-green-100 text-green-700 rounded-full text-sm font-medium';
                    badge.textContent = connection.charAt(0).toUpperCase() + connection.slice(1);
                    connectionsContainer.appendChild(badge);
                });
            }
        }

        function createConfetti() {
            const container = document.getElementById('confetti-container');
            container.innerHTML = '';

            const colors = ['#6366f1', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981'];

            for (let i = 0; i < 50; i++) {
                const confetti = document.createElement('div');
                confetti.className = 'confetti';
                confetti.style.left = Math.random() * 100 + '%';
                confetti.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
                confetti.style.animationDelay = Math.random() * 0.5 + 's';
                confetti.style.animationDuration = (Math.random() * 2 + 2) + 's';
                container.appendChild(confetti);
            }
        }

        // Initialize app
        init();
    </script>
</body>
</html>
```

This onboarding flow includes:

1. **4-Step Process**:
   - Step 1: Name, role selector, and profile photo upload
   - Step 2: Multi-select interest cards with visual feedback
   - Step 3: Account connections (GitHub, Google, Slack) with toggle states
   - Step 4: Success screen with celebration animation and summary

2. **Features**:
   - Animated progress indicator showing current step
   - Smooth transitions between steps (slide animations)
   - Form validation with inline error messages and shake animations
   - Back/Next buttons with proper disabled states
   - CSS-only celebration animation with confetti and checkmark
   - Responsive design that works on mobile and desktop
   - Clean, modern UI with Tailwind CSS
   - Photo upload with preview
   - Multi-select interest cards with visual feedback
   - Connection toggle states
   - Complete summary on final step

3. **Validation**:
   - Step 1: Requires name and role
   - Step 2: Requires at least 3 interests
   - Step 3: Optional (no validation)
   - Visual feedback with error messages and animations

The design is approachable and modern, with smooth animations and clear visual feedback throughout the entire flow.

```html
<!DOCTYPE html>
<html lang="en">
<head>
