<body class="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-purple-50">
    <div class="min-h-screen flex flex-col items-center justify-center p-4 sm:p-6 lg:p-8">
        <!-- Main Container -->
        <div class="w-full max-w-2xl">
            <!-- Progress Indicator -->
            <div class="mb-8">
                <div class="flex items-center justify-between mb-2">
                    <span class="text-sm font-medium text-gray-600">Step <span id="currentStepNum">1</span> of 4</span>
                    <span class="text-sm font-medium text-indigo-600" id="stepTitle">Welcome</span>
                </div>
                <div class="h-2 bg-gray-200 rounded-full overflow-hidden">
                    <div id="progressBar" class="progress-fill h-full bg-gradient-to-r from-indigo-500 to-purple-500 rounded-full" style="width: 25%"></div>
                </div>
                <!-- Step indicators -->
                <div class="flex justify-between mt-4">
                    <div class="flex flex-col items-center">
                        <div id="step1Indicator" class="w-10 h-10 rounded-full bg-indigo-600 text-white flex items-center justify-center font-semibold text-sm transition-all duration-300">1</div>
                        <span class="text-xs mt-1 text-gray-600 hidden sm:block">Welcome</span>
                    </div>
                    <div class="flex-1 flex items-center px-2">
                        <div class="h-0.5 w-full bg-gray-200 rounded"></div>
                    </div>
                    <div class="flex flex-col items-center">
                        <div id="step2Indicator" class="w-10 h-10 rounded-full bg-gray-200 text-gray-500 flex items-center justify-center font-semibold text-sm transition-all duration-300">2</div>
                        <span class="text-xs mt-1 text-gray-600 hidden sm:block">Preferences</span>
                    </div>
                    <div class="flex-1 flex items-center px-2">
                        <div class="h-0.5 w-full bg-gray-200 rounded"></div>
                    </div>
                    <div class="flex flex-col items-center">
                        <div id="step3Indicator" class="w-10 h-10 rounded-full bg-gray-200 text-gray-500 flex items-center justify-center font-semibold text-sm transition-all duration-300">3</div>
                        <span class="text-xs mt-1 text-gray-600 hidden sm:block">Connect</span>
                    </div>
                    <div class="flex-1 flex items-center px-2">
                        <div class="h-0.5 w-full bg-gray-200 rounded"></div>
                    </div>
                    <div class="flex flex-col items-center">
                        <div id="step4Indicator" class="w-10 h-10 rounded-full bg-gray-200 text-gray-500 flex items-center justify-center font-semibold text-sm transition-all duration-300">4</div>
                        <span class="text-xs mt-1 text-gray-600 hidden sm:block">Complete</span>
                    </div>
                </div>
            </div>

            <!-- Card Container -->
            <div class="bg-white rounded-2xl shadow-xl overflow-hidden">
                <!-- Steps Container -->
                <div id="stepsContainer" class="relative">
                    <!-- Step 1: Welcome -->
                    <div id="step1" class="step-content p-6 sm:p-8 step-enter">
                        <div class="text-center mb-8">
                            <h2 class="text-2xl sm:text-3xl font-bold text-gray-800 mb-2">Welcome! Let's get started 👋</h2>
                            <p class="text-gray-600">Tell us a bit about yourself</p>
                        </div>

                        <!-- Profile Photo Upload -->
                        <div class="flex justify-center mb-6">
                            <div class="photo-upload relative w-28 h-28 rounded-full bg-gray-100 border-2 border-dashed border-gray-300 cursor-pointer overflow-hidden group hover:border-indigo-400 transition-colors" onclick="document.getElementById('photoInput').click()">
                                <input type="file" id="photoInput" accept="image/*" class="hidden" onchange="handlePhotoUpload(event)">
                                <img id="photoPreview" src="" alt="" class="w-full h-full object-cover hidden">
                                <div class="upload-overlay absolute inset-0 flex flex-col items-center justify-center bg-gray-100 group-hover:bg-indigo-50 transition-colors">
                                    <svg class="w-8 h-8 text-gray-400 group-hover:text-indigo-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path>
                                    </svg>
                                    <span class="text-xs text-gray-500 mt-1">Add Photo</span>
                                </div>
                            </div>
                        </div>

                        <!-- Name Input -->
                        <div class="mb-5">
                            <label for="nameInput" class="block text-sm font-medium text-gray-700 mb-2">Full Name *</label>
                            <input type="text" id="nameInput" placeholder="Enter your full name" class="input-field w-full px-4 py-3 border border-gray-300 rounded-xl focus:border-indigo-500 transition-all duration-200" oninput="validateStep1()">
                            <p id="nameError" class="text-red-500 text-sm mt-1 hidden">Please enter your name</p>
                        </div>

                        <!-- Role Selector -->
                        <div class="mb-6">
                            <label for="roleSelect" class="block text-sm font-medium text-gray-700 mb-2">Your Role *</label>
                            <div class="relative">
                                <select id="roleSelect" class="input-field w-full px-4 py-3 border border-gray-300 rounded-xl appearance-none bg-white focus:border-indigo-500 transition-all duration-200 cursor-pointer" onchange="validateStep1()">
                                    <option value="">Select your role</option>
                                    <option value="developer">Developer</option>
                                    <option value="designer">Designer</option>
                                    <option value="product-manager">Product Manager</option>
                                    <option value="data-scientist">Data Scientist</option>
                                    <option value="marketing">Marketing</option>
                                    <option value="other">Other</option>
                                </select>
                                <div class="absolute inset-y-0 right-0 flex items-center pr-4 pointer-events-none">
                                    <svg class="w-5 h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path>
                                    </svg>
                                </div>
                            </div>
                            <p id="roleError" class="text-red-500 text-sm mt-1 hidden">Please select your role</p>
                        </div>
                    </div>

                    <!-- Step 2: Preferences -->
                    <div id="step2" class="step-content p-6 sm:p-8 hidden">
                        <div class="text-center mb-8">
                            <h2 class="text-2xl sm:text-3xl font-bold text-gray-800 mb-2">What interests you? 🎯</h2>
                            <p class="text-gray-600">Select at least 3 topics you're interested in</p>
                        </div>

                        <!-- Interest Cards Grid -->
                        <div id="interestsGrid" class="grid grid-cols-2 sm:grid-cols-3 gap-3 sm:gap-4 mb-4">
                            <!-- Cards will be generated by JS -->
                        </div>
                        <p id="interestsError" class="text-red-500 text-sm text-center hidden">Please select at least 3 interests</p>
                        <p id="interestsCount" class="text-sm text-gray-500 text-center mt-2">0 selected</p>
                    </div>

                    <!-- Step 3: Connect -->
                    <div id="step3" class="step-content p-6 sm:p-8 hidden">
                        <div class="text-center mb-8">
                            <h2 class="text-2xl sm:text-3xl font-bold text-gray-800 mb-2">Connect your accounts 🔗</h2>
                            <p class="text-gray-600">Link your favorite tools for a better experience</p>
                        </div>

                        <!-- Connection Cards -->
                        <div class="space-y-4">
                            <!-- GitHub -->
                            <div class="flex items-center justify-between p-4 bg-gray-50 rounded-xl border border-gray-200 hover:border-gray-300 transition-colors">
                                <div class="flex items-center gap-4">
                                    <div class="w-12 h-12 bg-gray-900 rounded-xl flex items-center justify-center">
                                        <svg class="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24">
                                            <path d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z"/>
                                        </svg>
                                    </div>
                                    <div>
                                        <h3 class="font-semibold text-gray-800">GitHub</h3>
                                        <p class="text-sm text-gray-500">Connect your repositories</p>
                                    </div>
                                </div>
                                <button id="githubBtn" onclick="toggleConnection('github')" class="connect-btn px-5 py-2.5 bg-gray-900 text-white rounded-lg font-medium hover:bg-gray-800 transition-all">
                                    Connect
                                </button>
                            </div>

                            <!-- Google -->
                            <div class="flex items-center justify-between p-4 bg-gray-50 rounded-xl border border-gray-200 hover:border-gray-300 transition-colors">
                                <div class="flex items-center gap-4">
                                    <div class="w-12 h-12 bg-white rounded-xl flex items-center justify-center border border-gray-200">
                                        <svg class="w-6 h-6" viewBox="0 0 24 24">
                                            <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                                            <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                                            <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
                                            <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                                        </svg>
                                    </div>
                                    <div>
                                        <h3 class="font-semibold text-gray-800">Google</h3>
                                        <p class="text-sm text-gray-500">Sync your calendar & contacts</p>
                                    </div>
                                </div>
                                <button id="googleBtn" onclick="toggleConnection('google')" class="connect-btn px-5 py-2.5 bg-gray-900 text-white rounded-lg font-medium hover:bg-gray-800 transition-all">
                                    Connect
                                </button>
                            </div>

                            <!-- Slack -->
                            <div class="flex items-center justify-between p-4 bg-gray-50 rounded-xl border border-gray-200 hover:border-gray-300 transition-colors">
                                <div class="flex items-center gap-4">
                                    <div class="w-12 h-12 bg-white rounded-xl flex items-center justify-center border border-gray-200">
                                        <svg class="w-6 h-6" viewBox="0 0 24 24">
                                            <path fill="#E01E5A" d="M5.042 15.165a2.528 2.528 0 0 1-2.52 2.523A2.528 2.528 0 0 1 0 15.165a2.527 2.527 0 0 1 2.522-2.52h2.52v2.52zM6.313 15.165a2.527 2.527 0 0 1 2.521-2.52 2.527 2.527 0 0 1 2.521 2.52v6.313A2.528 2.528 0 0 1 8.834 24a2.528 2.528 0 0 1-2.521-2.522v-6.313z"/>
                                            <path fill="#36C5F0" d="M8.834 5.042a2.528 2.528 0 0 1-2.521-2.52A2.528 2.528 0 0 1 8.834 0a2.528 2.528 0 0 1 2.521 2.522v2.52H8.834zM8.834 6.313a2.528 2.528 0 0 1 2.521 2.521 2.528 2.528 0 0 1-2.521 2.521H2.522A2.528 2.528 0 0 1 0 8.834a2.528 2.528 0 0 1 2.522-2.521h6.312z"/>
                                            <path fill="#2EB67D" d="M18.956 8.834a2.528 2.528 0 0 1 2.522-2.521A2.528 2.528 0 0 1 24 8.834a2.528 2.528 0 0 1-2.522 2.521h-2.522V8.834zM17.688 8.834a2.528 2.528 0 0 1-2.523 2.521 2.527 2.527 0 0 1-2.52-2.521V2.522A2.527 2.527 0 0 1 15.165 0a2.528 2.528 0 0 1 2.523 2.522v6.312z"/>
                                            <path fill="#ECB22E" d="M15.165 18.956a2.528 2.528 0 0 1 2.523 2.522A2.528 2.528 0 0 1 15.165 24a2.527 2.527 0 0 1-2.52-2.522v-2.522h2.52zM15.165 17.688a2.527 2.527 0 0 1-2.52-2.523 2.526 2.526 0 0 1 2.52-2.52h6.313A2.527 2.527 0 0 1 24 15.165a2.528 2.528 0 0 1-2.522 2.523h-6.313z"/>
                                        </svg>
                                    </div>
                                    <div>
                                        <h3 class="font-semibold text-gray-800">Slack</h3>
                                        <p class="text-sm text-gray-500">Get notifications in Slack</p>
                                    </div>
                                </div>
                                <button id="slackBtn" onclick="toggleConnection('slack')" class="connect-btn px-5 py-2.5 bg-gray-900 text-white rounded-lg font-medium hover:bg-gray-800 transition-all">
                                    Connect
                                </button>
                            </div>
                        </div>

                        <p class="text-sm text-gray-500 text-center mt-6">You can always connect more accounts later</p>
                    </div>

                    <!-- Step 4: Complete -->
                    <div id="step4" class="step-content p-6 sm:p-8 hidden">
                        <div class="text-center">
                            <!-- Success Animation -->
                            <div class="relative inline-block mb-6">
                                <div class="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto relative">
                                    <div class="pulse-ring absolute inset-0 bg-green-200 rounded-full"></div>
                                    <svg class="w-12 h-12 text-green-500 celebration-icon relative z-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path class="checkmark-path" stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"></path>
                                    </svg>
                                </div>
                            </div>

                            <h2 class="text-2xl sm:text-3xl font-bold text-gray-800 mb-2">You're all set! 🎉</h2>
                            <p class="text-gray-600 mb-8">Welcome aboard, <span id="welcomeName" class="font-semibold text-indigo-600"></span>!</p>

                            <!-- Summary -->
                            <div class="bg-gray-50 rounded-xl p-6 text-left mb-8">
                                <h3 class="font-semibold text-gray-800 mb-4">Your Profile Summary</h3>
                                <div class="space-y-3">
                                    <div class="flex items-center gap-3">
                                        <div class="w-8 h-8 bg-indigo-100 rounded-lg flex items-center justify-center">
                                            <svg class="w-4 h-4 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path>
                                            </svg>
                                        </div>
                                        <div>
                                            <p class="text-sm text-gray-500">Role</p>
                                            <p id="summaryRole" class="font-medium text-gray-800"></p>
                                        </div>
                                    </div>
                                    <div class="flex items-center gap-3">
                                        <div class="w-8 h-8 bg-purple-100 rounded-lg flex items-center justify-center">
                                            <svg class="w-4 h-4 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"></path>
                                            </svg>
                                        </div>
                                        <div>
                                            <p class="text-sm text-gray-500">Interests</p>
                                            <p id="summaryInterests" class="font-medium text-gray-800"></p>
                                        </div>
                                    </div>
                                    <div class="flex items-center gap-3">
                                        <div class="w-8 h-8 bg-green-100 rounded-lg flex items-center justify-center">
                                            <svg class="w-4 h-4 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1"></path>
                                            </svg>
                                        </div>
                                        <div>
                                            <p class="text-sm text-gray-500">Connected Accounts</p>
                                            <p id="summaryConnections" class="font-medium text-gray-800"></p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <!-- Go to Dashboard Button -->
                            <button onclick="goToDashboard()" class="w-full sm:w-auto px-8 py-4 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-xl font-semibold hover:from-indigo-700 hover:to-purple-700 transform hover:scale-105 transition-all duration-200 shadow-lg hover:shadow-xl">
                                Go to Dashboard
                                <svg class="w-5 h-5 inline-block ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 7l5 5m0 0l-5 5m5-5H6"></path>
                                </svg>
                            </button>
                        </div>
                    </div>
                </div>

                <!-- Navigation Buttons -->
                <div id="navButtons" class="flex justify-between items-center px-6 sm:px-8 py-4 bg-gray-50 border-t border-gray-100">
                    <button id="backBtn" onclick="prevStep()" class="px-6 py-2.5 text-gray-600 font-medium rounded-lg hover:bg-gray-200 transition-colors disabled:opacity-50 disabled:cursor-not-allowed" disabled>
                        <svg class="w-5 h-5 inline-block mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"></path>
                        </svg>
                        Back
                    </button>
                    <button id="nextBtn" onclick="nextStep()" class="px-6 py-2.5 bg-indigo-600 text-white font-medium rounded-lg hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
                        Next
                        <svg class="w-5 h-5 inline-block ml-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path>
                        </svg>
                    </button>
                </div>
            </div>
        </div>
    </div>

    <!-- Confetti Container -->
    <div id="confettiContainer"></div>

    <script>
        // State
        let currentStep = 1;
        const totalSteps = 4;

        const formData = {
            name: '',
            role: '',
            photo: null,
            interests: [],
            connections: {
                github: false,
                google: false,
                slack: false
            }
        };

        // Interests data
        const interests = [
            { id: 'ai', label: 'AI & ML', icon: '🤖' },
            { id: 'web', label: 'Web Dev', icon: '🌐' },
            { id: 'mobile', label: 'Mobile', icon: '📱' },
            { id: 'cloud', label: 'Cloud', icon: '☁️' },
            { id: 'security', label: 'Security', icon: '🔒' },
            { id: 'data', label: 'Data', icon: '📊' },
            { id: 'design', label: 'Design', icon: '🎨' },
            { id: 'devops', label: 'DevOps', icon: '⚙️' },
            { id: 'blockchain', label: 'Blockchain', icon: '⛓️' },
            { id: 'gaming', label: 'Gaming', icon: '🎮' },
            { id: 'iot', label: 'IoT', icon: '📡' },
            { id: 'startup', label: 'Startups', icon: '🚀' }
        ];

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            renderInterests();
            updateUI();
        });

        // Render interest cards
        function renderInterests() {
            const grid = document.getElementById('interestsGrid');
            grid.innerHTML = interests.map(interest => `
                <div class="card-select cursor-pointer p-4 bg-gray-50 border-2 border-gray-200 rounded-xl hover:border-indigo-300 transition-all" 
                     data-id="${interest.id}" 
                     onclick="toggleInterest('${interest.id}')">
                    <div class="text-2xl mb-2">${interest.icon}</div>
                    <div class="font-medium text-gray-800 text-sm">${interest.label}</div>
                </div>
            `).join('');
        }

        // Toggle interest selection
        function toggleInterest(id) {
            const card = document.querySelector(`[data-id="${id}"]`);
            const index = formData.interests.indexOf(id);

            if (index > -1) {
                formData.interests.splice(index, 1);
                card.classList.remove('selected', 'border-indigo-500', 'bg-indigo-50');
                card.classList.add('border-gray-200', 'bg-gray-50');
            } else {
                formData.interests.push(id);
                card.classList.add('selected', 'border-indigo-500', 'bg-indigo-50');
                card.classList.remove('border-gray-200', 'bg-gray-50');
            }

            updateInterestsCount();
            validateStep2();
        }

        // Update interests count
        function updateInterestsCount() {
            const count = formData.interests.length;
            document.getElementById('interestsCount').textContent = `${count} selected`;
        }

        // Toggle connection
        function toggleConnection(service) {
            const btn = document.getElementById(`${service}Btn`);
            formData.connections[service] = !formData.connections[service];

            if (formData.connections[service]) {
                btn.textContent = '✓ Connected';
                btn.classList.add('connected');
            } else {
                btn.textContent = 'Connect';
                btn.classList.remove('connected');
            }
        }

        // Photo upload handler
        function handlePhotoUpload(event) {
            const file = event.target.files[0];
            if (file) {
                const reader = new FileReader();
                reader.onload = (e) => {
                    const preview = document.getElementById('photoPreview');
                    preview.src = e.target.result;
                    preview.classList.remove('hidden');
                    document.querySelector('.upload-overlay').classList.add('hidden');
                    formData.photo = e.target.result;
                };
                reader.readAsDataURL(file);
            }
        }

        // Validation functions
        function validateStep1() {
            const name = document.getElementById('nameInput').value.trim();
            const role = document.getElementById('roleSelect').value;

            formData.name = name;
            formData.role = role;

            const nameError = document.getElementById('nameError');
            const roleError = document.getElementById('roleError');

            let valid = true;

            if (!name) {
                valid = false;
            }
            nameError.classList.toggle('hidden', name.length > 0);

            if (!role) {
                valid = false;
            }
            roleError.classList.toggle('hidden', role.length > 0);

            updateNextButton();
            return valid;
        }

        function validateStep2() {
            const valid = formData.interests.length >= 3;
            document.getElementById('interestsError').classList.toggle('hidden', valid);
            updateNextButton();
            return valid;
        }

        function validateStep3() {
            return true; // Connections are optional
        }

        // Update next button state
        function updateNextButton() {
            const nextBtn = document.getElementById('nextBtn');
            let isValid = false;

            switch (currentStep) {
                case 1:
                    isValid = formData.name.trim() && formData.role;
                    break;
                case 2:
                    isValid = formData.interests.length >= 3;
                    break;
                case 3:
                    isValid = true;
                    break;
            }

            nextBtn.disabled = !isValid;
        }

        // Navigation
        function nextStep() {
            let canProceed = false;

            switch (currentStep) {
                case 1:
                    canProceed = validateStep1();
                    if (!canProceed) {
                        document.getElementById('nameInput').parentElement.classList.add('error-shake');
                        setTimeout(() => {
                            document.getElementById('nameInput').parentElement.classList.remove('error-shake');
                        }, 300);
                    }
                    break;
                case 2:
                    canProceed = validateStep2();
                    break;
                case 3:
                    canProceed = true;
                    break;
            }

            if (canProceed && currentStep < totalSteps) {
                transitionStep(currentStep, currentStep + 1);
                currentStep++;
                updateUI();

                if (currentStep === 4) {
                    showCompletionStep();
                }
            }
        }

        function prevStep() {
            if (currentStep > 1) {
                transitionStep(currentStep, currentStep - 1);
                currentStep--;
                updateUI();
            }
        }

        // Step transition animation
        function transitionStep(from, to) {
            const fromStep = document.getElementById(`step${from}`);
            const toStep = document.getElementById(`step${to}`);

            fromStep.classList.add('step-exit');

            setTimeout(() => {
                fromStep.classList.add('hidden');
                fromStep.classList.remove('step-exit');
                toStep.classList.remove('hidden');
                toStep.classList.add('step-enter');

                setTimeout(() => {
                    toStep.classList.remove('step-enter');
                }, 400);
            }, 300);
        }

        // Update UI based on current step
        function updateUI() {
            // Update progress bar
            const progress = (currentStep / totalSteps) * 100;
            document.getElementById('progressBar').style.width = `${progress}%`;

            // Update step number
            document.getElementById('currentStepNum').textContent = currentStep;

            // Update step title
            const titles = ['Welcome', 'Preferences', 'Connect', 'Complete'];
            document.getElementById('stepTitle').textContent = titles[currentStep - 1];

            // Update step indicators
            for (let i = 1; i <= totalSteps; i++) {
                const indicator = document.getElementById(`step${i}Indicator`);
                if (i < currentStep) {
                    indicator.classList.remove('bg-gray-200', 'text-gray-500', 'bg-indigo-600', 'text-white');
                    indicator.classList.add('bg-green-500', 'text-white');
                    indicator.innerHTML = '✓';
                } else if (i === currentStep) {
                    indicator.classList.remove('bg-gray-200', 'text-gray-500', 'bg-green-500');
                    indicator.classList.add('bg-indigo-600', 'text-white');
                    indicator.innerHTML = i;
                } else {
                    indicator.classList.remove('bg-indigo-600', 'text-white', 'bg-green-500');
                    indicator.classList.add('bg-gray-200', 'text-gray-500');
                    indicator.innerHTML = i;
                }
            }

            // Update back button
            document.getElementById('backBtn').disabled = currentStep === 1;

            // Update next button
            updateNextButton();

            // Hide nav buttons on completion
            document.getElementById('navButtons').classList.toggle('hidden', currentStep === 4);
        }

        // Show completion step
        function showCompletionStep() {
            // Update summary
            document.getElementById('welcomeName').textContent = formData.name;

            const roleMap = {
                'developer': 'Developer',
                'designer': 'Designer',
                'product-manager': 'Product Manager',
                'data-scientist': 'Data Scientist',
                'marketing': 'Marketing',
                'other': 'Other'
            };
            document.getElementById('summaryRole').textContent = roleMap[formData.role] || formData.role;

            const selectedInterests = formData.interests.map(id => {
                const interest = interests.find(i => i.id === id);
                return interest ? interest.label : id;
            });
            document.getElementById('summaryInterests').textContent = selectedInterests.join(', ');

            const connectedServices = Object.entries(formData.connections)
                .filter(([_, connected]) => connected)
                .map(([service]) => service.charAt(0).toUpperCase() + service.slice(1));
            document.getElementById('summaryConnections').textContent = 
                connectedServices.length > 0 ? connectedServices.join(', ') : 'None';

            // Trigger confetti
            setTimeout(createConfetti, 500);
        }

        // Create confetti animation
        function createConfetti() {
            const container = document.getElementById('confettiContainer');
            const colors = ['#6366f1', '#8b5cf6', '#ec4899', '#10b981', '#f59e0b', '#ef4444'];

            for (let i = 0; i < 50; i++) {
                const confetti = document.createElement('div');
                confetti.className = 'confetti-piece';
                confetti.style.left = Math.random() * 100 + 'vw';
                confetti.style.top = '100vh';
                confetti.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
                confetti.style.borderRadius = Math.random() > 0.5 ? '50%' : '0';
                confetti.style.animationDelay = Math.random() * 0.5 + 's';
                confetti.style.animationDuration = (Math.random() * 2 + 2) + 's';
                container.appendChild(confetti);

                setTimeout(() => confetti.remove(), 4000);
            }
        }

        // Go to dashboard
        function goToDashboard() {
            alert('Welcome to your dashboard! 🎉\n\nThis would redirect to the main application.');
        }
    </script>
</body>
</html>
