            <!-- Navigation Buttons -->
            <div class="px-8 sm:px-10 py-6 border-t border-slate-100 flex justify-between items-center bg-slate-50/50" id="nav-buttons">
                <button id="back-btn" class="px-6 py-2.5 rounded-xl text-sm font-semibold text-slate-500 hover:text-slate-700 hover:bg-slate-100 transition-all disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:hover:text-slate-500" disabled onclick="goBack()">
