    <script>
        let currentStep = 1;
        const totalSteps = 4;
        let selectedInterests = new Set();
        let connectedAccounts = new Set();
        let userData = { name: '', role: '', photo: null };

        const interestLabels = {
            'ai': 'AI & ML', 'web': 'Web Dev', 'mobile': 'Mobile',
            'cloud': 'Cloud', 'security': 'Security', 'data': 'Data',
            'devops': 'DevOps', 'design': 'Design', 'blockchain': 'Blockchain'
        };

        const roleLabels = {
            'developer': '👨‍💻 Developer', 'designer': '🎨 Designer',
            'product-manager': '📋 Product Manager', 'data-scientist': '📊 Data Scientist',
            'marketing': '📣 Marketing', 'other': '🔧 Other'
        };

        // Photo upload
        document.getElementById('photo-input').addEventListener('change', function(e) {
            const file = e.target.files[0];
            if (file) {
                const reader = new FileReader();
                reader.onload = function(ev) {
                    const preview = document.getElementById('photo-preview');
                    const placeholder = document.getElementById('photo-placeholder');
                    preview.src = ev.target.result;
                    preview.classList.remove('hidden');
                    placeholder.classList.add('hidden');
                    userData.photo = ev.target.result;
                    document.getElementById('photo-label').style.borderStyle = 'solid';
                    document.getElementById('photo-label').style.borderColor = '#6366f1';
                };
                reader.readAsDataURL(file);
            }
        });

        // Interest cards
        document.querySelectorAll('.interest-card').forEach(card => {
            card.addEventListener('click', function() {
                const interest = this.dataset.interest;
                if (selectedInterests.has(interest)) {
                    selectedInterests.delete(interest);
                    this.classList.remove('selected', 'border-indigo-500', 'bg-indigo-50');
                    this.classList.add('border-slate-200', 'bg-white');
                    // Remove checkmark
                    const check = this.querySelector('.check-icon');
                    if (check) check.remove();
                } else {
                    selectedInterests.add(interest);
                    this.classList.add('selected', 'border-indigo-500', 'bg-indigo-50');
                    this.classList.remove('border-slate-200', 'bg-white');
                    // Add checkmark
                    if (!this.querySelector('.check-icon')) {
                        const checkDiv = document.createElement('div');
                        checkDiv.className = 'check-icon absolute top-1 right-1 w-5 h-5 bg-indigo-600 rounded-full flex items-center justify-center bounce-in';
                        checkDiv.innerHTML = '<svg class="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>';
                        this.style.position = 'relative';
                        this.appendChild(checkDiv);
                    }
                }
                updateInterestCount();
                hideError('interests-error');
            });
        });

        function updateInterestCount() {
            const count = selectedInterests.size;
            const el = document.getElementById('interests-count');
            el.textContent = `${count} selected${count < 3 ? ' (need ' + (3 - count) + ' more)' : ' ✓'}`;
            el.className = count >= 3 ? 'text-emerald-500 text-sm mt-3 text-center font-medium' : 'text-slate-400 text-sm mt-3 text-center';
        }

        function toggleConnect(btn) {
            const service = btn.dataset.service;
            if (connectedAccounts.has(service)) {
                connectedAccounts.delete(service);
                btn.textContent = 'Connect';
                btn.classList.remove('connected', 'bg-emerald-50', 'border-emerald-300', 'text-emerald-700');
                btn.classList.add('border-slate-200', 'text-slate-600');
            } else {
                // Simulate connecting
                btn.textContent = 'Connecting...';
                btn.disabled = true;
                btn.classList.add('opacity-50');
                setTimeout(() => {
                    connectedAccounts.add(service);
                    btn.innerHTML = '<svg class="w-4 h-4 inline mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>Connected';
                    btn.disabled = false;
                    btn.classList.remove('opacity-50', 'border-slate-200', 'text-slate-600');
                    btn.classList.add('connected', 'bg-emerald-50', 'border-emerald-300', 'text-emerald-700');
                }, 800);
            }
        }

        // Real-time validation clearing
        document.getElementById('name-input').addEventListener('input', function() {
            if (this.value.trim()) {
                hideError('name-error');
                this.classList.remove('border-red-400', 'ring-red-100');
            }
        });

        document.getElementById('role-select').addEventListener('change', function() {
            if (this.value) {
                hideError('role-error');
                this.classList.remove('border-red-400', 'ring-red-100');
            }
        });

        function showError(id, inputId) {
            const error = document.getElementById(id);
            error.classList.remove('hidden');
            if (inputId) {
                const input = document.getElementById(inputId);
                input.classList.add('border-red-400', 'ring-4', 'ring-red-100', 'input-error');
                setTimeout(() => input.classList.remove('input-error'), 400);
            }
        }

        function hideError(id) {
            document.getElementById(id).classList.add('hidden');
        }

        function validateStep(step) {
            if (step === 1) {
                let valid = true;
                const name = document.getElementById('name-input').value.trim();
                const role = document.getElementById('role-select').value;

                if (!name) {
                    showError('name-error', 'name-input');
                    valid = false;
                }
                if (!role) {
                    showError('role-error', 'role-select');
                    valid = false;
                }

                if (valid) {
                    userData.name = name;
                    userData.role = role;
                }
                return valid;
            }
            if (step === 2) {
                if (selectedInterests.size < 3) {
                    showError('interests-error');
                    // Shake the grid
                    const grid = document.getElementById('interests-grid');
                    grid.classList.add('input-error');
                    setTimeout(() => grid.classList.remove('input-error'), 400);
                    return false;
                }
                return true;
            }
            return true;
        }

        function updateProgressIndicator() {
            const dots = document.querySelectorAll('.step-dot');
            dots.forEach(dot => {
                const step = parseInt(dot.dataset.step);
                const label = dot.nextElementSibling;
                if (step < currentStep) {
                    // Completed
                    dot.className = 'step-dot w-10 h-10 rounded-full flex items-center justify-center text-sm font-semibold bg-emerald-500 text-white shadow-lg shadow-emerald-200';
                    dot.innerHTML = '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>';
                    if (label && label.tagName === 'SPAN') {
                        label.className = 'text-sm font-medium text-emerald-600 hidden sm:inline';
                    }
                } else if (step === currentStep) {
                    // Current
                    dot.className = 'step-dot w-10 h-10 rounded-full flex items-center justify-center text-sm font-semibold bg-indigo-600 text-white shadow-lg shadow-indigo-200';
                    dot.textContent = step;
                    if (label && label.tagName === 'SPAN') {
                        label.className = 'text-sm font-medium text-indigo-600 hidden sm:inline';
                    }
                } else {
                    // Upcoming
                    dot.className = 'step-dot w-10 h-10 rounded-full flex items-center justify-center text-sm font-semibold bg-slate-200 text-slate-400';
                    dot.textContent = step;
                    if (label && label.tagName === 'SPAN') {
                        label.className = 'text-sm font-medium text-slate-400 hidden sm:inline';
                    }
                }
            });

            // Update progress bars
            for (let i = 1; i < totalSteps; i++) {
                const bar = document.getElementById(`progress-${i}-${i+1}`);
                if (bar) {
                    if (currentStep > i) {
                        bar.style.width = '100%';
                    } else if (currentStep === i) {
                        bar.style.width = '50%';
                    } else {
                        bar.style.width = '0%';
                    }
                }
            }
        }

        function showStep(step) {
            // Hide all steps
            document.querySelectorAll('.step').forEach(s => {
                s.classList.add('hidden');
                s.classList.remove('step-enter');
            });

            // Show target step
            const target = document.getElementById(`step-${step}`);
            target.classList.remove('hidden');
            // Force reflow for animation
            void target.offsetWidth;
            target.classList.add('step-enter');

            // Update nav buttons
            const backBtn = document.getElementById('back-btn');
            const nextBtn = document.getElementById('next-btn');
            const navButtons = document.getElementById('nav-buttons');

            backBtn.disabled = step === 1;

            if (step === totalSteps) {
                navButtons.classList.add('hidden');
                populateSummary();
                launchConfetti();
            } else {
                navButtons.classList.remove('hidden');
                if (step === totalSteps - 1) {
                    nextBtn.textContent = 'Complete ✨';
                } else {
                    nextBtn.textContent = 'Next →';
                }
            }

            updateProgressIndicator();
        }

        function goNext() {
            if (!validateStep(currentStep)) return;
            if (currentStep < totalSteps) {
                currentStep++;
                showStep(currentStep);
            }
        }

        function goBack() {
            if (currentStep > 1) {
                currentStep--;
                showStep(currentStep);
            }
        }

        function populateSummary() {
            const roleName = roleLabels[userData.role] || userData.role;
            document.getElementById('summary-name-role').textContent = `${userData.name} — ${roleName}`;

            const interestNames = Array.from(selectedInterests).map(i => interestLabels[i]).join(', ');
            document.getElementById('summary-interests').textContent = interestNames || 'None selected';

            const accountNames = Array.from(connectedAccounts).map(a => a.charAt(0).toUpperCase() + a.slice(1)).join(', ');
            document.getElementById('summary-accounts').textContent = accountNames || 'None connected';
        }

        function launchConfetti() {
            const container = document.getElementById('confetti-container');
            container.innerHTML = '';
            const colors = ['#6366f1', '#a855f7', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#ef4444', '#8b5cf6'];

            for (let i = 0; i < 80; i++) {
                const confetti = document.createElement('div');
                confetti.className = 'confetti';
                confetti.style.left = Math.random() * 100 + '%';
                confetti.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
                confetti.style.animationDelay = Math.random() * 1.5 + 's';
                confetti.style.animationDuration = (2 + Math.random() * 2) + 's';
                confetti.style.width = (6 + Math.random() * 10) + 'px';
                confetti.style.height = (6 + Math.random() * 10) + 'px';
                confetti.style.borderRadius = Math.random() > 0.5 ? '50%' : '2px';
                confetti.style.opacity = '0';
                container.appendChild(confetti);
            }

            // Clean up confetti after animation
            setTimeout(() => {
                container.innerHTML = '';
            }, 5000);
        }

        // Keyboard navigation
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && currentStep < totalSteps) {
                goNext();
            }
        });

        // Initialize
        showStep(1);
    </script>
</body>
