<script>
    // DOM Elements
    const messageInput = document.getElementById('messageInput');
    const sendBtn = document.getElementById('sendBtn');
    const messagesContainer = document.getElementById('messagesContainer');
    const typingIndicator = document.getElementById('typingIndicator');
    const emojiBtn = document.getElementById('emojiBtn');
    const emojiPicker = document.getElementById('emojiPicker');
    const sidebar = document.getElementById('sidebar');
    const backBtn = document.getElementById('backBtn');
    const attachBtn = document.getElementById('attachBtn');

    // Auto-expanding Textarea
    messageInput.addEventListener('input', function() {
        this.style.height = 'auto';
        this.style.height = (this.scrollHeight) + 'px';
        if(this.value === '') this.style.height = 'auto';
    });

    // Toggle Emoji Picker
    emojiBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        emojiPicker.classList.toggle('show');
    });

    // Close emoji picker when clicking outside
    document.addEventListener('click', (e) => {
        if (!emojiPicker.contains(e.target) && e.target !== emojiBtn) {
            emojiPicker.classList.remove('show');
        }
    });

    // Insert Emoji
    document.querySelectorAll('.emoji-item').forEach(item => {
        item.addEventListener('click', () => {
            messageInput.value += item.textContent;
            messageInput.focus();
            emojiPicker.classList.remove('show');
            // Trigger input event to resize
            messageInput.dispatchEvent(new Event('input'));
        });
    });

    // Mobile Sidebar Toggle
    backBtn.addEventListener('click', () => {
        sidebar.classList.remove('active');
    });

    // Handle Contact Click (Mobile)
    document.querySelectorAll('.contact-item').forEach(item => {
        item.addEventListener('click', () => {
            // Remove active class from all
            document.querySelectorAll('.contact-item').forEach(i => i.classList.remove('active'));
            // Add to clicked
            item.classList.add('active');

            // On mobile, hide sidebar after selection
            if (window.innerWidth <= 768) {
                sidebar.classList.remove('active');
            }
        });
    });

    // Send Message Logic
    function sendMessage() {
        const text = messageInput.value.trim();
        if (!text) return;

        // 1. Add User Message
        addMessage(text, 'sent');
        messageInput.value = '';
        messageInput.style.height = 'auto';

        // 2. Simulate Reply
        simulateReply();
    }

    function addMessage(content, type, isImage = false) {
        const messageDiv = document.createElement('div');
        messageDiv.classList.add('message', type);

        const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

        let bubbleContent = '';
        if (isImage) {
            bubbleContent = `<img src="${content}" class="message-image">`;
        } else {
            bubbleContent = content;
        }

        let readReceipt = '';
        if (type === 'sent') {
            readReceipt = `
                <svg class="read-receipt" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <polyline points="20 6 9 17 4 12"></polyline>
                </svg>`;
        }

        messageDiv.innerHTML = `
            <div class="bubble">${bubbleContent}</div>
            <div class="message-meta">
                ${time}
                ${readReceipt}
            </div>
        `;

        // Insert before typing indicator
        messagesContainer.insertBefore(messageDiv, typingIndicator);
        scrollToBottom();
    }

    function simulateReply() {
        // Show typing indicator
        setTimeout(() => {
            typingIndicator.style.display = 'block';
            scrollToBottom();
        }, 600);

        // Hide typing and send message
        setTimeout(() => {
            typingIndicator.style.display = 'none';
            const replies = [
                "That's awesome! 🔥",
                "Can you send me the details?",
                "I'll check it out later.",
                "Haha, totally agree.",
                "Let's catch up tomorrow."
            ];
            const randomReply = replies[Math.floor(Math.random() * replies.length)];
            addMessage(randomReply, 'received');
        }, 2500);
    }

    function scrollToBottom() {
        messagesContainer.scrollTop = messagesContainer.scrollHeight;
    }

    // Event Listeners
    sendBtn.addEventListener('click', sendMessage);

    messageInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
        }
    });

    // Mock Attachment Button
    attachBtn.addEventListener('click', () => {
        // Simulate sending an image
        const randomImg = `https://picsum.photos/300/200?random=${Math.random()}`;
        addMessage(randomImg, 'sent', true);
        setTimeout(simulateReply, 1000);
    });

    // Initial Scroll
    scrollToBottom();

</script>

</body>
</html>
