        .icon-lg { width: 24px; height: 24px; }

        /* --- Sidebar --- */
        .sidebar {
            width: 350px;
            background-color: var(--bg-sidebar);
            border-right: 1px solid var(--border);
            display: flex;
            flex-direction: column;
            transition: transform 0.3s ease;
            z-index: 10;
        }

        .sidebar-header {
            padding: 20px;
            border-bottom: 1px solid var(--border);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .search-bar {
            padding: 10px 20px;
        }

        .search-input {
            width: 100%;
            background: var(--bg-app);
            border: 1px solid var(--border);
            padding: 10px 15px;
            border-radius: 20px;
            color: var(--text-primary);
            font-size: 14px;
        }

        .contact-list {
            flex: 1;
            overflow-y: auto;
        }

        .contact-item {
            display: flex;
            padding: 15px 20px;
            cursor: pointer;
            transition: background 0.2s;
            border-bottom: 1px solid rgba(255,255,255,0.05);
        }

        .contact-item:hover, .contact-item.active {
            background-color: rgba(255,255,255,0.05);
        }

        .avatar-container {
            position: relative;
            margin-right: 15px;
        }

        .avatar {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            object-fit: cover;
            background: #475569;
        }

        .status-dot {
            position: absolute;
            bottom: 2px;
            right: 2px;
            width: 12px;
            height: 12px;
            background-color: var(--online);
            border: 2px solid var(--bg-sidebar);
            border-radius: 50%;
        }

        .contact-info {
            flex: 1;
            min-width: 0;
        }

        .contact-top {
            display: flex;
            justify-content: space-between;
            margin-bottom: 4px;
        }

        .contact-name { font-weight: 600; font-size: 15px; }
        .contact-time { font-size: 12px; color: var(--text-secondary); }

        .contact-bottom {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .last-message {
            font-size: 13px;
            color: var(--text-secondary);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            max-width: 200px;
        }

        .unread-badge {
            background-color: var(--accent);
            color: white;
            font-size: 11px;
            font-weight: bold;
            padding: 2px 6px;
            border-radius: 10px;
            min-width: 18px;
            text-align: center;
        }

        /* --- Main Chat Area --- */
        .chat-area {
            flex: 1;
            display: flex;
            flex-direction: column;
            background-color: var(--bg-chat);
            position: relative;
        }

        .chat-header {
            padding: 15px 20px;
            background-color: rgba(30, 41, 59, 0.8);
            backdrop-filter: blur(10px);
            border-bottom: 1px solid var(--border);
            display: flex;
            align-items: center;
            z-index: 5;
        }

        .back-btn {
            display: none;
            background: none;
            border: none;
            color: var(--text-primary);
            margin-right: 10px;
            cursor: pointer;
        }

        .header-info {
            display: flex;
            flex-direction: column;
        }

        .header-name { font-weight: 600; font-size: 16px; }
        .header-status { font-size: 12px; color: var(--online); }

        .messages-container {
            flex: 1;
            padding: 20px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 10px;
            scroll-behavior: smooth;
        }

        /* Message Bubbles */
        .message {
            max-width: 70%;
            display: flex;
            flex-direction: column;
            position: relative;
            animation: popIn 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }

        @keyframes popIn {
            from { opacity: 0; transform: scale(0.9) translateY(10px); }
            to { opacity: 1; transform: scale(1) translateY(0); }
        }

        .message.received { align-self: flex-start; }
        .message.sent { align-self: flex-end; align-items: flex-end; }

        .bubble {
            padding: 10px 16px;
            border-radius: 18px;
            font-size: 15px;
            line-height: 1.4;
            position: relative;
            word-wrap: break-word;
        }

        .received .bubble {
            background-color: var(--bg-bubble-received);
            border-bottom-left-radius: 4px;
        }

        .sent .bubble {
            background-color: var(--bg-bubble-sent);
            border-bottom-right-radius: 4px;
        }

        .message-img {
            max-width: 100%;
            border-radius: 12px;
            margin-bottom: 5px;
            display: block;
        }

        .message-meta {
            display: flex;
            align-items: center;
            gap: 4px;
            margin-top: 4px;
            font-size: 11px;
            color: var(--text-secondary);
        }

        .checkmarks {
            display: flex;
            gap: 1px;
        }
        .check { width: 12px; height: 12px; }
        .check.read { color: #60a5fa; } /* Blue for read */

        /* Typing Indicator */
        .typing-indicator {
            display: none;
            align-self: flex-start;
            background-color: var(--bg-bubble-received);
            padding: 10px 15px;
            border-radius: 18px;
            border-bottom-left-radius: 4px;
            margin-bottom: 10px;
            width: fit-content;
        }

        .typing-dots {
            display: flex;
            gap: 4px;
        }

        .dot {
            width: 6px;
            height: 6px;
            background-color: var(--text-secondary);
            border-radius: 50%;
            animation: bounce 1.4s infinite ease-in-out both;
        }

        .dot:nth-child(1) { animation-delay: -0.32s; }
        .dot:nth-child(2) { animation-delay: -0.16s; }

        @keyframes bounce {
            0%, 80%, 100% { transform: scale(0); }
            40% { transform: scale(1); }
        }

        /* Input Area */
        .input-area {
            padding: 15px 20px;
            background-color: var(--bg-sidebar);
            border-top: 1px solid var(--border);
            display: flex;
            align-items: flex-end;
            gap: 10px;
        }

        .input-wrapper {
            flex: 1;
            background-color: var(--bg-app);
            border-radius: 24px;
            padding: 8px 15px;
            display: flex;
            align-items: center;
            border: 1px solid var(--border);
        }

        .action-btn {
            background: none;
            border: none;
            color: var(--text-secondary);
            cursor: pointer;
            padding: 5px;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: color 0.2s;
        }

        .action-btn:hover { color: var(--text-primary); }

        textarea {
            flex: 1;
            background: transparent;
            border: none;
            color: var(--text-primary);
            font-size: 15px;
            max-height: 100px;
            resize: none;
            padding: 8px 0;
            font-family: inherit;
            line-height: 1.4;
        }

        .send-btn {
            background-color: var(--accent);
            color: white;
            border: none;
            width: 40px;
            height: 40px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: transform 0.1s;
            flex-shrink: 0;
        }

        .send-btn:active { transform: scale(0.9); }

        /* Emoji Picker */
        .emoji-picker {
            position: absolute;
            bottom: 80px;
            left: 20px;
            background-color: var(--bg-sidebar);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 10px;
            display: grid;
            grid-template-columns: repeat(6, 1fr);
            gap: 5px;
            box-shadow: 0 10px 25px rgba(0,0,0,0.5);
            z-index: 20;
            display: none;
        }

        .emoji-picker.show { display: grid; animation: popIn 0.2s; }

        .emoji-item {
            font-size: 20px;
            cursor: pointer;
            text-align: center;
            padding: 5px;
            border-radius: 5px;
        }
        .emoji-item:hover { background-color: rgba(255,255,255,0.1); }

        /* Responsive */
        @media (max-width: 768px) {
            .sidebar {
                position: absolute;
                height: 100%;
                width: 100%;
                transform: translateX(-100%);
            }
            .sidebar.open { transform: translateX(0); }

            .back-btn { display: block; }

            .chat-area { width: 100%; }
        }
    </style>
</head>
