    <script>
        // --- Data ---
        const contacts = [
            { id: 1, name: "Josh Miller", avatar: "https://i.pravatar.cc/150?u=1", status: "online", lastMsg: "Sounds good! See you then.", time: "10:42 AM", unread: 2 },
            { id: 2, name: "Sarah Connor", avatar: "https://i.pravatar.cc/150?u=2", status: "offline", lastMsg: "Did you see the new design?", time: "Yesterday", unread: 0 },
            { id: 3, name: "Design Team", avatar: "https://i.pravatar.cc/150?u=3", status: "online", lastMsg: "Alex: I'll push the update.", time: "Yesterday", unread: 5 },
            { id: 4, name: "Mom", avatar: "https://i.pravatar.cc/150?u=4", status: "online", lastMsg: "Call me when you can ❤️", time: "Tue", unread: 0 },
            { id: 5, name: "John Doe", avatar: "https://i.pravatar.cc/150?u=5", status: "offline", lastMsg: "Thanks for the help!", time: "Mon", unread: 0 },
        ];

        const conversations = {
            1: [
                { id: 1, type: 'received', text: "Hey! Are we still on for lunch?", time: "10:30 AM", status: 'read' },
                { id: 2, type: 'sent', text: "Yes, absolutely. 1 PM right?", time: "10:32 AM", status: 'read' },
                { id: 3, type: 'received', text: "Yep! That new Italian place.", time: "10:33 AM", status: 'read' },
                { id: 4, type: 'sent', text: "Perfect. I'm craving pasta.", time: "10:35 AM", status: 'read' },
                { id: 5, type: 'received', text: "Sounds good! See you then.", time: "10:42 AM", status: 'delivered' }
            ],
            2: [
                { id: 1, type: 'received', text: "Check out this mockup.", time: "Yesterday", status: 'read', image: "https://picsum.photos/300/200?random=1" },
                { id: 2, type: 'sent', text: "Looks clean. I like the dark mode.", time: "Yesterday", status: 'read' },
                { id: 3, type: 'received', text: "Did you see the new design?", time: "Yesterday", status: 'delivered' }
            ],
            3: [
                { id: 1, type: 'received', text: "Meeting in 5 mins.", time: "Yesterday", status: 'read' },
                { id: 2, type: 'sent', text: "Joining now.", time: "Yesterday", status: 'read' }
            ],
            4: [
                { id: 1, type: 'received', text: "Happy Birthday! 🎂", time: "Mon", status: 'read' },
                { id: 2, type: 'sent', text: "Thanks Mom!", time: "Mon", status: 'read' }
            ],
            5: []
        };

        const emojis = ["😀", "😂", "😍", "🤔", "👍", "👎", "🎉", "🔥", "❤️", "😭", "😎", "🤡", "👻", "👽", "🤖", "💩"];

        // --- State ---
        let activeChatId = 1;
        let isSidebarOpen = false;

        // --- DOM Elements ---
        const contactListEl = document.getElementById('contactList');
        const messagesContainer = document.getElementById('messagesContainer');
        const messageInput = document.getElementById('messageInput');
        const sendBtn = document.getElementById('sendBtn');
        const typingIndicator = document.getElementById('typingIndicator');
        const emojiPicker = document.getElementById('emojiPicker');
        const emojiBtn = document.getElementById('emojiBtn');
        const backBtn = document.getElementById('backBtn');
        const sidebar = document.getElementById('sidebar');

        // Header Elements
        const headerName = document.getElementById('headerName');
        const headerStatus = document.getElementById('headerStatus');
        const headerAvatar = document.getElementById('headerAvatar');
        const headerStatusDot = document.getElementById('headerStatusDot');

        // --- Initialization ---
        function init() {
            renderContactList();
            loadChat(activeChatId);
            setupEventListeners();
            renderEmojiPicker();

            // Auto-resize textarea
            messageInput.addEventListener('input', function() {
                this.style.height = 'auto';
                this.style.height = (this.scrollHeight) + 'px';
                if(this.value === '') this.style.height = 'auto';
            });
        }

        // --- Rendering ---
        function renderContactList() {
            contactListEl.innerHTML = '';
            contacts.forEach(contact => {
                const isActive = contact.id === activeChatId ? 'active' : '';
                const unreadBadge = contact.unread > 0 
                    ? `<span class="unread-badge">${contact.unread}</span>` 
                    : '';

                const html = `
                    <div class="contact-item ${isActive}" onclick="switchChat(${contact.id})">
                        <div class="avatar-container">
                            <img src="${contact.avatar}" class="avatar" alt="${contact.name}">
                            ${contact.status === 'online' ? '<div class="status-dot"></div>' : ''}
                        </div>
                        <div class="contact-info">
                            <div class="contact-top">
                                <span class="contact-name">${contact.name}</span>
                                <span class="contact-time">${contact.time}</span>
                            </div>
                            <div class="contact-bottom">
                                <span class="last-message">${contact.lastMsg}</span>
                                ${unreadBadge}
                            </div>
                        </div>
                    </div>
                `;
                contactListEl.innerHTML += html;
            });
        }

        function loadChat(id) {
            activeChatId = id;
            const contact = contacts.find(c => c.id === id);
            const messages = conversations[id] || [];

            // Update Header
            headerName.textContent = contact.name;
            headerAvatar.src = contact.avatar;
            headerStatus.textContent = contact.status === 'online' ? 'Online' : 'Last seen recently';
            headerStatus.style.color = contact.status === 'online' ? 'var(--online)' : 'var(--text-secondary)';
            headerStatusDot.style.display = contact.status === 'online' ? 'block' : 'none';

            // Update Sidebar Active State
            renderContactList();

            // Render Messages
            messagesContainer.innerHTML = '';
            messagesContainer.appendChild(typingIndicator); // Keep typing indicator at bottom

            messages.forEach(msg => {
                appendMessageToDOM(msg);
            });

            scrollToBottom();

            // Mobile: Close sidebar when chat selected
            if (window.innerWidth <= 768) {
                sidebar.classList.remove('open');
            }
        }

        function appendMessageToDOM(msg) {
            const msgDiv = document.createElement('div');
            msgDiv.className = `message ${msg.type}`;

            let contentHtml = '';
            if (msg.image) {
                contentHtml += `<img src="${msg.image}" class="message-img">`;
            }
            if (msg.text) {
                contentHtml += `<div class="bubble-text">${msg.text}</div>`;
            }

            let metaHtml = `<span class="time">${msg.time}</span>`;
            if (msg.type === 'sent') {
                const checkClass = msg.status === 'read' ? 'read' : '';
                metaHtml += `
                    <div class="checkmarks">
                        <svg class="check ${checkClass}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"></polyline></svg>
                        <svg class="check ${checkClass}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"></polyline></svg>
                    </div>
                `;
            }

            msgDiv.innerHTML = `
                ${contentHtml}
                <div class="message-meta">${metaHtml}</div>
            `;

            // Insert before typing indicator
            messagesContainer.insertBefore(msgDiv, typingIndicator);
        }

        function renderEmojiPicker() {
            emojis.forEach(emoji => {
                const span = document.createElement('span');
                span.className = 'emoji-item';
                span.textContent = emoji;
                span.onclick = () => {
                    messageInput.value += emoji;
                    messageInput.focus();
                    emojiPicker.classList.remove('show');
                };
                emojiPicker.appendChild(span);
            });
        }

        // --- Logic ---

        function switchChat(id) {
            if (id === activeChatId) return;
            loadChat(id);
        }

        function scrollToBottom() {
            messagesContainer.scrollTop = messagesContainer.scrollHeight;
        }

        function getCurrentTime() {
            const now = new Date();
            return now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        }

        function sendMessage() {
            const text = messageInput.value.trim();
            if (!text) return;

            const newMsg = {
                id: Date.now(),
                type: 'sent',
                text: text,
                time: getCurrentTime(),
                status: 'delivered'
            };

            conversations[activeChatId].push(newMsg);
            appendMessageToDOM(newMsg);

            // Update contact list preview
            const contact = contacts.find(c => c.id === activeChatId);
            contact.lastMsg = "You: " + text;
            contact.time = getCurrentTime();
            renderContactList();

            messageInput.value = '';
            messageInput.style.height = 'auto';
            scrollToBottom();

            // Simulate Reply
            simulateReply();
        }

        function simulateReply() {
            // Show typing indicator
            setTimeout(() => {
                typingIndicator.style.display = 'block';
                scrollToBottom();
                headerStatus.textContent = "typing...";
            }, 1000);

            // Send message
            setTimeout(() => {
                typingIndicator.style.display = 'none';
                headerStatus.textContent = "Online";

                const replies = ["That's interesting!", "Can you send me the details?", "Haha, totally!", "Okay, got it.", "👍"];
                const randomReply = replies[Math.floor(Math.random() * replies.length)];

                const replyMsg = {
                    id: Date.now(),
                    type: 'received',
                    text: randomReply,
                    time: getCurrentTime(),
                    status: 'read'
                };

                conversations[activeChatId].push(replyMsg);
                appendMessageToDOM(replyMsg);

                const contact = contacts.find(c => c.id === activeChatId);
                contact.lastMsg = randomReply;
                contact.time = getCurrentTime();
                contact.unread += 1;
                renderContactList();

                scrollToBottom();

                // Mark as read after 2 seconds
                setTimeout(() => {
                    const lastSent = conversations[activeChatId].filter(m => m.type === 'sent').pop();
                    if(lastSent) {
                        lastSent.status = 'read';
                        // Re-render last message to update checks (simplified: just reload chat for demo)
                        // In prod, update DOM specifically
                        loadChat(activeChatId); 
                    }
                }, 2000);

            }, 3000);
        }

        function setupEventListeners() {
            sendBtn.addEventListener('click', sendMessage);

            messageInput.addEventListener('keypress', (e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                }
            });

            emojiBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                emojiPicker.classList.toggle('show');
            });

            document.addEventListener('click', (e) => {
                if (!emojiPicker.contains(e.target) && e.target !== emojiBtn) {
                    emojiPicker.classList.remove('show');
                }
            });

            backBtn.addEventListener('click', () => {
                sidebar.classList.add('open');
            });
        }

        // Start
        init();

    </script>
</body>
