        .search-box {
            width: 100%;
            padding: 10px 15px;
            background: #0d1117;
            border: 1px solid #30363d;
            border-radius: 8px;
            color: #e6edf3;
            font-size: 14px;
            outline: none;
            transition: border-color 0.2s;
        }

        .search-box:focus {
            border-color: #58a6ff;
        }

        .contacts-list {
            flex: 1;
            overflow-y: auto;
        }

        .contact-item {
            display: flex;
            align-items: center;
            padding: 15px 20px;
            cursor: pointer;
            transition: background 0.2s;
            border-bottom: 1px solid #21262d;
            position: relative;
        }

        .contact-item:hover {
            background: #1c2128;
        }

        .contact-item.active {
            background: #1c2128;
            border-left: 3px solid #58a6ff;
        }

        .contact-avatar {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            margin-right: 15px;
            position: relative;
            flex-shrink: 0;
        }

        .contact-avatar img {
            width: 100%;
            height: 100%;
            border-radius: 50%;
            object-fit: cover;
        }

        .online-indicator {
            width: 14px;
            height: 14px;
            background: #3fb950;
            border: 2px solid #161b22;
            border-radius: 50%;
            position: absolute;
            bottom: 0;
            right: 0;
        }

        .online-indicator.offline {
            background: #6e7681;
        }

        .contact-info {
            flex: 1;
            min-width: 0;
        }

        .contact-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 5px;
        }

        .contact-name {
            font-weight: 600;
            font-size: 15px;
        }

        .contact-time {
            font-size: 12px;
            color: #7d8590;
        }

        .contact-preview {
            font-size: 14px;
            color: #7d8590;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .contact-preview.unread {
            color: #e6edf3;
            font-weight: 500;
        }

        .unread-badge {
            background: #58a6ff;
            color: #fff;
            border-radius: 10px;
            padding: 2px 8px;
            font-size: 11px;
            font-weight: 600;
            margin-left: auto;
        }

        /* Main Chat Area */
        .chat-area {
            flex: 1;
            display: flex;
            flex-direction: column;
            background: #0d1117;
        }

        .chat-header {
            padding: 15px 25px;
            background: #161b22;
            border-bottom: 1px solid #30363d;
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .menu-toggle {
            display: none;
            background: none;
            border: none;
            color: #e6edf3;
            font-size: 24px;
            cursor: pointer;
            padding: 5px;
        }

        .chat-header-avatar {
            width: 45px;
            height: 45px;
            border-radius: 50%;
            position: relative;
        }

        .chat-header-avatar img {
            width: 100%;
            height: 100%;
            border-radius: 50%;
            object-fit: cover;
        }

        .chat-header-info {
            flex: 1;
        }

        .chat-header-name {
            font-weight: 600;
            font-size: 16px;
            margin-bottom: 3px;
        }

        .chat-header-status {
            font-size: 13px;
            color: #7d8590;
        }

        .chat-header-status.online {
            color: #3fb950;
        }

        /* Messages Area */
        .messages-area {
            flex: 1;
            overflow-y: auto;
            padding: 20px 25px;
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .message-group {
            display: flex;
            flex-direction: column;
            gap: 4px;
            animation: messageSlideIn 0.3s ease;
        }

        @keyframes messageSlideIn {
            from {
                opacity: 0;
                transform: translateY(10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .message {
            display: flex;
            gap: 10px;
            max-width: 70%;
        }

        .message.sent {
            align-self: flex-end;
            flex-direction: row-reverse;
        }

        .message-avatar {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            flex-shrink: 0;
        }

        .message-avatar img {
            width: 100%;
            height: 100%;
            border-radius: 50%;
            object-fit: cover;
        }

        .message-content {
            display: flex;
            flex-direction: column;
            gap: 5px;
        }

        .message-bubble {
            padding: 10px 15px;
            border-radius: 18px;
            word-wrap: break-word;
            position: relative;
        }

        .message.received .message-bubble {
            background: #21262d;
            border-bottom-left-radius: 4px;
        }

        .message.sent .message-bubble {
            background: #1f6feb;
            border-bottom-right-radius: 4px;
            color: #fff;
        }

        .message-bubble.image {
            padding: 4px;
            background: transparent;
        }

        .message-bubble img {
            max-width: 300px;
            border-radius: 12px;
            display: block;
        }

        .message-meta {
            display: flex;
            align-items: center;
            gap: 5px;
            font-size: 11px;
            color: #7d8590;
            padding: 0 5px;
        }

        .message.sent .message-meta {
            justify-content: flex-end;
        }

        .read-receipt {
            display: flex;
            gap: 1px;
        }

        .checkmark {
            width: 14px;
            height: 14px;
            color: #58a6ff;
        }

        /* Typing Indicator */
        .typing-indicator {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 10px 0;
            animation: messageSlideIn 0.3s ease;
        }

        .typing-dots {
            display: flex;
            gap: 4px;
            padding: 12px 15px;
            background: #21262d;
            border-radius: 18px;
            border-bottom-left-radius: 4px;
        }

        .typing-dot {
            width: 8px;
            height: 8px;
            background: #7d8590;
            border-radius: 50%;
            animation: typingAnimation 1.4s infinite;
        }

        .typing-dot:nth-child(2) {
            animation-delay: 0.2s;
        }

        .typing-dot:nth-child(3) {
            animation-delay: 0.4s;
        }

        @keyframes typingAnimation {
            0%, 60%, 100% {
                transform: translateY(0);
                opacity: 0.7;
            }
            30% {
                transform: translateY(-10px);
                opacity: 1;
            }
        }

        /* Input Area */
        .input-area {
            padding: 20px 25px;
            background: #161b22;
            border-top: 1px solid #30363d;
        }

        .input-container {
            display: flex;
            align-items: flex-end;
            gap: 10px;
            background: #0d1117;
            border: 1px solid #30363d;
            border-radius: 24px;
            padding: 8px 15px;
            transition: border-color 0.2s;
        }

        .input-container:focus-within {
            border-color: #58a6ff;
        }

        .input-actions {
            display: flex;
            gap: 5px;
        }

        .input-btn {
            background: none;
            border: none;
            color: #7d8590;
            cursor: pointer;
            padding: 8px;
            border-radius: 50%;
            transition: all 0.2s;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .input-btn:hover {
            background: #21262d;
            color: #e6edf3;
        }

        .message-input {
            flex: 1;
            background: none;
            border: none;
            color: #e6edf3;
            font-size: 15px;
            resize: none;
            outline: none;
            max-height: 120px;
            min-height: 24px;
            font-family: inherit;
            line-height: 1.5;
        }

        .send-btn {
            background: #1f6feb;
            color: #fff;
            border: none;
            padding: 8px 12px;
            border-radius: 50%;
            cursor: pointer;
            transition: all 0.2s;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .send-btn:hover {
            background: #1a5cd7;
            transform: scale(1.05);
        }

        .send-btn:disabled {
            background: #30363d;
            cursor: not-allowed;
            transform: scale(1);
        }

        /* Emoji Picker */
        .emoji-picker {
            position: absolute;
            bottom: 80px;
            right: 25px;
            background: #161b22;
            border: 1px solid #30363d;
            border-radius: 12px;
            padding: 15px;
            box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
            display: none;
            z-index: 1000;
            animation: popIn 0.2s ease;
        }

        @keyframes popIn {
            from {
                opacity: 0;
                transform: scale(0.9) translateY(10px);
            }
            to {
                opacity: 1;
                transform: scale(1) translateY(0);
            }
        }

        .emoji-picker.show {
            display: block;
        }

        .emoji-grid {
            display: grid;
            grid-template-columns: repeat(8, 1fr);
            gap: 8px;
            max-width: 320px;
        }

        .emoji-item {
            font-size: 24px;
            cursor: pointer;
            padding: 8px;
            border-radius: 8px;
            transition: all 0.2s;
            text-align: center;
        }

        .emoji-item:hover {
            background: #21262d;
            transform: scale(1.2);
        }

        /* Scrollbar */
        ::-webkit-scrollbar {
            width: 8px;
        }

        ::-webkit-scrollbar-track {
            background: #0d1117;
        }

        ::-webkit-scrollbar-thumb {
            background: #30363d;
            border-radius: 4px;
        }

        ::-webkit-scrollbar-thumb:hover {
            background: #484f58;
        }

        /* Mobile Responsive */
        @media (max-width: 768px) {
            .sidebar {
                position: absolute;
                left: 0;
                top: 0;
                height: 100%;
                z-index: 100;
                transform: translateX(-100%);
            }

            .sidebar.show {
                transform: translateX(0);
            }

            .menu-toggle {
                display: block;
            }

            .message {
                max-width: 85%;
            }

            .emoji-picker {
                right: 10px;
                left: 10px;
                max-width: calc(100% - 20px);
            }

            .emoji-grid {
                max-width: 100%;
            }
        }

        /* Overlay for mobile */
        .overlay {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.5);
            z-index: 99;
        }

        .overlay.show {
            display: block;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="sidebar" id="sidebar">
            <div class="sidebar-header">
                <h2>Messages</h2>
                <input type="text" class="search-box" placeholder="Search conversations...">
            </div>
            <div class="contacts-list" id="contactsList">
                <!-- Contacts will be populated by JavaScript -->
            </div>
        </div>

        <div class="chat-area">
            <div class="chat-header">
                <button class="menu-toggle" id="menuToggle">☰</button>
                <div class="chat-header-avatar">
                    <img src="https://i.pravatar.cc/150?img=12" alt="Avatar" id="headerAvatar">
                    <div class="online-indicator" id="headerOnline"></div>
                </div>
                <div class="chat-header-info">
                    <div class="chat-header-name" id="headerName">Sarah Johnson</div>
                    <div class="chat-header-status online" id="headerStatus">Online</div>
                </div>
            </div>

            <div class="messages-area" id="messagesArea">
                <!-- Messages will be populated by JavaScript -->
            </div>

            <div class="input-area">
                <div class="input-container">
                    <div class="input-actions">
                        <button class="input-btn" id="attachBtn" title="Attach file">
                            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/>
                            </svg>
                        </button>
                        <button class="input-btn" id="emojiBtn" title="Emoji">
                            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <circle cx="12" cy="12" r="10"/>
                                <path d="M8 14s1.5 2 4 2 4-2 4-2"/>
                                <line x1="9" y1="9" x2="9.01" y2="9"/>
                                <line x1="15" y1="9" x2="15.01" y2="9"/>
                            </svg>
                        </button>
                    </div>
                    <textarea class="message-input" id="messageInput" placeholder="Type a message..." rows="1"></textarea>
                    <button class="send-btn" id="sendBtn" disabled>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <line x1="22" y1="2" x2="11" y2="13"/>
                            <polygon points="22 2 15 22 11 13 2 9 22 2"/>
                        </svg>
                    </button>
                </div>
            </div>
        </div>

        <div class="emoji-picker" id="emojiPicker">
            <div class="emoji-grid" id="emojiGrid">
                <!-- Emojis will be populated by JavaScript -->
            </div>
        </div>
    </div>

    <div class="overlay" id="overlay"></div>

    <script>
        // Sample data
        const contacts = [
            {
                id: 1,
                name: 'Sarah Johnson',
                avatar: 'https://i.pravatar.cc/150?img=12',
                online: true,
                lastMessage: 'See you tomorrow! 😊',
                time: '2m ago',
                unread: 0,
                typing: false
            },
            {
                id: 2,
                name: 'Mike Chen',
                avatar: 'https://i.pravatar.cc/150?img=13',
                online: true,
                lastMessage: 'Thanks for the help!',
                time: '15m ago',
                unread: 2,
                typing: false
            },
            {
                id: 3,
                name: 'Emma Wilson',
                avatar: 'https://i.pravatar.cc/150?img=45',
                online: false,
                lastMessage: 'Let me know when you\'re free',
