            },
            {
                id: 6,
                name: 'David Kim',
                avatar: 'https://i.pravatar.cc/150?img=52',
                online: true,
                lastMessage: '👍',
                time: 'Yesterday',
                unread: 0,
                typing: false
            }
        ];

        const messages = {
            1: [
                { id: 1, type: 'received', content: 'Hey! How are you doing?', time: '10:30 AM', read: true },
                { id: 2, type: 'sent', content: 'I\'m doing great! Just finished that project we talked about.', time: '10:32 AM', read: true },
                { id: 3, type: 'received', content: 'That\'s awesome! How did it turn out?', time: '10:33 AM', read: true },
                { id: 4, type: 'sent', content: 'Really well! The client loved it. Check out this screenshot:', time: '10:35 AM', read: true },
                { id: 5, type: 'sent', content: 'https://via.placeholder.com/400x300/1f6feb/ffffff?text=Project+Screenshot', time: '10:35 AM', read: true, image: true },
                { id: 6, type: 'received', content: 'Wow, that looks amazing! Great work! 🎉', time: '10:37 AM', read: true },
                { id: 7, type: 'sent', content: 'Thanks! Want to grab coffee tomorrow to celebrate?', time: '10:38 AM', read: true },
                { id: 8, type: 'received', content: 'See you tomorrow! 😊', time: '10:40 AM', read: true }
            ],
            2: [
                { id: 1, type: 'received', content: 'Can you help me with the deployment?', time: '9:15 AM', read: true },
                { id: 2, type: 'sent', content: 'Sure! What do you need help with?', time: '9:20 AM', read: true },
                { id: 3, type: 'received', content: 'I\'m getting an error with the build process', time: '9:22 AM', read: true },
                { id: 4, type: 'sent', content: 'Let me take a look. Can you share the error message?', time: '9:23 AM', read: true },
                { id: 5, type: 'received', content: 'Thanks for the help!', time: '9:45 AM', read: false }
            ]
        };

        const emojis = ['😀', '😃', '😄', '😁', '😅', '😂', '🤣', '😊', '😇', '🙂', '🙃', '😉', '😌', '😍', '🥰', '😘', '😗', '😙', '😚', '😋', '😛', '😝', '😜', '🤪', '🤨', '🧐', '🤓', '😎', '🤩', '🥳', '😏', '😒', '😞', '😔', '😟', '😕', '🙁', '😣', '😖', '😫', '😩', '🥺', '😢', '😭', '😤', '😠', '😡', '🤬', '🤯', '😳', '🥵', '🥶', '😱', '😨', '😰', '😥', '😓', '🤗', '🤔', '🤭', '🤫', '🤥', '😶', '😐', '😑', '😬', '🙄', '😯', '😦', '😧', '😮', '😲', '🥱', '😴', '🤤', '😪', '😵', '🤐', '🥴', '🤢', '🤮', '🤧', '😷', '🤒', '🤕', '🤑', '🤠', '👍', '👎', '👌', '✌️', '🤞', '🤟', '🤘', '🤙', '👏', '🙌', '👐', '🤲', '🤝', '🙏', '❤️', '🧡', '💛', '💚', '💙', '💜', '🖤', '🤍', '🤎', '💔', '❣️', '💕', '💞', '💓', '💗', '💖', '💘', '💝', '🔥', '✨', '💫', '⭐', '🌟', '💯', '🎉', '🎊', '🎈'];

        let currentContactId = 1;
        let isTyping = false;

        // Initialize
        function init() {
            renderContacts();
            renderMessages(currentContactId);
            setupEventListeners();
            renderEmojis();
            autoExpandTextarea();
        }

        // Render contacts list
        function renderContacts() {
            const contactsList = document.getElementById('contactsList');
            contactsList.innerHTML = contacts.map(contact => `
                <div class="contact-item ${contact.id === currentContactId ? 'active' : ''}" data-id="${contact.id}">
                    <div class="contact-avatar">
                        <img src="${contact.avatar}" alt="${contact.name}">
                        <div class="online-indicator ${contact.online ? '' : 'offline'}"></div>
                    </div>
                    <div class="contact-info">
                        <div class="contact-header">
                            <div class="contact-name">${contact.name}</div>
                            <div class="contact-time">${contact.time}</div>
                        </div>
                        <div class="contact-preview ${contact.unread > 0 ? 'unread' : ''}">
                            <span>${contact.lastMessage}</span>
                            ${contact.unread > 0 ? `<span class="unread-badge">${contact.unread}</span>` : ''}
                        </div>
                    </div>
                </div>
            `).join('');
        }

        // Render messages
        function renderMessages(contactId) {
            const messagesArea = document.getElementById('messagesArea');
            const contactMessages = messages[contactId] || [];
            const contact = contacts.find(c => c.id === contactId);

            messagesArea.innerHTML = contactMessages.map(msg => {
                if (msg.image) {
                    return `
                        <div class="message-group">
                            <div class="message ${msg.type}">
                                ${msg.type === 'received' ? `<div class="message-avatar"><img src="${contact.avatar}" alt="${contact.name}"></div>` : ''}
                                <div class="message-content">
                                    <div class="message-bubble image">
                                        <img src="${msg.content}" alt="Image">
                                    </div>
                                    <div class="message-meta">
                                        <span>${msg.time}</span>
                                        ${msg.type === 'sent' ? `
                                            <div class="read-receipt">
                                                <svg class="checkmark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                                    <polyline points="20 6 9 17 4 12"/>
                                                </svg>
                                                <svg class="checkmark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                                    <polyline points="20 6 9 17 4 12"/>
                                                </svg>
                                            </div>
                                        ` : ''}
                                    </div>
                                </div>
                            </div>
                        </div>
                    `;
                }
                return `
                    <div class="message-group">
                        <div class="message ${msg.type}">
                            ${msg.type === 'received' ? `<div class="message-avatar"><img src="${contact.avatar}" alt="${contact.name}"></div>` : ''}
                            <div class="message-content">
                                <div class="message-bubble">${msg.content}</div>
                                <div class="message-meta">
                                    <span>${msg.time}</span>
                                    ${msg.type === 'sent' ? `
                                        <div class="read-receipt">
                                            <svg class="checkmark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                                <polyline points="20 6 9 17 4 12"/>
                                            </svg>
                                            <svg class="checkmark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                                <polyline points="20 6 9 17 4 12"/>
                                            </svg>
                                        </div>
                                    ` : ''}
                                </div>
                            </div>
                        </div>
                    </div>
                `;
            }).join('');

            // Add typing indicator if contact is typing
            if (contact.typing) {
                messagesArea.innerHTML += `
                    <div class="typing-indicator">
                        <div class="message-avatar"><img src="${contact.avatar}" alt="${contact.name}"></div>
                        <div class="typing-dots">
                            <div class="typing-dot"></div>
                            <div class="typing-dot"></div>
                            <div class="typing-dot"></div>
                        </div>
                    </div>
                `;
            }

            messagesArea.scrollTop = messagesArea.scrollHeight;
        }

        // Update chat header
        function updateChatHeader(contactId) {
            const contact = contacts.find(c => c.id === contactId);
            document.getElementById('headerName').textContent = contact.name;
            document.getElementById('headerAvatar').src = contact.avatar;
            document.getElementById('headerStatus').textContent = contact.online ? 'Online' : 'Offline';
            document.getElementById('headerStatus').className = `chat-header-status ${contact.online ? 'online' : ''}`;
            document.getElementById('headerOnline').className = `online-indicator ${contact.online ? '' : 'offline'}`;
        }

        // Send message
        function sendMessage() {
            const input = document.getElementById('messageInput');
            const content = input.value.trim();

            if (!content) return;

            const newMessage = {
                id: Date.now(),
                type: 'sent',
                content: content,
                time: new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
                read: false
            };

            if (!messages[currentContactId]) {
                messages[currentContactId] = [];
            }
            messages[currentContactId].push(newMessage);

            // Update contact's last message
            const contact = contacts.find(c => c.id === currentContactId);
            contact.lastMessage = content;
            contact.time = 'Just now';

            renderMessages(currentContactId);
            renderContacts();
            input.value = '';
            input.style.height = 'auto';
            document.getElementById('sendBtn').disabled = true;

            // Simulate typing response
            setTimeout(() => {
                simulateTyping();
            }, 2000);
        }

        // Simulate typing indicator
        function simulateTyping() {
            const contact = contacts.find(c => c.id === currentContactId);
            contact.typing = true;
            renderMessages(currentContactId);
            document.getElementById('headerStatus').textContent = 'typing...';

            setTimeout(() => {
                contact.typing = false;
                const responses = [
                    'That sounds great!',
                    'I agree! 👍',
                    'Absolutely!',
                    'Let me think about it',
                    'Perfect timing!'
                ];
                const response = responses[Math.floor(Math.random() * responses.length)];

                const newMessage = {
                    id: Date.now(),
                    type: 'received',
                    content: response,
                    time: new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
                    read: true
                };

                messages[currentContactId].push(newMessage);
                contact.lastMessage = response;
                contact.time = 'Just now';

                renderMessages(currentContactId);
                renderContacts();
                updateChatHeader(currentContactId);
            }, 3000);
        }

        // Render emojis
        function renderEmojis() {
            const emojiGrid = document.getElementById('emojiGrid');
            emojiGrid.innerHTML = emojis.map(emoji => 
                `<div class="emoji-item" data-emoji="${emoji}">${emoji}</div>`
            ).join('');
        }

        // Auto-expand textarea
        function autoExpandTextarea() {
            const textarea = document.getElementById('messageInput');
            textarea.addEventListener('input', function() {
                this.style.height = 'auto';
                this.style.height = Math.min(this.scrollHeight, 120) + 'px';

                document.getElementById('sendBtn').disabled = !this.value.trim();
            });
        }

        // Setup event listeners
        function setupEventListeners() {
            // Contact selection
            document.getElementById('contactsList').addEventListener('click', (e) => {
                const contactItem = e.target.closest('.contact-item');
                if (contactItem) {
                    currentContactId = parseInt(contactItem.dataset.id);
                    renderContacts();
                    renderMessages(currentContactId);
                    updateChatHeader(currentContactId);

                    // Hide sidebar on mobile
                    if (window.innerWidth <= 768) {
                        document.getElementById('sidebar').classList.remove('show');
                        document.getElementById('overlay').classList.remove('show');
                    }
                }
            });

            // Send button
            document.getElementById('sendBtn').addEventListener('click', sendMessage);

            // Enter to send
            document.getElementById('messageInput').addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                }
            });

            // Emoji picker
            document.getElementById('emojiBtn').addEventListener('click', (e) => {
                e.stopPropagation();
                document.getElementById('emojiPicker').classList.toggle('show');
            });

            // Emoji selection
            document.getElementById('emojiGrid').addEventListener('click', (e) => {
                if (e.target.classList.contains('emoji-item')) {
                    const input = document.getElementById('messageInput');
                    input.value += e.target.dataset.emoji;
                    input.focus();
                    document.getElementById('sendBtn').disabled = false;
                    document.getElementById('emojiPicker').classList.remove('show');
                }
            });

            // Close emoji picker when clicking outside
            document.addEventListener('click', (e) => {
                if (!e.target.closest('.emoji-picker') && !e.target.closest('#emojiBtn')) {
                    document.getElementById('emojiPicker').classList.remove('show');
                }
            });

            // Attach button (placeholder)
            document.getElementById('attachBtn').addEventListener('click', () => {
                alert('File attachment feature would open file picker here');
            });

            // Mobile menu toggle
            document.getElementById('menuToggle').addEventListener('click', () => {
                document.getElementById('sidebar').classList.add('show');
                document.getElementById('overlay').classList.add('show');
            });

            // Overlay click
            document.getElementById('overlay').addEventListener('click', () => {
                document.getElementById('sidebar').classList.remove('show');
                document.getElementById('overlay').classList.remove('show');
            });

            // Handle window resize
            window.addEventListener('resize', () => {
                if (window.innerWidth > 768) {
                    document.getElementById('sidebar').classList.remove('show');
                    document.getElementById('overlay').classList.remove('show');
                }
            });
        }

        // Initialize app
        init();
    </script>
</body>
