        const emojis = ['😀', '😂', '🥰', '😎', '🤔', '😅', '🙌', '👍', '❤️', '🔥', '✨', '🎉', '💯', '🙏', '😊', '🤗', '😍', '🥳', '😇', '🤩', '😋', '🤭', '😏', '🥺', '😢', '😤', '🤯', '😱', '🤮', '💀', '👻', '🎃'];

        let activeContactId = 1;

        // DOM Elements
        const contactsList = document.getElementById('contactsList');
        const messagesContainer = document.getElementById('messagesContainer');
        const messageInput = document.getElementById('messageInput');
        const sendBtn = document.getElementById('sendBtn');
        const emojiBtn = document.getElementById('emojiBtn');
        const emojiPicker = document.getElementById('emojiPicker');
        const attachBtn = document.getElementById('attachBtn');
        const menuBtn = document.getElementById('menuBtn');
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('overlay');
        const typingIndicator = document.getElementById('typingIndicator');
        const typingText = document.getElementById('typingText');
        const headerAvatar = document.getElementById('headerAvatar');
        const headerName = document.getElementById('headerName');
        const headerStatus = document.getElementById('headerStatus');

        // Render contacts
        function renderContacts() {
            contactsList.innerHTML = contacts.map(contact => `
                <div class="contact-item ${contact.id === activeContactId ? 'active' : ''}" data-id="${contact.id}">
                    <div class="contact-avatar">
                        <img src="${contact.avatar}" alt="${contact.name}">
                        ${contact.online ? '<div class="online-indicator"></div>' : ''}
                    </div>
                    <div class="contact-info">
                        <div class="contact-name">${contact.name}</div>
                        <div class="contact-preview">${contact.lastMessage}</div>
                    </div>
                    <div class="contact-meta">
                        <span class="contact-time">${contact.lastTime}</span>
                        ${contact.unread > 0 ? `<span class="unread-badge">${contact.unread}</span>` : ''}
                    </div>
                </div>
            `).join('');

            // Add click listeners
            document.querySelectorAll('.contact-item').forEach(item => {
                item.addEventListener('click', () => {
                    const id = parseInt(item.dataset.id);
                    selectContact(id);
                });
            });
        }

        // Render messages
        function renderMessages(contactId) {
            const messages = conversations[contactId] || [];
            messagesContainer.innerHTML = `
                <div class="date-separator"><span>Today</span></div>
                ${messages.map(msg => `
                    <div class="message ${msg.type}">
                        ${msg.image ? `
                            <div class="message-image">
                                <img src="${msg.image}" alt="Shared image">
                            </div>
                        ` : `
                            <div class="message-bubble">${msg.text}</div>
                        `}
                        <div class="message-meta">
                            <span>${msg.time}</span>
                            ${msg.type === 'sent' ? `
                                <span class="read-receipt ${msg.read ? '' : 'pending'}">✓✓</span>
                            ` : ''}
                        </div>
                    </div>
                `).join('')}
            `;
            messagesContainer.scrollTop = messagesContainer.scrollHeight;
        }

        // Select contact
        function selectContact(id) {
            activeContactId = id;
            const contact = contacts.find(c => c.id === id);

            // Update header
            headerAvatar.src = contact.avatar;
            headerName.textContent = contact.name;
            headerStatus.textContent = contact.online ? 'Online' : 'Offline';
            headerStatus.style.color = contact.online ? 'var(--accent-green)' : 'var(--text-secondary)';

            // Clear unread
            contact.unread = 0;

            // Render
            renderContacts();
            renderMessages(id);

            // Hide sidebar on mobile
            sidebar.classList.remove('show');
            overlay.classList.remove('show');

            // Show typing indicator randomly
            if (contact.online && Math.random() > 0.5) {
                showTypingIndicator(contact.name);
            }
        }

        // Show typing indicator
        function showTypingIndicator(name) {
            typingText.textContent = `${name} is typing...`;
            typingIndicator.style.display = 'flex';

            setTimeout(() => {
                typingIndicator.style.display = 'none';
            }, 3000);
        }

        // Send message
        function sendMessage() {
            const text = messageInput.value.trim();
            if (!text) return;

            const newMessage = {
                id: Date.now(),
                type: 'sent',
                text: text,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                read: false
            };

            conversations[activeContactId].push(newMessage);

            // Update contact preview
            const contact = contacts.find(c => c.id === activeContactId);
            contact.lastMessage = text;
            contact.lastTime = newMessage.time;

            renderMessages(activeContactId);
            renderContacts();

            messageInput.value = '';
            messageInput.style.height = 'auto';

            // Simulate reply
            if (contact.online) {
                setTimeout(() => {
                    showTypingIndicator(contact.name);

                    setTimeout(() => {
                        typingIndicator.style.display = 'none';

                        const replies = [
                            "That's interesting! Tell me more 😊",
                            "I totally agree with you!",
                            "Haha, that's funny! 😂",
                            "Let me think about that...",
                            "Sounds good to me! 👍",
                            "I'll get back to you on that"
                        ];

                        const replyMessage = {
                            id: Date.now(),
                            type: 'received',
                            text: replies[Math.floor(Math.random() * replies.length)],
                            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                            read: false
                        };

                        conversations[activeContactId].push(replyMessage);
                        contact.lastMessage = replyMessage.text;
                        contact.lastTime = replyMessage.time;

                        renderMessages(activeContactId);
                        renderContacts();
                    }, 2000);
                }, 1000);
            }
        }

        // Render emoji picker
        function renderEmojiPicker() {
            const grid = emojiPicker.querySelector('.emoji-grid');
            grid.innerHTML = emojis.map(emoji => `
                <button class="emoji-btn">${emoji}</button>
            `).join('');

            grid.querySelectorAll('.emoji-btn').forEach(btn => {
                btn.addEventListener('click', () => {
                    messageInput.value += btn.textContent;
                    messageInput.focus();
                    emojiPicker.classList.remove('show');
                });
            });
        }

        // Auto-expand textarea
        messageInput.addEventListener('input', () => {
            messageInput.style.height = 'auto';
            messageInput.style.height = Math.min(messageInput.scrollHeight, 120) + 'px';
        });

        // Send on Enter (Shift+Enter for new line)
        messageInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });

        // Event listeners
        sendBtn.addEventListener('click', sendMessage);

        emojiBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            emojiPicker.classList.toggle('show');
        });

        document.addEventListener('click', (e) => {
            if (!emojiPicker.contains(e.target) && e.target !== emojiBtn) {
                emojiPicker.classList.remove('show');
            }
        });

        attachBtn.addEventListener('click', () => {
            // Simulate image attachment
            const images = [
                "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=400&h=300&fit=crop",
                "https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=400&h=300&fit=crop",
                "https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?w=400&h=300&fit=crop"
            ];

            const newMessage = {
                id: Date.now(),
                type: 'sent',
                image: images[Math.floor(Math.random() * images.length)],
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                read: false
            };

            conversations[activeContactId].push(newMessage);

            const contact = contacts.find(c => c.id === activeContactId);
            contact.lastMessage = "📷 Photo";
            contact.lastTime = newMessage.time;

            renderMessages(activeContactId);
            renderContacts();
        });

        menuBtn.addEventListener('click', () => {
            sidebar.classList.add('show');
            overlay.classList.add('show');
        });

        overlay.addEventListener('click', () => {
            sidebar.classList.remove('show');
            overlay.classList.remove('show');
        });

        // Touch swipe for mobile
        let touchStartX = 0;
        document.addEventListener('touchstart', (e) => {
            touchStartX = e.touches[0].clientX;
        });

        document.addEventListener('touchend', (e) => {
            const touchEndX = e.changedTouches[0].clientX;
            const diff = touchEndX - touchStartX;

            if (diff > 100 && touchStartX < 50) {
                sidebar.classList.add('show');
                overlay.classList.add('show');
            } else if (diff < -100 && sidebar.classList.contains('show')) {
                sidebar.classList.remove('show');
                overlay.classList.remove('show');
            }
        });

        // Initialize
        renderContacts();
        renderEmojiPicker();
        selectContact(1);
    </script>
</body>
</html>
