let activeContactId = null;
let emojiPickerVisible = false;

function getLastMessage(contact) {
  const msgs = contact.messages;
  const last = msgs[msgs.length - 1];
  if (last.type === 'image') return '📷 Photo';
  return last.text;
}

function getLastTime(contact) {
  const msgs = contact.messages;
  return msgs[msgs.length - 1].time;
}

function renderContacts(filter = '') {
  const list = document.getElementById('contactList');
  list.innerHTML = '';

  const filtered = contacts.filter(c => 
    c.name.toLowerCase().includes(filter.toLowerCase())
  );

  filtered.forEach(contact => {
    const item = document.createElement('div');
    item.className = `contact-item${contact.id === activeContactId ? ' active' : ''}`;
    item.onclick = () => selectContact(contact.id);

    const lastMsg = getLastMessage(contact);
    const lastTime = getLastTime(contact);

    item.innerHTML = `
      <div class="contact-avatar">
        <img src="${contact.avatar}" alt="${contact.name}">
        <div class="online-indicator ${contact.online ? '' : 'offline'}"></div>
      </div>
      <div class="contact-info">
        <div class="contact-name-row">
          <span class="contact-name">${contact.name}</span>
          <span class="contact-time">${lastTime}</span>
        </div>
        <div class="contact-preview-row">
          <span class="contact-preview">${contact.typing ? '<em>typing...</em>' : lastMsg}</span>
          ${contact.unread > 0 ? `<span class="unread-badge">${contact.unread}</span>` : ''}
        </div>
      </div>
    `;
    list.appendChild(item);
  });
}

function selectContact(id) {
  activeContactId = id;
  const contact = contacts.find(c => c.id === id);
  contact.unread = 0;

  renderContacts(document.getElementById('searchInput').value);
  renderChat(contact);

  // Close sidebar on mobile
  document.getElementById('sidebar').classList.remove('open');
  document.getElementById('sidebarOverlay').classList.remove('visible');
  document.getElementById('sidebarOverlay').style.display = 'none';
}

function renderChat(contact) {
  const chatArea = document.getElementById('chatArea');

  chatArea.innerHTML = `
    <div class="chat-header">
      <button class="mobile-back" onclick="openSidebar()">←</button>
      <div class="chat-header-avatar">
        <img src="${contact.avatar}" alt="${contact.name}">
        <div class="online-indicator ${contact.online ? '' : 'offline'}"></div>
      </div>
      <div class="chat-header-info">
        <div class="chat-header-name">${contact.name}</div>
        <div class="chat-header-status ${contact.online ? '' : 'offline'}">${contact.lastSeen}</div>
      </div>
      <div class="chat-header-actions">
        <button>📞</button>
        <button>📹</button>
        <button>⋯</button>
      </div>
    </div>
    <div class="messages-container" id="messagesContainer">
      <div class="date-divider"><span>Today</span></div>
    </div>
    <div class="typing-indicator ${contact.typing ? 'visible' : ''}" id="typingIndicator">
      <div class="typing-dots">
        <span></span><span></span><span></span>
      </div>
      <span class="typing-indicator-text">${contact.name.split(' ')[0]} is typing...</span>
    </div>
    <div class="input-area">
      <div class="input-actions">
        <button onclick="handleAttachment()" title="Attach file">📎</button>
        <button onclick="toggleEmojiPicker()" title="Emoji" id="emojiBtn">😊</button>
      </div>
      <div class="input-wrapper">
        <textarea id="messageInput" placeholder="Type a message..." rows="1" onkeydown="handleKeyDown(event)"></textarea>
      </div>
      <button class="send-btn" onclick="sendMessage()" title="Send">➤</button>
    </div>
    <div class="emoji-picker" id="emojiPicker">
      <div class="emoji-picker-header">Smileys & People</div>
      <div class="emoji-grid" id="emojiGrid"></div>
    </div>
  `;

  const container = document.getElementById('messagesContainer');

  contact.messages.forEach((msg, i) => {
    const wrapper = document.createElement('div');
    wrapper.className = `message-wrapper ${msg.sent ? 'sent' : 'received'}`;
    wrapper.style.animation = 'none';

    let content = '';
    if (msg.type === 'image') {
      content = `<div class="message-image"><img src="${msg.image}" alt="Shared image" loading="lazy"></div>`;
    } else {
      content = `<div class="message-bubble">${msg.text}</div>`;
    }

    const readIcon = msg.sent ? 
      `<span class="read-receipt ${msg.read ? '' : 'sent'}">${msg.read ? '✓✓' : '✓'}</span>` : '';

    wrapper.innerHTML = `
      ${content}
      <div class="message-meta">
        <span class="message-time">${msg.time}</span>
        ${readIcon}
      </div>
    `;

    container.appendChild(wrapper);
  });

  // Scroll to bottom
  container.scrollTop = container.scrollHeight;

  // Setup auto-expanding textarea
  const textarea = document.getElementById('messageInput');
  textarea.addEventListener('input', autoExpand);

  // Populate emoji picker
  populateEmojiPicker();

  // Simulate typing indicator for Josh
  if (contact.typing) {
    setTimeout(() => {
      simulateIncomingMessage(contact);
    }, 3000);
  }
}

function autoExpand() {
  const textarea = document.getElementById('messageInput');
  textarea.style.height = 'auto';
  textarea.style.height = Math.min(textarea.scrollHeight, 120) + 'px';
}

function handleKeyDown(e) {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    sendMessage();
  }
}

function sendMessage() {
  const textarea = document.getElementById('messageInput');
  const text = textarea.value.trim();
  if (!text) return;

  const contact = contacts.find(c => c.id === activeContactId);
  const now = new Date();
  const timeStr = now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });

  const newMsg = {
    id: contact.messages.length + 1,
    text: text,
    sent: true,
    time: timeStr,
    read: false,
    type: 'text'
  };

  contact.messages.push(newMsg);

  const container = document.getElementById('messagesContainer');
  const wrapper = document.createElement('div');
  wrapper.className = 'message-wrapper sent';
  wrapper.innerHTML = `
    <div class="message-bubble">${text}</div>
    <div class="message-meta">
      <span class="message-time">${timeStr}</span>
      <span class="read-receipt sent">✓</span>
    </div>
  `;
  container.appendChild(wrapper);
  container.scrollTop = container.scrollHeight;

  textarea.value = '';
  textarea.style.height = 'auto';

  renderContacts(document.getElementById('searchInput').value);

  // Simulate read receipt
  setTimeout(() => {
    const receipt = wrapper.querySelector('.read-receipt');
    if (receipt) {
      receipt.classList.remove('sent');
      receipt.textContent = '✓✓';
      newMsg.read = true;
    }
  }, 2000);

  // Simulate reply
  setTimeout(() => {
    showTypingIndicator(contact);
    setTimeout(() => {
      hideTypingIndicator();
      simulateReply(contact);
    }, 2000 + Math.random() * 2000);
  }, 1500);
}

function showTypingIndicator(contact) {
  const indicator = document.getElementById('typingIndicator');
  if (indicator) {
    indicator.classList.add('visible');
    const container = document.getElementById('messagesContainer');
    container.scrollTop = container.scrollHeight;
  }
}

function hideTypingIndicator() {
  const indicator = document.getElementById('typingIndicator');
  if (indicator) {
    indicator.classList.remove('visible');
  }
}

const replies = [
  "That sounds great! 👍",
  "Interesting, tell me more!",
  "Haha, totally agree 😄",
  "Let me think about that...",
  "Sure thing! I'll get back to you on that",
  "Nice! Can't wait 🎉",
  "Got it, thanks for letting me know",
  "Absolutely! Let's do it",
  "That's a great idea 💡",
  "I was just thinking the same thing!"
];

function simulateReply(contact) {
  const now = new Date();
  const timeStr = now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
  const replyText = replies[Math.floor(Math.random() * replies.length)];

  const newMsg = {
    id: contact.messages.length + 1,
    text: replyText,
    sent: false,
    time: timeStr,
    read: true,
    type: 'text'
  };

  contact.messages.push(newMsg);

  if (activeContactId === contact.id) {
    const container = document.getElementById('messagesContainer');
    const wrapper = document.createElement('div');
    wrapper.className = 'message-wrapper received';
    wrapper.innerHTML = `
      <div class="message-bubble">${replyText}</div>
      <div class="message-meta">
        <span class="message-time">${timeStr}</span>
      </div>
    `;
    container.appendChild(wrapper);
    container.scrollTop = container.scrollHeight;
  }

  renderContacts(document.getElementById('searchInput').value);
}

function simulateIncomingMessage(contact) {
  const now = new Date();
  const timeStr = now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });

  const newMsg = {
    id: contact.messages.length + 1,
    text: "Yeah let me check... How about next Thursday? There's a home game! 🏟️",
    sent: false,
    time: timeStr,
    read: true,
    type: 'text'
  };

  contact.messages.push(newMsg);
  contact.typing = false;

  hideTypingIndicator();

  if (activeContactId === contact.id) {
    const container = document.getElementById('messagesContainer');
    const wrapper = document.createElement('div');
    wrapper.className = 'message-wrapper received';
    wrapper.innerHTML = `
      <div class="message-bubble">${newMsg.text}</div>
      <div class="message-meta">
        <span class="message-time">${timeStr}</span>
      </div>
    `;
    container.appendChild(wrapper);
    container.scrollTop = container.scrollHeight;
  }

  renderContacts(document.getElementById('searchInput').value);
}

function toggleEmojiPicker() {
  const picker = document.getElementById('emojiPicker');
  emojiPickerVisible = !emojiPickerVisible;
  picker.classList.toggle('visible', emojiPickerVisible);
}

function populateEmojiPicker() {
  const emojis = ['😀','😂','🥰','😍','🤩','😎','🥳','😇','🤔','😅','😊','🙃','😋','🤗','🤭','😏','😌','🥺','😢','😤','🔥','❤️','💕','✨','🎉','👍','👏','🙌','💪','🤝','👋','✌️','🎯','💡','⭐','🌟','🚀','💻','🎨','🎵','📸','🍕','☕','🌈','🦋','🌸','🍀','🎁'];

  const grid = document.getElementById('emojiGrid');
  if (!grid) return;

  grid.innerHTML = '';
  emojis.forEach(emoji => {
    const btn = document.createElement('button');
    btn.textContent = emoji;
    btn.onclick = () => {
      const textarea = document.getElementById('messageInput');
      textarea.value += emoji;
      textarea.focus();
      toggleEmojiPicker();
    };
    grid.appendChild(btn);
  });
}

function handleAttachment() {
  // Simulate sending an image
  const contact = contacts.find(c => c.id === activeContactId);
  if (!contact) return;

  const now = new Date();
  const timeStr = now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });

  const images = [
    "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=400&h=300&fit=crop",
    "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=400&h=300&fit=crop",
    "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=400&h=300&fit=crop"
  ];

  const newMsg = {
    id: contact.messages.length + 1,
    image: images[Math.floor(Math.random() * images.length)],
    sent: true,
    time: timeStr,
    read: false,
    type: 'image'
  };

  contact.messages.push(newMsg);

  const container = document.getElementById('messagesContainer');
  const wrapper = document.createElement('div');
  wrapper.className = 'message-wrapper sent';
  wrapper.innerHTML = `
    <div class="message-image"><img src="${newMsg.image}" alt="Shared image"></div>
    <div class="message-meta">
      <span class="message-time">${timeStr}</span>
      <span class="read-receipt sent">✓</span>
    </div>
  `;
  container.appendChild(wrapper);
  container.scrollTop = container.scrollHeight;

  renderContacts(document.getElementById('searchInput').value);

  setTimeout(() => {
    const receipt = wrapper.querySelector('.read-receipt');
    if (receipt) {
      receipt.classList.remove('sent');
      receipt.textContent = '✓✓';
    }
  }, 2000);
}

function openSidebar() {
  document.getElementById('sidebar').classList.add('open');
  const overlay = document.getElementById('sidebarOverlay');
  overlay.style.display = 'block';
  requestAnimationFrame(() => overlay.classList.add('visible'));
}

document.getElementById('sidebarOverlay').addEventListener('click', () => {
  document.getElementById('sidebar').classList.remove('open');
  const overlay = document.getElementById('sidebarOverlay');
  overlay.classList.remove('visible');
  setTimeout(() => overlay.style.display = 'none', 300);
});

document.getElementById('searchInput').addEventListener('input', (e) => {
  renderContacts(e.target.value);
});

// Close emoji picker when clicking outside
document.addEventListener('click', (e) => {
  if (emojiPickerVisible && !e.target.closest('.emoji-picker') && !e.target.closest('#emojiBtn')) {
    emojiPickerVisible = false;
    const picker = document.getElementById('emojiPicker');
    if (picker) picker.classList.remove('visible');
  }
});

// Touch swipe to open sidebar on mobile
let touchStartX = 0;
let touchEndX = 0;

document.addEventListener('touchstart', (e) => {
  touchStartX = e.changedTouches[0].screenX;
});

document.addEventListener('touchend', (e) => {
  touchEndX = e.changedTouches[0].screenX;
  if (touchEndX - touchStartX > 80 && touchStartX < 40) {
    openSidebar();
  }
});

// Initialize
renderContacts();
selectContact(1);
</script>
</body>
</html>
```

