    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const messageInput = document.getElementById('message-input');
            const messageArea = document.getElementById('message-area');
            const sendBtn = document.getElementById('send-btn');
            const emojiBtn = document.getElementById('emoji-btn');
            const emojiPicker = document.getElementById('emoji-picker');
            const sidebar = document.querySelector('.sidebar');
            const backToContactsBtn = document.getElementById('back-to-contacts');
            const contacts = document.querySelectorAll('.contact');

            // --- Auto-expanding Textarea ---
            messageInput.addEventListener('input', function() {
                this.style.height = 'auto';
                this.style.height = (this.scrollHeight) + 'px';
            });

            // --- Scroll to bottom on load ---
            const scrollToBottom = () => {
                messageArea.scrollTop = messageArea.scrollHeight;
            };
            scrollToBottom();

            // --- Emoji Picker ---
            const emojis = ['😀', '😂', '😍', '🤔', '👍', '❤️', '🔥', '🎉', '🚀', '💯', '👋', '🙏', '😎', '😢', '🤯', '😱'];
            emojis.forEach(emoji => {
                const span = document.createElement('span');
                span.textContent = emoji;
                span.addEventListener('click', () => {
                    messageInput.value += emoji;
                    messageInput.focus();
                    messageInput.dispatchEvent(new Event('input')); // Trigger resize
                });
                emojiPicker.appendChild(span);
            });

            emojiBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                emojiPicker.classList.toggle('show');
            });

            document.addEventListener('click', (e) => {
                if (!emojiPicker.contains(e.target) && e.target !== emojiBtn) {
                    emojiPicker.classList.remove('show');
                }
            });

            // --- Send Message ---
            const sendMessage = () => {
                const text = messageInput.value.trim();
                if (text === '') return;

                // 1. Create and append sent message
                const sentMessageHTML = `
                    <div class="message sent">
                        <div class="message-content">
                            <p>${text}</p>
                            <div class="message-meta">
                                <span>${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                <span class="read-receipt">
                                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>
                                </span>
                            </div>
                        </div>
                    </div>
                `;
                messageArea.insertAdjacentHTML('beforeend', sentMessageHTML);

                // 2. Clear input and reset height
                messageInput.value = '';
                messageInput.style.height = 'auto';
                messageInput.focus();

                // 3. Scroll to bottom
                scrollToBottom();

                // 4. Simulate response
                simulateResponse(sentMessageHTML);
            };

            sendBtn.addEventListener('click', sendMessage);
            messageInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                }
            });

            // --- Simulate Response & Typing Indicator ---
            const simulateResponse = (sentMessageHTML) => {
                const sentMessageEl = messageArea.lastElementChild;
                const receiptEl = sentMessageEl.querySelector('.read-receipt');

                // Show typing indicator
                const typingIndicatorHTML = `
                    <div class="message received typing-indicator">
                        <span></span><span></span><span></span>
                    </div>
                `;
                messageArea.insertAdjacentHTML('beforeend', typingIndicatorHTML);
                scrollToBottom();

                // Mark as "delivered" (double check)
                setTimeout(() => {
                    if(receiptEl) {
                        receiptEl.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline><line x1="15" y1="6" x2="9" y2="12"></line></svg>`;
                    }
                }, 800);

                // After a delay, remove typing and show response
                setTimeout(() => {
                    const typingIndicator = document.querySelector('.typing-indicator');
                    if (typingIndicator) {
                        typingIndicator.remove();
                    }

                    // Mark as "read" (blue double check)
                    if(receiptEl) {
                        receiptEl.classList.add('read');
                    }

                    // Bot response
                    const responseText = "That's interesting! Tell me more.";
                    const receivedMessageHTML = `
                        <div class="message received">
                            <div class="message-content">
                                <p>${responseText}</p>
                                <div class="message-meta">
                                    <span>${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                </div>
                            </div>
                        </div>
                    `;
                    messageArea.insertAdjacentHTML('beforeend', receivedMessageHTML);
                    scrollToBottom();

                }, 2000 + Math.random() * 1500); // Random delay for realism
            };

            // --- Responsive Sidebar Toggle ---
            backToContactsBtn.addEventListener('click', () => {
                sidebar.classList.add('open');
            });

            contacts.forEach(contact => {
                contact.addEventListener('click', () => {
                    // On mobile, clicking a contact should close the sidebar
                    if (window.innerWidth <= 768) {
                        sidebar.classList.remove('open');
                    }
                    // Here you would typically load the new chat data
                });
            });

            // Close sidebar if clicking outside on mobile
            document.addEventListener('click', (e) => {
                if (sidebar.classList.contains('open') && !sidebar.contains(e.target) && e.target !== backToContactsBtn) {
                    sidebar.classList.remove('open');
                }
            });
        });
    </script>

</body>
