        function generateData(count) {
            const firstNames = ['James', 'Mary', 'Robert', 'Patricia', 'John', 'Jennifer', 'Michael', 'Linda', 'David', 'Elizabeth', 'William', 'Barbara', 'Richard', 'Susan', 'Joseph', 'Jessica', 'Thomas', 'Sarah', 'Charles', 'Karen'];
            const lastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez', 'Hernandez', 'Lopez', 'Gonzalez', 'Wilson', 'Anderson', 'Thomas', 'Taylor', 'Moore', 'Jackson', 'Martin'];

            return Array.from({ length: count }, (_, i) => {
                const fn = firstNames[Math.floor(Math.random() * firstNames.length)];
                const ln = lastNames[Math.floor(Math.random() * lastNames.length)];
                const status = Math.random() > 0.1 ? 'Active' : 'Inactive'; // 90% active
                return {
                    id: i + 1,
                    name: `${fn} ${ln}`,
                    email: `${fn.toLowerCase()}.${ln.toLowerCase()}@company.com`,
                    role: roles[Math.floor(Math.random() * roles.length)],
                    department: departments[Math.floor(Math.random() * departments.length)],
                    status: status,
                    joined: new Date(Date.now() - Math.floor(Math.random() * 10000000000)).toISOString().split('T')[0],
                    avatarColor: ['bg-red-100 text-red-700', 'bg-blue-100 text-blue-700', 'bg-green-100 text-green-700', 'bg-yellow-100 text-yellow-700', 'bg-purple-100 text-purple-700'][Math.floor(Math.random() * 5)]
                };
            });
        }

        // --- State Management ---
        let allData = generateData(20);
        let currentPage = 1;
        let pageSize = 10;
        let sortConfig = { key: 'name', direction: 'asc' };
        let searchQuery = '';
        let selectedIds = new Set();
        let isLoading = false;

        // --- DOM Elements ---
        const tableBody = document.getElementById('tableBody');
        const searchInput = document.getElementById('searchInput');
        const selectAllCheckbox = document.getElementById('selectAll');
        const bulkActionsBar = document.getElementById('bulkActions');
        const selectedCountSpan = document.getElementById('selectedCount');
        const pageIndicator = document.getElementById('pageIndicator');
        const prevBtn = document.getElementById('prevBtn');
        const nextBtn = document.getElementById('nextBtn');

        // --- Core Functions ---

        function init() {
            lucide.createIcons();
            renderTable();

            // Search Listener
            searchInput.addEventListener('input', (e) => {
                searchQuery = e.target.value.toLowerCase();
                currentPage = 1;
                renderTable();
            });

            // Select All Listener
            selectAllCheckbox.addEventListener('change', (e) => {
                const visibleIds = getFilteredData().map(u => u.id);
                if (e.target.checked) {
                    visibleIds.forEach(id => selectedIds.add(id));
                } else {
                    visibleIds.forEach(id => selectedIds.delete(id));
                }
                updateBulkActionsUI();
                renderTable(); // Re-render to update checkboxes
            });
        }

        function getFilteredData() {
            let data = [...allData];

            // Filter
            if (searchQuery) {
                data = data.filter(item => 
                    item.name.toLowerCase().includes(searchQuery) || 
                    item.email.toLowerCase().includes(searchQuery) ||
                    item.role.toLowerCase().includes(searchQuery)
                );
            }

            // Sort
            data.sort((a, b) => {
                if (a[sortConfig.key] < b[sortConfig.key]) return sortConfig.direction === 'asc' ? -1 : 1;
                if (a[sortConfig.key] > b[sortConfig.key]) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });

            return data;
        }

        function renderTable() {
            // Simulate loading for realism on sort/filter
            if(isLoading) {
                renderSkeleton();
                return;
            }

            const filteredData = getFilteredData();
            const totalPages = Math.ceil(filteredData.length / pageSize) || 1;

            // Pagination Logic
            if (currentPage > totalPages) currentPage = totalPages;
            const start = (currentPage - 1) * pageSize;
            const end = start + pageSize;
            const paginatedData = filteredData.slice(start, end);

            // Update Pagination UI
            pageIndicator.textContent = `Page ${currentPage} of ${totalPages}`;
            prevBtn.disabled = currentPage === 1;
            nextBtn.disabled = currentPage === totalPages;

            // Empty State
            if (paginatedData.length === 0) {
                tableBody.innerHTML = `
                    <tr>
                        <td colspan="8" class="py-12 text-center">
                            <div class="flex flex-col items-center justify-center text-slate-400">
                                <i data-lucide="inbox" class="w-12 h-12 mb-3 text-slate-300"></i>
                                <p class="text-lg font-medium text-slate-600">No members found</p>
                                <p class="text-sm">Try adjusting your search or filters.</p>
                            </div>
                        </td>
                    </tr>
                `;
                lucide.createIcons();
                return;
            }

            // Render Rows
            tableBody.innerHTML = paginatedData.map(user => {
                const isSelected = selectedIds.has(user.id);
                const initials = user.name.split(' ').map(n => n[0]).join('');

                // Badge Styles
                const roleStyles = {
                    'Admin': 'bg-purple-100 text-purple-700 border-purple-200',
                    'Editor': 'bg-blue-100 text-blue-700 border-blue-200',
                    'Developer': 'bg-indigo-100 text-indigo-700 border-indigo-200',
                    'Designer': 'bg-pink-100 text-pink-700 border-pink-200',
                    'Viewer': 'bg-slate-100 text-slate-700 border-slate-200'
                }[user.role] || 'bg-slate-100 text-slate-700';

                const statusStyles = user.status === 'Active' 
                    ? 'bg-emerald-50 text-emerald-700 border-emerald-100' 
                    : 'bg-slate-100 text-slate-600 border-slate-200';

                return `
                    <tr class="group hover:bg-slate-50 transition-colors border-b border-slate-100 last:border-0">
                        <td class="p-4 sticky-col bg-white group-hover:bg-slate-50">
                            <input type="checkbox" 
                                class="row-checkbox rounded border-slate-300 text-indigo-600 focus:ring-indigo-500/20 cursor-pointer" 
                                data-id="${user.id}" 
                                ${isSelected ? 'checked' : ''}
                                onchange="toggleRowSelection(${user.id})">
                        </td>
                        <td class="p-4 sticky-col bg-white group-hover:bg-slate-50">
                            <div class="flex items-center gap-3">
                                <div class="w-8 h-8 rounded-full flex items-center justify-center text-xs font-semibold ${user.avatarColor}">
                                    ${initials}
                                </div>
                                <div>
                                    <div class="font-medium text-slate-900">${user.name}</div>
                                </div>
                            </div>
                        </td>
                        <td class="p-4 text-slate-600">${user.email}</td>
                        <td class="p-4">
                            <span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${roleStyles}">
                                ${user.role}
                            </span>
                        </td>
                        <td class="p-4 text-slate-600">${user.department}</td>
                        <td class="p-4">
                            <div class="flex items-center gap-1.5">
                                <span class="w-1.5 h-1.5 rounded-full ${user.status === 'Active' ? 'bg-emerald-500' : 'bg-slate-400'}"></span>
                                <span class="text-slate-600">${user.status}</span>
                            </div>
                        </td>
                        <td class="p-4 text-slate-500 font-mono text-xs">${user.joined}</td>
                        <td class="p-4 text-right relative">
                            <button onclick="toggleDropdown(this)" class="p-1.5 hover:bg-slate-200 rounded-md text-slate-400 hover:text-slate-600 transition-colors">
                                <i data-lucide="more-horizontal" class="w-4 h-4"></i>
                            </button>
                        </td>
                    </tr>
                `;
            }).join('');

            lucide.createIcons();
        }

        function renderSkeleton() {
            let skeleton = '';
            for(let i=0; i<pageSize; i++) {
                skeleton += `
                    <tr class="animate-pulse border-b border-slate-100">
                        <td class="p-4"><div class="h-4 w-4 bg-slate-200 rounded"></div></td>
                        <td class="p-4"><div class="flex items-center gap-3"><div class="h-8 w-8 bg-slate-200 rounded-full"></div><div class="h-4 w-32 bg-slate-200 rounded"></div></div></td>
                        <td class="p-4"><div class="h-4 w-40 bg-slate-200 rounded"></div></td>
                        <td class="p-4"><div class="h-5 w-16 bg-slate-200 rounded-full"></div></td>
                        <td class="p-4"><div class="h-4 w-24 bg-slate-200 rounded"></div></td>
                        <td class="p-4"><div class="h-4 w-16 bg-slate-200 rounded"></div></td>
                        <td class="p-4"><div class="h-4 w-20 bg-slate-200 rounded"></div></td>
                        <td class="p-4 text-right"><div class="h-4 w-4 bg-slate-200 rounded ml-auto"></div></td>
                    </tr>
                `;
            }
            tableBody.innerHTML = skeleton;
        }

        // --- Interaction Handlers ---

        function handleSort(key) {
            isLoading = true;
            if (sortConfig.key === key) {
                sortConfig.direction = sortConfig.direction === 'asc' ? 'desc' : 'asc';
            } else {
                sortConfig.key = key;
                sortConfig.direction = 'asc';
            }

            // Simulate network delay for sort
            setTimeout(() => {
                isLoading = false;
                renderTable();
            }, 300);
        }

        function toggleRowSelection(id) {
            if (selectedIds.has(id)) {
                selectedIds.delete(id);
            } else {
                selectedIds.add(id);
            }
            updateBulkActionsUI();

            // Update "Select All" checkbox state
            const visibleIds = getFilteredData().map(u => u.id);
            const allVisibleSelected = visibleIds.every(id => selectedIds.has(id));
            selectAllCheckbox.checked = allVisibleSelected && visibleIds.length > 0;
            selectAllCheckbox.indeterminate = !allVisibleSelected && selectedIds.size > 0;
        }

        function clearSelection() {
            selectedIds.clear();
            selectAllCheckbox.checked = false;
            selectAllCheckbox.indeterminate = false;
            updateBulkActionsUI();
            renderTable();
        }

        function updateBulkActionsUI() {
            if (selectedIds.size > 0) {
                bulkActionsBar.classList.remove('hidden');
                selectedCountSpan.textContent = `${selectedIds.size} selected`;
            } else {
                bulkActionsBar.classList.add('hidden');
            }
        }

        function changePage(delta) {
            currentPage += delta;
            renderTable();
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

        function changePageSize() {
            pageSize = parseInt(document.getElementById('pageSize').value);
            currentPage = 1;
            renderTable();
        }

        // --- Dropdown Logic ---
        let activeDropdown = null;

        function toggleDropdown(btn) {
            // Close existing
            if (activeDropdown) {
                activeDropdown.remove();
                activeDropdown = null;
                if(btn === activeDropdownTrigger) return; // If clicked same button, just close
            }

            // Create new
            const template = document.getElementById('dropdownTemplate').cloneNode(true);
            template.id = ''; // Remove ID to avoid duplicates
            template.classList.remove('hidden');

            // Position logic
            const rect = btn.getBoundingClientRect();
            template.style.top = `${rect.bottom - window.scrollY + 4}px`;
            template.style.right = `${window.innerWidth - rect.right + 4}px`; // Align right edge

            document.body.appendChild(template);
            activeDropdown = template;
            activeDropdownTrigger = btn;
            lucide.createIcons();

            // Close on click outside
            setTimeout(() => {
                document.addEventListener('click', closeDropdownOutside);
            }, 0);
        }

        function closeDropdownOutside(e) {
            if (activeDropdown && !activeDropdown.contains(e.target) && e.target !== activeDropdownTrigger) {
                activeDropdown.remove();
                activeDropdown = null;
                document.removeEventListener('click', closeDropdownOutside);
            }
        }

        // Initialize
        init();

    </script>
</body>
</html>
