            </div>
        </div>
    </div>

    <!-- Row Action Dropdown (Hidden by default, positioned absolutely) -->
    <div id="actionDropdown" class="hidden absolute z-50 w-48 bg-white rounded-lg shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none">
        <div class="py-1">
            <a href="#" class="group flex items-center px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-gray-900">
                <svg class="mr-3 h-5 w-5 text-gray-400 group-hover:text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"></path></svg>
                Edit
            </a>
            <a href="#" class="group flex items-center px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-gray-900">
                <svg class="mr-3 h-5 w-5 text-gray-400 group-hover:text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636m12.728 12.728L5.636 5.636"></path></svg>
                Deactivate
            </a>
            <a href="#" class="group flex items-center px-4 py-2 text-sm text-red-600 hover:bg-red-50 hover:text-red-900">
                <svg class="mr-3 h-5 w-5 text-red-400 group-hover:text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                Remove
            </a>
        </div>
    </div>

    <script>
        // --- Data Generation ---
        const roles = ['Admin', 'Editor', 'Viewer', 'Developer', 'Designer'];
        const departments = ['Engineering', 'Product', 'Design', 'Marketing', 'Sales'];
        const statuses = ['Active', 'Inactive'];

        const generateData = (count) => {
            return Array.from({ length: count }, (_, i) => {
                const firstName = ['Alex', 'Jordan', 'Taylor', 'Morgan', 'Casey', 'Riley', 'Jamie', 'Avery', 'Quinn', 'Skyler'][Math.floor(Math.random() * 10)];
                const lastName = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez'][Math.floor(Math.random() * 10)];
                const name = `${firstName} ${lastName}`;
                const status = Math.random() > 0.2 ? 'Active' : 'Inactive';

                return {
                    id: i + 1,
                    name: name,
                    email: `${firstName.toLowerCase()}.${lastName.toLowerCase()}@company.com`,
                    role: roles[Math.floor(Math.random() * roles.length)],
                    department: departments[Math.floor(Math.random() * departments.length)],
                    status: status,
                    joined: new Date(2023, Math.floor(Math.random() * 12), Math.floor(Math.random() * 28) + 1).toISOString().split('T')[0],
                    avatarColor: ['bg-red-100 text-red-700', 'bg-green-100 text-green-700', 'bg-blue-100 text-blue-700', 'bg-yellow-100 text-yellow-700', 'bg-purple-100 text-purple-700', 'bg-pink-100 text-pink-700'][Math.floor(Math.random() * 6)]
                };
            });
        };

        let allData = generateData(20);
        let currentPage = 1;
        let pageSize = 10;
        let sortCol = 'name';
        let sortAsc = true;
        let selectedIds = new Set();
        let searchQuery = '';

        // --- DOM Elements ---
        const tableBody = document.getElementById('tableBody');
        const emptyState = document.getElementById('emptyState');
        const loadingState = document.getElementById('loadingState');
        const bulkActions = document.getElementById('bulkActions');
        const selectedCountSpan = document.getElementById('selectedCount');
        const selectAllCheckbox = document.getElementById('selectAll');
        const actionDropdown = document.getElementById('actionDropdown');

        // Pagination Elements
        const showingStartEl = document.getElementById('showingStart');
        const showingEndEl = document.getElementById('showingEnd');
        const totalItemsEl = document.getElementById('totalItems');
        const prevBtn = document.getElementById('prevBtn');
        const nextBtn = document.getElementById('nextBtn');
        const mobilePrevBtn = document.getElementById('mobilePrevBtn');
        const mobileNextBtn = document.getElementById('mobileNextBtn');
        const pageSizeSelect = document.getElementById('pageSize');

        // --- Helper Functions ---
        const getInitials = (name) => name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();

        const getStatusBadge = (status) => {
            const activeClass = status === 'Active' 
                ? 'bg-green-50 text-green-700 ring-green-600/20' 
                : 'bg-gray-50 text-gray-600 ring-gray-500/10';
            return `<span class="inline-flex items-center rounded-md px-2 py-1 text-xs font-medium ring-1 ring-inset ${activeClass}">${status}</span>`;
        };

        const getRoleBadge = (role) => {
            // Simple color mapping for roles
            const colors = {
                'Admin': 'bg-purple-50 text-purple-700 ring-purple-700/10',
                'Developer': 'bg-blue-50 text-blue-700 ring-blue-700/10',
                'Designer': 'bg-pink-50 text-pink-700 ring-pink-700/10',
                'Editor': 'bg-orange-50 text-orange-700 ring-orange-700/10',
                'Viewer': 'bg-gray-50 text-gray-600 ring-gray-500/10'
            };
            const colorClass = colors[role] || colors['Viewer'];
            return `<span class="inline-flex items-center rounded-md px-2 py-1 text-xs font-medium ring-1 ring-inset ${colorClass}">${role}</span>`;
        };

        // --- Rendering ---
        const renderSkeleton = () => {
            let html = '';
            for(let i=0; i<5; i++) {
                html += `
                <tr class="animate-pulse">
                    <td class="px-6 py-4 whitespace-nowrap"><div class="h-4 w-4 bg-gray-200 rounded"></div></td>
                    <td class="px-6 py-4 whitespace-nowrap"><div class="flex items-center"><div class="h-8 w-8 bg-gray-200 rounded-full mr-3"></div><div class="h-4 w-32 bg-gray-200 rounded"></div></div></td>
                    <td class="px-6 py-4 whitespace-nowrap"><div class="h-4 w-48 bg-gray-200 rounded"></div></td>
                    <td class="px-6 py-4 whitespace-nowrap"><div class="h-6 w-16 bg-gray-200 rounded"></div></td>
                    <td class="px-6 py-4 whitespace-nowrap"><div class="h-4 w-24 bg-gray-200 rounded"></div></td>
                    <td class="px-6 py-4 whitespace-nowrap"><div class="h-6 w-16 bg-gray-200 rounded"></div></td>
                    <td class="px-6 py-4 whitespace-nowrap"><div class="h-4 w-20 bg-gray-200 rounded"></div></td>
                    <td class="px-6 py-4 whitespace-nowrap text-right text-sm font-medium"><div class="h-4 w-4 bg-gray-200 rounded ml-auto"></div></td>
                </tr>`;
            }
            loadingState.innerHTML = `<table class="min-w-full"><tbody>${html}</tbody></table>`;
        };

        const renderTable = () => {
            // Filter
            let filtered = allData.filter(item => 
                item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                item.email.toLowerCase().includes(searchQuery.toLowerCase())
            );

            // Sort
            filtered.sort((a, b) => {
                let valA = a[sortCol];
                let valB = b[sortCol];
                if (valA < valB) return sortAsc ? -1 : 1;
                if (valA > valB) return sortAsc ? 1 : -1;
                return 0;
            });

            // Pagination Logic
            const totalItems = filtered.length;
            const totalPages = Math.ceil(totalItems / pageSize);
            if (currentPage > totalPages) currentPage = Math.max(1, totalPages);

            const start = (currentPage - 1) * pageSize;
            const end = start + pageSize;
            const pageData = filtered.slice(start, end);

            // Update UI Counts
            showingStartEl.textContent = totalItems === 0 ? 0 : start + 1;
            showingEndEl.textContent = Math.min(end, totalItems);
            totalItemsEl.textContent = totalItems;

            prevBtn.disabled = currentPage === 1;
            nextBtn.disabled = currentPage === totalPages || totalPages === 0;
            mobilePrevBtn.disabled = currentPage === 1;
            mobileNextBtn.disabled = currentPage === totalPages || totalPages === 0;

            // Toggle Empty State
            if (totalItems === 0) {
                tableBody.innerHTML = '';
                emptyState.classList.remove('hidden');
                bulkActions.classList.add('hidden');
                return;
            } else {
                emptyState.classList.add('hidden');
            }

            // Render Rows
            tableBody.innerHTML = pageData.map(item => {
                const isSelected = selectedIds.has(item.id);
                return `
                <tr class="hover:bg-gray-50 transition-colors group ${isSelected ? 'bg-gray-50' : ''}">
                    <td class="sticky left-0 z-10 ${isSelected ? 'bg-gray-50' : 'bg-white'} group-hover:bg-gray-50 px-6 py-4 whitespace-nowrap">
                        <input type="checkbox" data-id="${item.id}" ${isSelected ? 'checked' : ''} class="row-checkbox rounded border-gray-300 text-gray-900 focus:ring-gray-900">
                    </td>
                    <td class="sticky left-12 z-10 ${isSelected ? 'bg-gray-50' : 'bg-white'} group-hover:bg-gray-50 px-6 py-4 whitespace-nowrap">
                        <div class="flex items-center">
                            <div class="flex-shrink-0 h-8 w-8 rounded-full ${item.avatarColor} flex items-center justify-center text-xs font-bold ring-2 ring-white">
                                ${getInitials(item.name)}
                            </div>
                            <div class="ml-4">
                                <div class="text-sm font-medium text-gray-900">${item.name}</div>
                            </div>
                        </div>
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap">
                        <div class="text-sm text-gray-500">${item.email}</div>
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap">
                        ${getRoleBadge(item.role)}
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        ${item.department}
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap">
                        ${getStatusBadge(item.status)}
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        ${item.joined}
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-right text-sm font-medium relative">
                        <button onclick="toggleDropdown(event, ${item.id})" class="text-gray-400 hover:text-gray-600 p-1 rounded-full hover:bg-gray-200 transition-colors">
                            <svg class="h-5 w-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 6a2 2 0 110-4 2 2 0 010 4zM10 12a2 2 0 110-4 2 2 0 010 4zM10 18a2 2 0 110-4 2 2 0 010 4z" /></svg>
                        </button>
                    </td>
                </tr>
                `;
            }).join('');

            updateBulkActionUI();
        };

        // --- Event Handlers ---

        // Search
        document.getElementById('searchInput').addEventListener('input', (e) => {
            searchQuery = e.target.value;
            currentPage = 1;
            renderTable();
        });

        // Page Size
        pageSizeSelect.addEventListener('change', (e) => {
            pageSize = parseInt(e.target.value);
            currentPage = 1;
            renderTable();
        });

        // Pagination Buttons
        const changePage = (dir) => {
            currentPage += dir;
            renderTable();
        };
        prevBtn.addEventListener('click', () => changePage(-1));
        nextBtn.addEventListener('click', () => changePage(1));
        mobilePrevBtn.addEventListener('click', () => changePage(-1));
        mobileNextBtn.addEventListener('click', () => changePage(1));

        // Sorting
        window.sortTable = (col) => {
            if (sortCol === col) {
                sortAsc = !sortAsc;
            } else {
                sortCol = col;
                sortAsc = true;
            }
            renderTable();
        };

        // Selection Logic
        selectAllCheckbox.addEventListener('change', (e) => {
            // Only select visible rows on current page for better UX, or all filtered? 
            // Let's select all filtered for bulk actions consistency
            let filtered = allData.filter(item => 
                item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                item.email.toLowerCase().includes(searchQuery.toLowerCase())
            );

            if (e.target.checked) {
                filtered.forEach(item => selectedIds.add(item.id));
            } else {
                filtered.forEach(item => selectedIds.delete(item.id));
            }
            renderTable();
        });

        tableBody.addEventListener('change', (e) => {
            if (e.target.classList.contains('row-checkbox')) {
                const id = parseInt(e.target.dataset.id);
                if (e.target.checked) {
                    selectedIds.add(id);
                } else {
                    selectedIds.delete(id);
                }
                updateBulkActionUI();

                // Update "Select All" checkbox state
                const visibleCheckboxes = document.querySelectorAll('.row-checkbox');
                const checkedCheckboxes = document.querySelectorAll('.row-checkbox:checked');
                selectAllCheckbox.checked = visibleCheckboxes.length > 0 && visibleCheckboxes.length === checkedCheckboxes.length;
                selectAllCheckbox.indeterminate = checkedCheckboxes.length > 0 && checkedCheckboxes.length < visibleCheckboxes.length;
            }
        });

        const updateBulkActionUI = () => {
            if (selectedIds.size > 0) {
                bulkActions.classList.remove('hidden');
                selectedCountSpan.textContent = selectedIds.size;
            } else {
                bulkActions.classList.add('hidden');
            }
        };

        // Dropdown Logic
        window.toggleDropdown = (e, id) => {
            e.stopPropagation();
            // Close existing
            actionDropdown.classList.add('hidden');

            // Position new
            const btn = e.currentTarget;
            const rect = btn.getBoundingClientRect();

            actionDropdown.style.top = `${rect.bottom + window.scrollY}px`;
            actionDropdown.style.left = `${rect.right - 150}px`; // Align right edge
            actionDropdown.classList.remove('hidden');

            // Store current action ID for demo purposes
            actionDropdown.dataset.targetId = id;
        };

        // Close dropdown on click outside
        document.addEventListener('click', (e) => {
            if (!actionDropdown.contains(e.target)) {
                actionDropdown.classList.add('hidden');
            }
        });

        // --- Initialization ---
        (async function init() {
            renderSkeleton();
            // Simulate API delay
            await new Promise(r => setTimeout(r, 800));
            loadingState.innerHTML = ''; // Clear skeleton
            renderTable();
        })();

    </script>
</body>
</html>
