</head>
<body class="bg-gray-50 min-h-screen">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <!-- Header -->
        <div class="mb-8">
            <h1 class="text-2xl font-semibold text-gray-900">Team Members</h1>
            <p class="mt-1 text-sm text-gray-500">Manage your team members and their account permissions here.</p>
        </div>

        <!-- Controls Bar -->
        <div class="bg-white rounded-lg shadow-sm border border-gray-200 mb-4">
            <div class="p-4 flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
                <!-- Search -->
                <div class="relative w-full sm:w-80">
                    <svg class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/>
                    </svg>
                    <input type="text" id="searchInput" placeholder="Search by name or email..." class="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all">
                </div>

                <!-- Filters -->
                <div class="flex gap-3 w-full sm:w-auto">
                    <select id="departmentFilter" class="px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary bg-white">
                        <option value="">All Departments</option>
                        <option value="Engineering">Engineering</option>
                        <option value="Design">Design</option>
                        <option value="Marketing">Marketing</option>
                        <option value="Sales">Sales</option>
                        <option value="HR">HR</option>
                        <option value="Finance">Finance</option>
                    </select>
                    <select id="statusFilter" class="px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary bg-white">
                        <option value="">All Status</option>
                        <option value="active">Active</option>
                        <option value="inactive">Inactive</option>
                    </select>
                    <button onclick="toggleLoading()" class="px-4 py-2 bg-gray-100 text-gray-600 rounded-lg text-sm hover:bg-gray-200 transition-colors">
                        Toggle Loading
                    </button>
                </div>
            </div>

            <!-- Bulk Actions Bar -->
            <div id="bulkActionsBar" class="hidden px-4 py-3 bg-primary/5 border-t border-gray-200 flex items-center justify-between">
                <div class="flex items-center gap-3">
                    <span class="text-sm text-gray-600"><span id="selectedCount">0</span> selected</span>
                    <button class="px-3 py-1.5 text-sm text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded transition-colors">Deactivate</button>
                    <button class="px-3 py-1.5 text-sm text-red-600 hover:text-red-700 hover:bg-red-50 rounded transition-colors">Remove</button>
                </div>
                <button onclick="clearSelection()" class="text-sm text-gray-500 hover:text-gray-700">Clear selection</button>
            </div>
        </div>

        <!-- Table -->
        <div class="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
            <div class="table-container overflow-x-auto">
                <table class="w-full min-w-[900px]">
                    <thead>
                        <tr class="bg-gray-50 border-b border-gray-200">
                            <th class="sticky left-0 bg-gray-50 px-4 py-3 w-12">
                                <input type="checkbox" id="selectAll" class="w-4 h-4 rounded border-gray-300 text-primary focus:ring-primary/20 cursor-pointer">
                            </th>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Member</th>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:text-gray-700 select-none" onclick="sortTable('email')">
                                <div class="flex items-center gap-1">
                                    Email
                                    <svg class="w-4 h-4 sort-icon" data-column="email" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4"/>
                                    </svg>
                                </div>
                            </th>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:text-gray-700 select-none" onclick="sortTable('role')">
                                <div class="flex items-center gap-1">
                                    Role
                                    <svg class="w-4 h-4 sort-icon" data-column="role" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4"/>
                                    </svg>
                                </div>
                            </th>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:text-gray-700 select-none" onclick="sortTable('department')">
                                <div class="flex items-center gap-1">
                                    Department
                                    <svg class="w-4 h-4 sort-icon" data-column="department" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4"/>
                                    </svg>
                                </div>
                            </th>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:text-gray-700 select-none" onclick="sortTable('joinedDate')">
                                <div class="flex items-center gap-1">
                                    Joined
                                    <svg class="w-4 h-4 sort-icon" data-column="joinedDate" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4"/>
                                    </svg>
                                </div>
                            </th>
                            <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
                        </tr>
                    </thead>
                    <tbody id="tableBody" class="divide-y divide-gray-100">
                        <!-- Dynamic content -->
                    </tbody>
                </table>
            </div>

            <!-- Empty State -->
            <div id="emptyState" class="hidden py-16 text-center">
                <svg class="mx-auto w-12 h-12 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/>
                </svg>
                <h3 class="mt-4 text-sm font-medium text-gray-900">No team members found</h3>
                <p class="mt-1 text-sm text-gray-500">Try adjusting your search or filter to find what you're looking for.</p>
                <button onclick="resetFilters()" class="mt-4 px-4 py-2 bg-primary text-white text-sm rounded-lg hover:bg-primary/90 transition-colors">
                    Clear filters
                </button>
            </div>

            <!-- Pagination -->
            <div id="pagination" class="px-4 py-3 border-t border-gray-200 flex flex-col sm:flex-row items-center justify-between gap-4">
                <div class="flex items-center gap-2">
                    <span class="text-sm text-gray-500">Rows per page:</span>
                    <select id="pageSize" class="px-2 py-1 border border-gray-200 rounded text-sm text-gray-600 focus:outline-none focus:ring-2 focus:ring-primary/20 bg-white">
                        <option value="5">5</option>
                        <option value="10" selected>10</option>
                        <option value="20">20</option>
                    </select>
                </div>
                <div class="flex items-center gap-2">
                    <span id="paginationInfo" class="text-sm text-gray-500">1-10 of 20</span>
                    <div class="flex gap-1">
                        <button id="prevPage" class="p-2 rounded hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
                            <svg class="w-4 h-4 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/>
                            </svg>
                        </button>
                        <button id="nextPage" class="p-2 rounded hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
                            <svg class="w-4 h-4 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/>
                            </svg>
                        </button>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script>
        // Sample data
        const teamMembers = [
            { id: 1, name: "Sarah Chen", email: "sarah.chen@company.com", role: "Admin", department: "Engineering", status: "active", joinedDate: "2023-01-15", avatar: null },
            { id: 2, name: "Marcus Johnson", email: "marcus.j@company.com", role: "Manager", department: "Sales", status: "active", joinedDate: "2022-08-22", avatar: null },
            { id: 3, name: "Emily Rodriguez", email: "emily.r@company.com", role: "Developer", department: "Engineering", status: "active", joinedDate: "2023-03-10", avatar: null },
            { id: 4, name: "David Kim", email: "david.kim@company.com", role: "Designer", department: "Design", status: "active", joinedDate: "2022-11-05", avatar: null },
            { id: 5, name: "Jessica Taylor", email: "jessica.t@company.com", role: "Manager", department: "Marketing", status: "inactive", joinedDate: "2021-06-18", avatar: null },
            { id: 6, name: "Michael Brown", email: "michael.b@company.com", role: "Developer", department: "Engineering", status: "active", joinedDate: "2023-02-28", avatar: null },
            { id: 7, name: "Amanda White", email: "amanda.w@company.com", role: "HR Specialist", department: "HR", status: "active", joinedDate: "2022-09-14", avatar: null },
            { id: 8, name: "Christopher Lee", email: "chris.lee@company.com", role: "Developer", department: "Engineering", status: "active", joinedDate: "2023-04-01", avatar: null },
            { id: 9, name: "Rachel Green", email: "rachel.g@company.com", role: "Designer", department: "Design", status: "active", joinedDate: "2022-12-20", avatar: null },
            { id: 10, name: "Daniel Martinez", email: "daniel.m@company.com", role: "Sales Rep", department: "Sales", status: "inactive", joinedDate: "2021-10-30", avatar: null },
            { id: 11, name: "Olivia Wilson", email: "olivia.w@company.com", role: "Manager", department: "Finance", status: "active", joinedDate: "2022-07-08", avatar: null },
            { id: 12, name: "James Anderson", email: "james.a@company.com", role: "Developer", department: "Engineering", status: "active", joinedDate: "2023-05-15", avatar: null },
            { id: 13, name: "Sophia Thomas", email: "sophia.t@company.com", role: "Marketing Specialist", department: "Marketing", status: "active", joinedDate: "2022-04-25", avatar: null },
            { id: 14, name: "William Garcia", email: "william.g@company.com", role: "Admin", department: "HR", status: "active", joinedDate: "2021-12-01", avatar: null },
            { id: 15, name: "Isabella Moore", email: "isabella.m@company.com", role: "Designer", department: "Design", status: "inactive", joinedDate: "2022-02-14", avatar: null },
            { id: 16, name: "Benjamin Clark", email: "ben.clark@company.com", role: "Developer", department: "Engineering", status: "active", joinedDate: "2023-06-20", avatar: null },
            { id: 17, name: "Mia Robinson", email: "mia.r@company.com", role: "Sales Rep", department: "Sales", status: "active", joinedDate: "2022-10-10", avatar: null },
            { id: 18, name: "Alexander Hall", email: "alex.hall@company.com", role: "Finance Analyst", department: "Finance", status: "active", joinedDate: "2023-01-30", avatar: null },
            { id: 19, name: "Charlotte Young", email: "charlotte.y@company.com", role: "HR Specialist", department: "HR", status: "inactive", joinedDate: "2021-08-05", avatar: null },
            { id: 20, name: "Ethan King", email: "ethan.k@company.com", role: "Manager", department: "Engineering", status: "active", joinedDate: "2022-05-18", avatar: null }
        ];

        // State
        let currentPage = 1;
        let pageSize = 10;
        let sortColumn = null;
        let sortDirection = 'asc';
        let selectedRows = new Set();
        let isLoading = false;
        let openDropdown = null;

        // DOM Elements
        const tableBody = document.getElementById('tableBody');
        const searchInput = document.getElementById('searchInput');
        const departmentFilter = document.getElementById('departmentFilter');
        const statusFilter = document.getElementById('statusFilter');
        const pageSizeSelect = document.getElementById('pageSize');
        const selectAllCheckbox = document.getElementById('selectAll');
        const bulkActionsBar = document.getElementById('bulkActionsBar');
        const selectedCountSpan = document.getElementById('selectedCount');
        const emptyState = document.getElementById('emptyState');
        const pagination = document.getElementById('pagination');
        const paginationInfo = document.getElementById('paginationInfo');
        const prevPageBtn = document.getElementById('prevPage');
        const nextPageBtn = document.getElementById('nextPage');

        // Get initials from name
        function getInitials(name) {
            return name.split(' ').map(n => n[0]).join('').toUpperCase();
        }

        // Get avatar color based on name
        function getAvatarColor(name) {
            const colors = [
                'bg-blue-500', 'bg-green-500', 'bg-yellow-500', 'bg-purple-500',
                'bg-pink-500', 'bg-indigo-500', 'bg-red-500', 'bg-teal-500'
            ];
            const index = name.charCodeAt(0) % colors.length;
            return colors[index];
        }

        // Get role badge style
        function getRoleBadgeStyle(role) {
            const styles = {
                'Admin': 'bg-purple-100 text-purple-700',
                'Manager': 'bg-blue-100 text-blue-700',
                'Developer': 'bg-green-100 text-green-700',
                'Designer': 'bg-pink-100 text-pink-700',
                'HR Specialist': 'bg-yellow-100 text-yellow-700',
                'Sales Rep': 'bg-orange-100 text-orange-700',
                'Marketing Specialist': 'bg-cyan-100 text-cyan-700',
                'Finance Analyst': 'bg-emerald-100 text-emerald-700'
            };
            return styles[role] || 'bg-gray-100 text-gray-700';
        }

        // Format date
        function formatDate(dateStr) {
            const date = new Date(dateStr);
            return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
        }

        // Filter data
        function getFilteredData() {
            const searchTerm = searchInput.value.toLowerCase();
            const department = departmentFilter.value;
            const status = statusFilter.value;

            return teamMembers.filter(member => {
                const matchesSearch = member.name.toLowerCase().includes(searchTerm) ||
                                     member.email.toLowerCase().includes(searchTerm);
                const matchesDepartment = !department || member.department === department;
                const matchesStatus = !status || member.status === status;
                return matchesSearch && matchesDepartment && matchesStatus;
            });
        }

        // Sort data
        function getSortedData(data) {
            if (!sortColumn) return data;

            return [...data].sort((a, b) => {
                let aVal = a[sortColumn];
                let bVal = b[sortColumn];

                if (sortColumn === 'joinedDate') {
                    aVal = new Date(aVal);
                    bVal = new Date(bVal);
                }

                if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
                if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
                return 0;
            });
        }

        // Get paginated data
        function getPaginatedData(data) {
            const start = (currentPage - 1) * pageSize;
            const end = start + pageSize;
            return data.slice(start, end);
        }

        // Render skeleton loading
        function renderSkeleton() {
            let html = '';
            for (let i = 0; i < pageSize; i++) {
                html += `
                    <tr class="animate-pulse">
                        <td class="sticky left-0 bg-white px-4 py-4">
                            <div class="w-4 h-4 skeleton rounded"></div>
                        </td>
                        <td class="px-4 py-4">
                            <div class="flex items-center gap-3">
                                <div class="w-10 h-10 skeleton rounded-full"></div>
                                <div class="w-32 h-4 skeleton rounded"></div>
                            </div>
                        </td>
                        <td class="px-4 py-4"><div class="w-40 h-4 skeleton rounded"></div></td>
                        <td class="px-4 py-4"><div class="w-20 h-6 skeleton rounded-full"></div></td>
                        <td class="px-4 py-4"><div class="w-24 h-4 skeleton rounded"></div></td>
                        <td class="px-4 py-4"><div class="w-16 h-6 skeleton rounded-full"></div></td>
                        <td class="px-4 py-4"><div class="w-24 h-4 skeleton rounded"></div></td>
                        <td class="px-4 py-4"><div class="w-8 h-8 skeleton rounded ml-auto"></div></td>
                    </tr>
                `;
            }
            tableBody.innerHTML = html;
        }

        // Render table
        function renderTable() {
            if (isLoading) {
                renderSkeleton();
                emptyState.classList.add('hidden');
                pagination.classList.remove('hidden');
                return;
            }

            const filteredData = getFilteredData();
            const sortedData = getSortedData(filteredData);
            const paginatedData = getPaginatedData(sortedData);

            if (filteredData.length === 0) {
                tableBody.innerHTML = '';
                emptyState.classList.remove('hidden');
                pagination.classList.add('hidden');
                return;
            }

            emptyState.classList.add('hidden');
            pagination.classList.remove('hidden');

            let html = '';
            paginatedData.forEach(member => {
                const isSelected = selectedRows.has(member.id);
                html += `
                    <tr class="hover:bg-gray-50 transition-colors ${isSelected ? 'bg-primary/5' : ''}">
                        <td class="sticky left-0 ${isSelected ? 'bg-primary/5' : 'bg-white'} px-4 py-4">
                            <input type="checkbox" class="row-checkbox w-4 h-4 rounded border-gray-300 text-primary focus:ring-primary/20 cursor-pointer" 
                                   data-id="${member.id}" ${isSelected ? 'checked' : ''}>
                        </td>
                        <td class="px-4 py-4">
                            <div class="flex items-center gap-3">
                                <div class="w-10 h-10 rounded-full ${getAvatarColor(member.name)} flex items-center justify-center text-white text-sm font-medium">
                                    ${getInitials(member.name)}
                                </div>
                                <span class="font-medium text-gray-900">${member.name}</span>
                            </div>
                        </td>
                        <td class="px-4 py-4 text-gray-600">${member.email}</td>
                        <td class="px-4 py-4">
                            <span class="inline-flex px-2.5 py-1 text-xs font-medium rounded-full ${getRoleBadgeStyle(member.role)}">
                                ${member.role}
                            </span>
                        </td>
                        <td class="px-4 py-4 text-gray-600">${member.department}</td>
                        <td class="px-4 py-4">
                            <span class="inline-flex items-center gap-1.5 px-2.5 py-1 text-xs font-medium rounded-full ${member.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}">
                                <span class="w-1.5 h-1.5 rounded-full ${member.status === 'active' ? 'bg-green-500' : 'bg-gray-400'}"></span>
                                ${member.status.charAt(0).toUpperCase() + member.status.slice(1)}
                            </span>
                        </td>
                        <td class="px-4 py-4 text-gray-600">${formatDate(member.joinedDate)}</td>
                        <td class="px-4 py-4 text-right">
                            <div class="relative inline-block">
                                <button onclick="toggleDropdown(event, ${member.id})" class="p-2 hover:bg-gray-100 rounded-lg transition-colors">
                                    <svg class="w-4 h-4 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/>
                                    </svg>
                                </button>
                                <div id="dropdown-${member.id}" class="hidden absolute right-0 mt-1 w-40 bg-white rounded-lg shadow-lg border border-gray-200 py-1 z-50">
                                    <button onclick="handleAction('edit', ${member.id})" class="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2">
                                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/>
                                        </svg>
                                        Edit
                                    </button>
                                    <button onclick="handleAction('deactivate', ${member.id})" class="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2">
                                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636m12.728 12.728L5.636 5.636"/>
                                        </svg>
                                        ${member.status === 'active' ? 'Deactivate' : 'Activate'}
                                    </button>
                                    <hr class="my-1 border-gray-100">
                                    <button onclick="handleAction('remove', ${member.id})" class="w-full px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center gap-2">
                                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/>
                                        </svg>
                                        Remove
                                    </button>
                                </div>
                            </div>
                        </td>
                    </tr>
                `;
            });

            tableBody.innerHTML = html;
            updatePagination(filteredData.length);
            updateSelectAll();
        }

        // Update pagination info
        function updatePagination(totalItems) {
            const start = (currentPage - 1) * pageSize + 1;
            const end = Math.min(currentPage * pageSize, totalItems);
            paginationInfo.textContent = `${start}-${end} of ${totalItems}`;

            prevPageBtn.disabled = currentPage === 1;
            nextPageBtn.disabled = end >= totalItems;
        }

        // Update select all checkbox
        function updateSelectAll() {
            const checkboxes = document.querySelectorAll('.row-checkbox');
            const allChecked = checkboxes.length > 0 && Array.from(checkboxes).every(cb => cb.checked);
            const someChecked = Array.from(checkboxes).some(cb => cb.checked);

            selectAllCheckbox.checked = allChecked;
            selectAllCheckbox.indeterminate = someChecked && !allChecked;
        }

        // Update bulk actions bar
        function updateBulkActionsBar() {
            if (selectedRows.size > 0) {
                bulkActionsBar.classList.remove('hidden');
                selectedCountSpan.textContent = selectedRows.size;
            } else {
                bulkActionsBar.classList.add('hidden');
            }
        }

        // Sort table
        function sortTable(column) {
            if (sortColumn === column) {
                sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
            } else {
                sortColumn = column;
                sortDirection = 'asc';
            }

            // Update sort icons
            document.querySelectorAll('.sort-icon').forEach(icon => {
                icon.classList.remove('text-primary');
            });
            const activeIcon = document.querySelector(`.sort-icon[data-column="${column}"]`);
            if (activeIcon) {
                activeIcon.classList.add('text-primary');
            }

            currentPage = 1;
            renderTable();
        }

        // Toggle dropdown
        function toggleDropdown(event, id) {
            event.stopPropagation();

            // Close any open dropdown
            if (openDropdown && openDropdown !== id) {
                document.getElementById(`dropdown-${openDropdown}`).classList.add('hidden');
            }

            const dropdown = document.getElementById(`dropdown-${id}`);
            dropdown.classList.toggle('hidden');
            openDropdown = dropdown.classList.contains('hidden') ? null : id;
        }

        // Handle action
        function handleAction(action, id) {
            const member = teamMembers.find(m => m.id === id);
            console.log(`${action} action for:`, member.name);

            if (action === 'deactivate') {
                member.status = member.status === 'active' ? 'inactive' : 'active';
                renderTable();
            } else if (action === 'remove') {
                const index = teamMembers.findIndex(m => m.id === id);
                if (index > -1) {
                    teamMembers.splice(index, 1);
                    selectedRows.delete(id);
                    updateBulkActionsBar();
                    renderTable();
                }
            }

            // Close dropdown
            if (openDropdown) {
                document.getElementById(`dropdown-${openDropdown}`).classList.add('hidden');
                openDropdown = null;
            }
        }

        // Clear selection
        function clearSelection() {
            selectedRows.clear();
            updateBulkActionsBar();
            renderTable();
        }

        // Reset filters
        function resetFilters() {
            searchInput.value = '';
            departmentFilter.value = '';
            statusFilter.value = '';
            currentPage = 1;
            renderTable();
        }

        // Toggle loading state
        function toggleLoading() {
            isLoading = !isLoading;
            renderTable();
        }

        // Event listeners
        searchInput.addEventListener('input', () => {
            currentPage = 1;
            renderTable();
        });

        departmentFilter.addEventListener('change', () => {
            currentPage = 1;
            renderTable();
        });

        statusFilter.addEventListener('change', () => {
            currentPage = 1;
            renderTable();
        });

        pageSizeSelect.addEventListener('change', (e) => {
            pageSize = parseInt(e.target.value);
            currentPage = 1;
            renderTable();
        });

        selectAllCheckbox.addEventListener('change', (e) => {
            const checkboxes = document.querySelectorAll('.row-checkbox');
            checkboxes.forEach(cb => {
                const id = parseInt(cb.dataset.id);
                if (e.target.checked) {
                    selectedRows.add(id);
                } else {
                    selectedRows.delete(id);
                }
            });
            updateBulkActionsBar();
            renderTable();
        });

        tableBody.addEventListener('change', (e) => {
            if (e.target.classList.contains('row-checkbox')) {
                const id = parseInt(e.target.dataset.id);
                if (e.target.checked) {
                    selectedRows.add(id);
                } else {
                    selectedRows.delete(id);
                }
                updateSelectAll();
                updateBulkActionsBar();
                renderTable();
            }
        });

        prevPageBtn.addEventListener('click', () => {
            if (currentPage > 1) {
                currentPage--;
                renderTable();
            }
        });

        nextPageBtn.addEventListener('click', () => {
            const filteredData = getFilteredData();
            const maxPage = Math.ceil(filteredData.length / pageSize);
            if (currentPage < maxPage) {
                currentPage++;
                renderTable();
            }
        });

        // Close dropdown when clicking outside
        document.addEventListener('click', () => {
            if (openDropdown) {
                document.getElementById(`dropdown-${openDropdown}`).classList.add('hidden');
                openDropdown = null;
            }
        });

        // Initial render
        renderTable();
    </script>
</body>
