<script>
// ─── State ────────────────────────────────────────────────────────────────────
const state = {
  ws: null,
  nickname: '',
  currentRoom: null,
  joinedRooms: new Map(),   // roomName → { messages: [], members: [] }
  typingUsers: new Map(),   // roomName → Map<user, timeoutId>
  availableRooms: [],
};

// ─── DOM refs ─────────────────────────────────────────────────────────────────
const $ = (id) => document.getElementById(id);
const statusDot    = $('status-dot');
const statusText   = $('status-text');
const nickInput    = $('nick-input');
const nickForm     = $('nick-form');
const roomList     = $('room-list');
const joinInput    = $('join-input');
const joinForm     = $('join-form');
const chatHeader   = $('current-room-label');
const messagesEl   = $('messages');
const typingBar    = $('typing-bar');
const msgInput     = $('msg-input');
const sendBtn      = $('send-btn');
const leaveBtn     = $('leave-btn');
const memberList   = $('member-list');
const emptyState   = $('empty-state');

// ─── WebSocket connection ─────────────────────────────────────────────────────
function connect() {
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  const ws = new WebSocket(`${proto}://${location.host}`);
  state.ws = ws;

  ws.addEventListener('open', () => {
    setStatus(true);
    toast('Connected to server', 'success');
  });

  ws.addEventListener('close', () => {
    setStatus(false);
    toast('Disconnected. Reconnecting in 3 s…', 'error');
    setTimeout(connect, 3000);
  });

  ws.addEventListener('error', () => {
    toast('WebSocket error', 'error');
  });

  ws.addEventListener('message', ({ data }) => {
    let msg;
    try { msg = JSON.parse(data); } catch { return; }
    handleMessage(msg);
  });
}

// ─── Message dispatcher ───────────────────────────────────────────────────────
function handleMessage(msg) {
  switch (msg.type) {

    case 'system':
      if (msg.room) {
        appendMessage(msg.room, msg);
      } else {
        // Server-level system message (welcome, nick change confirm, etc.)
        if (msg.nickname) {
          // Nick was accepted
          state.nickname = msg.nickname;
          nickInput.value = msg.nickname;
          toast(`Nickname set to "${msg.nickname}"`, 'success');
        }
        if (msg.rooms) {
          state.availableRooms = msg.rooms;
          renderRoomList();
        }
      }
      break;

    case 'joined':
      // We successfully joined a room
      if (!state.joinedRooms.has(msg.room)) {
        state.joinedRooms.set(msg.room, { messages: [], members: msg.members || [] });
        state.typingUsers.set(msg.room, new Map());
      } else {
        state.joinedRooms.get(msg.room).members = msg.members || [];
      }
      renderRoomList();
      switchRoom(msg.room);
      break;

    case 'left':
      state.joinedRooms.delete(msg.room);
      state.typingUsers.delete(msg.room);
      if (state.currentRoom === msg.room) {
        state.currentRoom = null;
        renderChat();
      }
      renderRoomList();
      break;

    case 'history': {
      const roomData = state.joinedRooms.get(msg.room);
      if (roomData) {
        roomData.messages = msg.messages || [];
        roomData.members  = msg.members  || [];
        if (state.currentRoom === msg.room) renderChat();
      }
      break;
    }

    case 'message':
      appendMessage(msg.room, msg);
      // Unread badge if not current room
      if (msg.room !== state.currentRoom) {
        markUnread(msg.room);
      }
      break;

    case 'typing': {
      const typingMap = state.typingUsers.get(msg.room);
      if (!typingMap) break;
      if (msg.isTyping) {
        if (typingMap.has(msg.user)) clearTimeout(typingMap.get(msg.user));
        const tid = setTimeout(() => {
          typingMap.delete(msg.user);
          if (state.currentRoom === msg.room) renderTyping();
        }, 4000);
        typingMap.set(msg.user, tid);
      } else {
        if (typingMap.has(msg.user)) {
          clearTimeout(typingMap.get(msg.user));
          typingMap.delete(msg.user);
        }
      }
      if (state.currentRoom === msg.room) renderTyping();
      break;
    }

    case 'rooms':
      state.availableRooms = msg.rooms || [];
      renderRoomList();
      break;

    case 'members': {
      const roomData = state.joinedRooms.get(msg.room);
      if (roomData) {
        roomData.members = msg.members || [];
        if (state.currentRoom === msg.room) renderMembers();
      }
      break;
    }

    case 'error':
      toast(msg.content, 'error');
      break;
  }
}

// ─── Append a message to a room's local store ─────────────────────────────────
function appendMessage(roomName, msg) {
  const roomData = state.joinedRooms.get(roomName);
  if (!roomData) return;

  // Update member list on join/leave events
  if (msg.event === 'joined' && msg.who) {
    if (!roomData.members.includes(msg.who)) roomData.members.push(msg.who);
    roomData.members.sort();
  } else if (msg.event === 'left' && msg.who) {
    roomData.members = roomData.members.filter((m) => m !== msg.who);
  }

  roomData.messages.push(msg);
  if (roomData.messages.length > 200) roomData.messages.shift();

  if (state.currentRoom === roomName) {
    renderSingleMessage(msg, roomData.messages.length - 1, roomData.messages);
    renderMembers();
    scrollToBottom();
  }
}

// ─── Render helpers ───────────────────────────────────────────────────────────
function renderChat() {
  messagesEl.innerHTML = '';
  if (!state.currentRoom) {
    messagesEl.appendChild(emptyState);
    chatHeader.textContent = 'Select a room';
    msgInput.disabled = true;
    sendBtn.disabled = true;
    leaveBtn.disabled = true;
    renderMembers();
    renderTyping();
    return;
  }

  emptyState.remove();
  chatHeader.innerHTML = `<span class="hash">#</span>${state.currentRoom}`;
  msgInput.disabled = false;
  sendBtn.disabled = false;
  leaveBtn.disabled = false;

  const roomData = state.joinedRooms.get(state.currentRoom);
  if (roomData) {
    roomData.messages.forEach((msg, i) => {
      renderSingleMessage(msg, i, roomData.messages);
    });
  }

  renderMembers();
  renderTyping();
  scrollToBottom();
}

function renderSingleMessage(msg, index, allMessages) {
  const el = document.createElement('div');

  if (msg.type === 'system') {
    el.className = 'msg system';
    const content = document.createElement('span');
    content.className = 'msg-content';
    content.textContent = msg.content;
    el.appendChild(content);
    messagesEl.appendChild(el);
    return;
  }

  const isOwn = msg.user === state.nickname;
  const prev  = allMessages[index - 1];
  const isCompact = prev
    && prev.type === 'message'
    && prev.user === msg.user
    && (new Date(msg.timestamp) - new Date(prev.timestamp)) < 5 * 60 * 1000;

  el.className = `msg${isOwn ? ' own' : ''}${isCompact ? ' compact' : ''}`;

  // Avatar
  const avatar = document.createElement('div');
  avatar.className = 'msg-avatar';
  avatar.style.background = stringToColor(msg.user);
  avatar.textContent = (msg.user || '?')[0].toUpperCase();
  el.appendChild(avatar);

  // Right side
  const right = document.createElement('div');

  if (!isCompact) {
    const meta = document.createElement('div');
    meta.className = 'msg-meta';

    const author = document.createElement('span');
    author.className = 'msg-author';
    author.style.color = stringToColor(msg.user);
    author.textContent = msg.user;

    const time = document.createElement('span');
    time.className = 'msg-time';
    time.textContent = formatTime(msg.timestamp);

    meta.appendChild(author);
    meta.appendChild(time);
    right.appendChild(meta);
  }

  const content = document.createElement('div');
  content.className = 'msg-content';
  content.textContent = msg.content;
  right.appendChild(content);

  el.appendChild(right);
  messagesEl.appendChild(el);
}

function renderRoomList() {
  roomList.innerHTML = '';

  // Joined rooms first
  const joined = [...state.joinedRooms.keys()];
  const others = state.availableRooms.filter((r) => !state.joinedRooms.has(r));
  const all = [...joined, ...others.filter((r) => !joined.includes(r))];

  if (all.length === 0) {
    const hint = document.createElement('div');
    hint.style.cssText = 'padding:8px 12px;font-size:.8rem;color:var(--text-dim)';
    hint.textContent = 'No rooms yet. Create one below!';
    roomList.appendChild(hint);
    return;
  }

  all.forEach((name) => {
    const item = document.createElement('div');
    item.className = 'room-item' +
      (state.currentRoom === name ? ' active' : '') +
      (state.joinedRooms.has(name) ? '' : ' not-joined');

    const hash = document.createElement('span');
    hash.className = 'hash';
    hash.textContent = '#';

    const label = document.createElement('span');
    label.textContent = name;

    item.appendChild(hash);
    item.appendChild(label);

    // Unread badge
    const badge = document.createElement('span');
    badge.id = `badge-${name}`;
    badge.style.cssText = `
      margin-left:auto;
      background:var(--accent);
      color:#fff;
      border-radius:10px;
      padding:1px 6px;
      font-size:.7rem;
      font-weight:700;
      display:none;
    `;
    item.appendChild(badge);

    item.addEventListener('click', () => {
      if (state.joinedRooms.has(name)) {
        switchRoom(name);
      } else {
        sendWS({ type: 'join', room: name });
      }
    });

    roomList.appendChild(item);
  });
}

function renderMembers() {
  memberList.innerHTML = '';
  if (!state.currentRoom) return;
  const roomData = state.joinedRooms.get(state.currentRoom);
  if (!roomData) return;

  roomData.members.forEach((nick) => {
    const item = document.createElement('div');
    item.className = 'member-item';

    const dot = document.createElement('div');
    dot.className = 'member-dot';
    dot.style.background = stringToColor(nick);

    const name = document.createElement('span');
    name.textContent = nick;
    if (nick === state.nickname) {
      name.style.color = 'var(--text)';
      name.style.fontWeight = '600';
    }

    item.appendChild(dot);
    item.appendChild(name);
    memberList.appendChild(item);
  });
}

function renderTyping() {
  typingBar.innerHTML = '';
  if (!state.currentRoom) return;
  const typingMap = state.typingUsers.get(state.currentRoom);
  if (!typingMap || typingMap.size === 0) return;

  const users = [...typingMap.keys()];
  const names = users.length <= 2
    ? users.join(' and ')
    : `${users.slice(0, 2).join(', ')} and ${users.length - 2} more`;

  const dots = `<span class="typing-dots">
    <span></span><span></span><span></span>
  </span>`;
  typingBar.innerHTML = `${dots} <em>${escapeHtml(names)} ${users.length === 1 ? 'is' : 'are'} typing…</em>`;
}

function switchRoom(name) {
  state.currentRoom = name;
  clearUnread(name);
  renderRoomList();
  renderChat();
  msgInput.focus();
}

function markUnread(roomName) {
  const badge = document.getElementById(`badge-${roomName}`);
  if (!badge) return;
  const count = parseInt(badge.dataset.count || '0') + 1;
  badge.dataset.count = count;
  badge.textContent = count > 99 ? '99+' : count;
  badge.style.display = 'inline';
}

function clearUnread(roomName) {
  const badge = document.getElementById(`badge-${roomName}`);
  if (!badge) return;
  badge.dataset.count = '0';
  badge.style.display = 'none';
}

function scrollToBottom() {
  messagesEl.scrollTop = messagesEl.scrollHeight;
}

// ─── Typing indicator ─────────────────────────────────────────────────────────
let typingTimeout = null;
let isTyping = false;

msgInput.addEventListener('input', () => {
  if (!state.currentRoom) return;

  if (!isTyping) {
    isTyping = true;
    sendWS({ type: 'typing', room: state.currentRoom, isTyping: true });
  }

  clearTimeout(typingTimeout);
  typingTimeout = setTimeout(() => {
    isTyping = false;
    sendWS({ type: 'typing', room: state.currentRoom, isTyping: false });
  }, 2000);
});

// ─── Send message ─────────────────────────────────────────────────────────────
function sendMessage() {
  const content = msgInput.value.trim();
  if (!content || !state.currentRoom) return;

  sendWS({ type: 'message', room: state.currentRoom, content });
  msgInput.value = '';

  // Stop typing indicator
  clearTimeout(typingTimeout);
  if (isTyping) {
    isTyping = false;
    sendWS({ type: 'typing', room: state.currentRoom, isTyping: false });
  }
}

sendBtn.addEventListener('click', sendMessage);

msgInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    sendMessage();
  }
});

// ─── Leave room ───────────────────────────────────────────────────────────────
leaveBtn.addEventListener('click', () => {
  if (state.currentRoom) {
    sendWS({ type: 'leave', room: state.currentRoom });
  }
});

// ─── Nick form ────────────────────────────────────────────────────────────────
nickForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const nick = nickInput.value.trim();
  if (nick) sendWS({ type: 'nick', nickname: nick });
});

// ─── Join form ────────────────────────────────────────────────────────────────
joinForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const room = joinInput.value.trim().toLowerCase();
  if (room) {
    sendWS({ type: 'join', room });
    joinInput.value = '';
  }
});

// ─── Utilities ────────────────────────────────────────────────────────────────
function sendWS(payload) {
  if (state.ws && state.ws.readyState === WebSocket.OPEN) {
    state.ws.send(JSON.stringify(payload));
  }
}

function setStatus(connected) {
  statusDot.className = connected ? 'connected' : '';
  statusText.textContent = connected ? 'Connected' : 'Disconnected';
}

function formatTime(iso) {
  const d = new Date(iso);
  return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

function escapeHtml(str) {
  return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

/** Deterministic colour from a string (for avatars). */
function stringToColor(str = '') {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = str.charCodeAt(i) + ((hash << 5) - hash);
  }
  const hue = Math.abs(hash) % 360;
  return `hsl(${hue}, 60%, 55%)`;
}

function toast(message, type = 'info') {
  const el = document.createElement('div');
  el.className = `toast ${type}`;
  el.textContent = message;
  $('toast-container').appendChild(el);
  setTimeout(() => el.remove(), 4000);
}

// ─── Boot ─────────────────────────────────────────────────────────────────────
connect();
</script>
</body>
</html>
```

## How It Works

### Server Architecture

```
Client connects
    │
    ├─► Assigned Guest{id} nickname
    ├─► Receives welcome + room list
    │
    ├─► type: "nick"     → validate, check duplicates, notify rooms
    ├─► type: "join"     → add to room, send history + members, broadcast join
    ├─► type: "leave"    → remove from room, broadcast leave, prune empty rooms
    ├─► type: "message"  → validate, store in history (capped at 50), broadcast
    ├─► type: "typing"   → forward to room (excluding sender)
    ├─► type: "rooms"    → return current room list
    └─► type: "members"  → return members of a specific room
```

### Message Protocol

| Type | Direction | Purpose |
|------|-----------|---------|
| `nick` | C→S | Set nickname |
| `join` | C→S | Join a room |
| `leave` | C→S | Leave a room |
| `message` | C↔S | Chat message |
| `typing` | C↔S | Typing indicator |
| `rooms` | C→S | Request room list |
| `members` | C→S | Request member list |
| `history` | S→C | Room history on join |
| `system` | S→C | Server notifications |
| `error` | S→C | Error feedback |

### Running

```bash
npm install
npm start
# Open http://localhost:3000
```

### Key Features
- **Heartbeat ping/pong** every 30s to detect dead connections
- **Compact messages** — consecutive messages from the same user collapse the avatar/header
- **Unread badges** on rooms you're not currently viewing
- **Auto-reconnect** on disconnect with 3s delay
- **Deterministic avatar colours** from nickname hash
- **Input sanitisation** on both server (room names, message length) and client

I'll build a complete, well-structured `fstats` CLI tool. Let me walk through the design before the code:

**Architecture:**
- `Scanner` class handles file discovery with exclusion patterns
- `Analyzer` class computes all statistics
- `Comparator` class handles directory comparison
- `Formatter` class handles json/table/csv output
- `Progress` class provides terminal progress indication
- Color support via ANSI codes with terminal detection

```python
#!/usr/bin/env python3
"""
fstats - File Statistics CLI Tool
Recursively analyze directories and compare them.

Usage:
    fstats analyze <path> [--format json|table|csv] [--exclude <pattern>]
    fstats compare <path1> <path2> [--format json|table|csv] [--exclude <pattern>]
"""

import argparse
import csv
import hashlib
import io
import json
import os
import sys
import time
from collections import defaultdict
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Dict, Generator, List, Optional, Set, Tuple

# ─────────────────────────────────────────────
# Color Support
# ─────────────────────────────────────────────

def _supports_color() -> bool:
    """Return True if the terminal supports ANSI color codes."""
    if not hasattr(sys.stdout, "isatty") or not sys.stdout.isatty():
        return False
    if sys.platform == "win32":
        try:
            import ctypes
            kernel32 = ctypes.windll.kernel32          # type: ignore[attr-defined]
            # Enable VIRTUAL_TERMINAL_PROCESSING
            kernel32.SetConsoleMode(kernel32.GetStdHandle(-11), 7)
            return True
        except Exception:
            return False
    return os.environ.get("TERM", "") != "dumb"


class Color:
    """ANSI color codes with automatic fallback."""

    _USE_COLOR = _supports_color()

    RESET   = "\033[0m"
    BOLD    = "\033[1m"
    DIM     = "\033[2m"
    RED     = "\033[31m"
    GREEN   = "\033[32m"
    YELLOW  = "\033[33m"
    BLUE    = "\033[34m"
    MAGENTA = "\033[35m"
    CYAN    = "\033[36m"
    WHITE   = "\033[37m"
    BRIGHT_RED     = "\033[91m"
    BRIGHT_GREEN   = "\033[92m"
    BRIGHT_YELLOW  = "\033[93m"
    BRIGHT_BLUE    = "\033[94m"
    BRIGHT_MAGENTA = "\033[95m"
    BRIGHT_CYAN    = "\033[96m"

    @classmethod
    def wrap(cls, text: str, *codes: str) -> str:
        if not cls._USE_COLOR:
            return text
        return "".join(codes) + text + cls.RESET

    @classmethod
    def bold(cls, text: str) -> str:
        return cls.wrap(text, cls.BOLD)

    @classmethod
    def dim(cls, text: str) -> str:
        return cls.wrap(text, cls.DIM)

    @classmethod
    def header(cls, text: str) -> str:
        return cls.wrap(text, cls.BOLD, cls.BRIGHT_CYAN)

    @classmethod
    def success(cls, text: str) -> str:
        return cls.wrap(text, cls.BRIGHT_GREEN)

    @classmethod
    def warning(cls, text: str) -> str:
        return cls.wrap(text, cls.BRIGHT_YELLOW)

    @classmethod
    def error(cls, text: str) -> str:
        return cls.wrap(text, cls.BRIGHT_RED)

    @classmethod
    def info(cls, text: str) -> str:
        return cls.wrap(text, cls.BRIGHT_BLUE)

    @classmethod
    def accent(cls, text: str) -> str:
        return cls.wrap(text, cls.BRIGHT_MAGENTA)


# ─────────────────────────────────────────────
# Progress Indicator
# ─────────────────────────────────────────────

class Progress:
    """
    Simple terminal progress indicator.
    Shows a spinner + count when stdout is a TTY; silent otherwise.
    """

    _SPINNER = ("⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏")
    # ASCII fallback for terminals that can't render braille
    _SPINNER_ASCII = ("|", "/", "-", "\\")

    def __init__(self, label: str = "Scanning") -> None:
        self._label = label
        self._count = 0
        self._start = time.monotonic()
        self._active = sys.stderr.isatty()
        self._frame = 0
        self._last_render = 0.0
        # Choose spinner style
        try:
            "⠋".encode(sys.stderr.encoding or "utf-8")
            self._frames = self._SPINNER
        except (UnicodeEncodeError, LookupError):
            self._frames = self._SPINNER_ASCII

    def update(self, increment: int = 1) -> None:
        self._count += increment
        now = time.monotonic()
        # Throttle redraws to ~20 fps
        if self._active and (now - self._last_render) >= 0.05:
            self._render()
            self._last_render = now

    def _render(self) -> None:
        frame = self._frames[self._frame % len(self._frames)]
        self._frame += 1
        elapsed = time.monotonic() - self._start
        line = f"\r  {frame}  {self._label}: {self._count:,} files  ({elapsed:.1f}s)"
        sys.stderr.write(line)
        sys.stderr.flush()

    def done(self) -> None:
        if self._active:
            elapsed = time.monotonic() - self._start
            sys.stderr.write(
                f"\r  ✓  {self._label}: {self._count:,} files  ({elapsed:.1f}s)\n"
            )
            sys.stderr.flush()


# ─────────────────────────────────────────────
# Data Classes
# ─────────────────────────────────────────────

@dataclass
class FileInfo:
    path: Path
    size: int
    mtime: float          # seconds since epoch
    extension: str        # lowercase, includes dot; '' for no extension

    @property
    def age_days(self) -> float:
        return (time.time() - self.mtime) / 86_400

    @property
    def mtime_dt(self) -> datetime:
        return datetime.fromtimestamp(self.mtime, tz=timezone.utc)


@dataclass
class AnalysisResult:
    root: Path
    files: List[FileInfo] = field(default_factory=list)
    # extension → count
    ext_count: Dict[str, int] = field(default_factory=dict)
    # extension → total bytes
    ext_size: Dict[str, int] = field(default_factory=dict)
    largest: List[FileInfo] = field(default_factory=list)
    # hash → list of paths
    duplicates: Dict[str, List[Path]] = field(default_factory=dict)
    avg_age_days: float = 0.0
    total_size: int = 0
    errors: List[str] = field(default_factory=list)


@dataclass
class CompareResult:
    path1: Path
    path2: Path
    only_in_1: List[str] = field(default_factory=list)   # relative paths
    only_in_2: List[str] = field(default_factory=list)
    modified: List[str] = field(default_factory=list)    # same name, diff hash
    identical: int = 0
    errors: List[str] = field(default_factory=list)


# ─────────────────────────────────────────────
# Scanner
# ─────────────────────────────────────────────

class Scanner:
    """Walk a directory tree and yield FileInfo objects."""

    def __init__(self, exclude_patterns: Optional[List[str]] = None) -> None:
        self._excludes: List[str] = exclude_patterns or []

    def _is_excluded(self, path: Path) -> bool:
        from fnmatch import fnmatch
        name = path.name
        for pattern in self._excludes:
            if fnmatch(name, pattern) or fnmatch(str(path), pattern):
                return True
        return False

    def scan(
        self,
        root: Path,
        progress: Optional[Progress] = None,
    ) -> Tuple[List[FileInfo], List[str]]:
        """
        Return (list_of_FileInfo, list_of_error_strings).
        Symlinks are skipped to avoid loops.
        """
        files: List[FileInfo] = []
        errors: List[str] = []

        for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
            dp = Path(dirpath)

            # Prune excluded directories in-place
            dirnames[:] = [
                d for d in dirnames
                if not self._is_excluded(dp / d)
            ]

            for fname in filenames:
                fpath = dp / fname
                if self._is_excluded(fpath):
                    continue
                if fpath.is_symlink():
                    continue
                try:
                    stat = fpath.stat()
                    ext = fpath.suffix.lower()
                    files.append(FileInfo(
                        path=fpath,
                        size=stat.st_size,
                        mtime=stat.st_mtime,
                        extension=ext if ext else "(no ext)",
                    ))
                    if progress:
                        progress.update()
                except OSError as exc:
                    errors.append(f"{fpath}: {exc}")

        return files, errors


# ─────────────────────────────────────────────
# Hasher
# ─────────────────────────────────────────────

def _hash_file(path: Path, chunk: int = 65_536) -> Optional[str]:
    """Return SHA-256 hex digest of a file, or None on error."""
    h = hashlib.sha256()
    try:
        with path.open("rb") as fh:
            while True:
                block = fh.read(chunk)
                if not block:
                    break
                h.update(block)
        return h.hexdigest()
    except OSError:
        return None


# ─────────────────────────────────────────────
# Analyzer
# ─────────────────────────────────────────────

class Analyzer:
    """Compute statistics from a list of FileInfo objects."""

    TOP_N = 10

    def analyze(self, root: Path, files: List[FileInfo], errors: List[str]) -> AnalysisResult:
        result = AnalysisResult(root=root, files=files, errors=errors)

        if not files:
            return result

        # Extension counts and sizes
        ext_count: Dict[str, int] = defaultdict(int)
        ext_size: Dict[str, int] = defaultdict(int)
        total_size = 0
        total_age = 0.0

        for fi in files:
            ext_count[fi.extension] += 1
            ext_size[fi.extension] += fi.size
            total_size += fi.size
            total_age += fi.age_days

        result.ext_count = dict(ext_count)
        result.ext_size = dict(ext_size)
        result.total_size = total_size
        result.avg_age_days = total_age / len(files)

        # Largest files
        result.largest = sorted(files, key=lambda f: f.size, reverse=True)[: self.TOP_N]

        # Duplicate detection — group by size first (cheap), then hash
        size_groups: Dict[int, List[FileInfo]] = defaultdict(list)
        for fi in files:
            size_groups[fi.size].append(fi)

        hash_groups: Dict[str, List[Path]] = defaultdict(list)
        for size, group in size_groups.items():
            if size == 0 or len(group) < 2:
                continue
            for fi in group:
                digest = _hash_file(fi.path)
                if digest:
                    hash_groups[digest].append(fi.path)

        result.duplicates = {
            h: paths for h, paths in hash_groups.items() if len(paths) > 1
        }

        return result


# ─────────────────────────────────────────────
# Comparator
# ─────────────────────────────────────────────

class Comparator:
    """Compare two directory trees."""

    def compare(
        self,
        path1: Path,
        path2: Path,
        files1: List[FileInfo],
        files2: List[FileInfo],
        errors: List[str],
    ) -> CompareResult:
        result = CompareResult(path1=path1, path2=path2, errors=errors)

        # Build relative-path → FileInfo maps
        def rel_map(root: Path, files: List[FileInfo]) -> Dict[str, FileInfo]:
            m: Dict[str, FileInfo] = {}
            for fi in files:
                try:
                    rel = str(fi.path.relative_to(root))
                    m[rel] = fi
                except ValueError:
                    pass
            return m

        map1 = rel_map(path1, files1)
        map2 = rel_map(path2, files2)

        keys1: Set[str] = set(map1)
        keys2: Set[str] = set(map2)

        result.only_in_1 = sorted(keys1 - keys2)
        result.only_in_2 = sorted(keys2 - keys1)

        # Files present in both — compare by hash
        common = keys1 & keys2
        for rel in sorted(common):
            fi1 = map1[rel]
            fi2 = map2[rel]
            if fi1.size == fi2.size and fi1.mtime == fi2.mtime:
                # Fast path: assume identical
                result.identical += 1
                continue
            h1 = _hash_file(fi1.path)
            h2 = _hash_file(fi2.path)
            if h1 is None or h2 is None:
                result.errors.append(f"Could not hash {rel}")
            elif h1 == h2:
                result.identical += 1
            else:
                result.modified.append(rel)

        return result


# ─────────────────────────────────────────────
# Formatting Helpers
# ─────────────────────────────────────────────

def _human_size(n: int) -> str:
    """Convert bytes to a human-readable string."""
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if abs(n) < 1024:
            return f"{n:.1f} {unit}"
        n /= 1024  # type: ignore[assignment]
    return f"{n:.1f} PB"


def _age_str(days: float) -> str:
    if days < 1:
        return f"{days * 24:.1f}h"
    if days < 30:
        return f"{days:.1f}d"
    if days < 365:
        return f"{days / 30:.1f}mo"
    return f"{days / 365:.1f}yr"


# ─────────────────────────────────────────────
# Table Renderer
# ─────────────────────────────────────────────

class TableRenderer:
    """Minimal table renderer — no external dependencies."""

    def __init__(self, headers: List[str], rows: List[List[str]]) -> None:
        self._headers = headers
        self._rows = rows

    def render(self) -> str:
        all_rows = [self._headers] + self._rows
        widths = [
            max(len(str(row[i])) for row in all_rows)
            for i in range(len(self._headers))
        ]

        def fmt_row(row: List[str], bold: bool = False) -> str:
            cells = [str(row[i]).ljust(widths[i]) for i in range(len(row))]
            line = "  ".join(cells)
            return Color.bold(line) if bold else line

        sep = "  ".join("─" * w for w in widths)
        lines = [
            fmt_row(self._headers, bold=True),
            Color.dim(sep),
        ]
        for row in self._rows:
            lines.append(fmt_row(row))
        return "\n".join(lines)


# ─────────────────────────────────────────────
# Formatter
# ─────────────────────────────────────────────

class Formatter:
    """Render AnalysisResult or CompareResult in the requested format."""

    def __init__(self, fmt: str) -> None:
        if fmt not in ("table", "json", "csv"):
            raise ValueError(f"Unknown format: {fmt!r}")
        self.fmt = fmt

    # ── Analysis ──────────────────────────────

    def format_analysis(self, result: AnalysisResult) -> str:
        if self.fmt == "json":
            return self._analysis_json(result)
        if self.fmt == "csv":
            return self._analysis_csv(result)
        return self._analysis_table(result)

    def _analysis_json(self, r: AnalysisResult) -> str:
        data = {
            "root": str(r.root),
            "total_files": len(r.files),
            "total_size_bytes": r.total_size,
            "total_size_human": _human_size(r.total_size),
            "avg_age_days": round(r.avg_age_days, 2),
            "extensions": {
                ext: {
                    "count": r.ext_count[ext],
                    "size_bytes": r.ext_size[ext],
                    "size_human": _human_size(r.ext_size[ext]),
                }
                for ext in sorted(r.ext_count, key=lambda e: r.ext_count[e], reverse=True)
            },
            "largest_files": [
                {
                    "path": str(fi.path),
                    "size_bytes": fi.size,
                    "size_human": _human_size(fi.size),
                    "mtime": fi.mtime_dt.isoformat(),
                }
                for fi in r.largest
            ],
            "duplicate_groups": [
                {"hash": h, "paths": [str(p) for p in paths]}
                for h, paths in r.duplicates.items()
            ],
            "errors": r.errors,
        }
        return json.dumps(data, indent=2)

    def _analysis_csv(self, r: AnalysisResult) -> str:
        buf = io.StringIO()
        w = csv.writer(buf)

        w.writerow(["# Summary"])
        w.writerow(["root", str(r.root)])
        w.writerow(["total_files", len(r.files)])
        w.writerow(["total_size_bytes", r.total_size])
        w.writerow(["avg_age_days", round(r.avg_age_days, 2)])
        w.writerow([])

        w.writerow(["# Extensions"])
        w.writerow(["extension", "count", "size_bytes", "size_human"])
        for ext in sorted(r.ext_count, key=lambda e: r.ext_count[e], reverse=True):
            w.writerow([ext, r.ext_count[ext], r.ext_size[ext], _human_size(r.ext_size[ext])])
        w.writerow([])

        w.writerow(["# Largest Files"])
        w.writerow(["path", "size_bytes", "size_human", "mtime"])
        for fi in r.largest:
            w.writerow([str(fi.path), fi.size, _human_size(fi.size), fi.mtime_dt.isoformat()])
        w.writerow([])

        w.writerow(["# Duplicate Groups"])
        w.writerow(["hash", "paths"])
        for h, paths in r.duplicates.items():
            w.writerow([h, "; ".join(str(p) for p in paths)])

        return buf.getvalue()

    def _analysis_table(self, r: AnalysisResult) -> str:
        lines: List[str] = []

        # ── Header ──
        lines.append("")
        lines.append(Color.header(f"  📁  Analysis: {r.root}"))
        lines.append(Color.dim("  " + "─" * 60))
        lines.append(
            f"  Total files : {Color.bold(f'{len(r.files):,}')}"
        )
        lines.append(
            f"  Total size  : {Color.bold(_human_size(r.total_size))}"
        )
        lines.append(
            f"  Avg file age: {Color.bold(_age_str(r.avg_age_days))}"
        )
        lines.append("")

        # ── Extensions ──
        lines.append(Color.header("  Extensions"))
        lines.append("")
        ext_rows = [
            [
                ext,
                str(r.ext_count[ext]),
                _human_size(r.ext_size[ext]),
                f"{r.ext_size[ext] / r.total_size * 100:.1f}%" if r.total_size else "0%",
            ]
            for ext in sorted(r.ext_count, key=lambda e: r.ext_count[e], reverse=True)
        ]
        tbl = TableRenderer(["Extension", "Count", "Size", "% of Total"], ext_rows)
        for line in tbl.render().splitlines():
            lines.append("    " + line)
        lines.append("")

        # ── Largest Files ──
        lines.append(Color.header(f"  Largest {len(r.largest)} Files"))
        lines.append("")
        large_rows = [
            [_human_size(fi.size), str(fi.path)]
            for fi in r.largest
        ]
        tbl2 = TableRenderer(["Size", "Path"], large_rows)
        for line in tbl2.render().splitlines():
            lines.append("    " + line)
        lines.append("")

        # ── Duplicates ──
        lines.append(Color.header("  Duplicate Files"))
        lines.append("")
        if not r.duplicates:
            lines.append(Color.success("    ✓  No duplicates found."))
        else:
            dup_count = sum(len(v) for v in r.duplicates.values())
            wasted = sum(
                (len(v) - 1) * _file_size_from_paths(v)
                for v in r.duplicates.values()
            )
            lines.append(
                f"    {Color.warning(f'⚠  {len(r.duplicates)} duplicate group(s), '
                                     f'{dup_count} files, '
                                     f'~{_human_size(wasted)} wasted')}"
            )
            lines.append("")
            for i, (h, paths) in enumerate(r.duplicates.items(), 1):
                lines.append(
                    f"    {Color.accent(f'Group {i}')}  "
                    f"{Color.dim(h[:12] + '…')}"
                )
                for p in paths:
                    lines.append(f"      {Color.dim('•')} {p}")
        lines.append("")

        # ── Errors ──
        if r.errors:
            lines.append(Color.header("  Errors"))
            for e in r.errors:
                lines.append(f"    {Color.error('✗')} {e}")
            lines.append("")

        return "\n".join(lines)

    # ── Compare ───────────────────────────────

    def format_compare(self, result: CompareResult) -> str:
        if self.fmt == "json":
            return self._compare_json(result)
        if self.fmt == "csv":
            return self._compare_csv(result)
        return self._compare_table(result)

    def _compare_json(self, r: CompareResult) -> str:
        data = {
            "path1": str(r.path1),
            "path2": str(r.path2),
            "only_in_path1": r.only_in_1,
            "only_in_path2": r.only_in_2,
            "modified": r.modified,
            "identical_count": r.identical,
            "summary": {
                "only_in_path1": len(r.only_in_1),
                "only_in_path2": len(r.only_in_2),
                "modified": len(r.modified),
                "identical": r.identical,
            },
            "errors": r.errors,
        }
        return json.dumps(data, indent=2)

    def _compare_csv(self, r: CompareResult) -> str:
        buf = io.StringIO()
        w = csv.writer(buf)

        w.writerow(["# Summary"])
        w.writerow(["path1", str(r.path1)])
        w.writerow(["path2", str(r.path2)])
        w.writerow(["only_in_path1", len(r.only_in_1)])
        w.writerow(["only_in_path2", len(r.only_in_2)])
        w.writerow(["modified", len(r.modified)])
        w.writerow(["identical", r.identical])
        w.writerow([])

        w.writerow(["# Only in path1"])
        for p in r.only_in_1:
            w.writerow([p])
        w.writerow([])

        w.writerow(["# Only in path2"])
        for p in r.only_in_2:
            w.writerow([p])
        w.writerow([])

        w.writerow(["# Modified (same name, different content)"])
        for p in r.modified:
            w.writerow([p])

        return buf.getvalue()

    def _compare_table(self, r: CompareResult) -> str:
        lines: List[str] = []

        lines.append("")
        lines.append(Color.header("  🔍  Directory Comparison"))
        lines.append(Color.dim("  " + "─" * 60))
        lines.append(f"  Path 1: {Color.info(str(r.path1))}")
        lines.append(f"  Path 2: {Color.info(str(r.path2))}")
        lines.append("")

        # Summary table
        summary_rows = [
            ["Only in Path 1",  Color.warning(str(len(r.only_in_1)))],
            ["Only in Path 2",  Color.warning(str(len(r.only_in_2)))],
            ["Modified",        Color.error(str(len(r.modified)))   ],
            ["Identical",       Color.success(str(r.identical))     ],
        ]
        tbl = TableRenderer(["Category", "Count"], summary_rows)
        lines.append(Color.header("  Summary"))
        lines.append("")
        for line in tbl.render().splitlines():
            lines.append("    " + line)
        lines.append("")

        def _section(title: str, items: List[str], color_fn) -> None:
            lines.append(Color.header(f"  {title}"))
            lines.append("")
            if not items:
                lines.append(Color.dim("    (none)"))
            else:
                for item in items:
                    lines.append(f"    {color_fn('•')} {item}")
            lines.append("")

        _section(
            f"Only in Path 1  ({len(r.only_in_1)} files)",
            r.only_in_1,
            Color.warning,
        )
        _section(
            f"Only in Path 2  ({len(r.only_in_2)} files)",
            r.only_in_2,
            Color.info,
        )
        _section(
            f"Modified Files  ({len(r.modified)} files)",
            r.modified,
            Color.error,
        )

        if r.errors:
            lines.append(Color.header("  Errors"))
            for e in r.errors:
                lines.append(f"    {Color.error('✗')} {e}")
            lines.append("")

        return "\n".join(lines)


def _file_size_from_paths(paths: List[Path]) -> int:
    """Return the size of the first readable file in the list."""
    for p in paths:
        try:
            return p.stat().st_size
        except OSError:
            pass
    return 0


# ─────────────────────────────────────────────
# CLI Entry Points
# ─────────────────────────────────────────────

def cmd_analyze(args: argparse.Namespace) -> int:
    root = Path(args.path).expanduser().resolve()
    if not root.is_dir():
        print(Color.error(f"Error: '{root}' is not a directory."), file=sys.stderr)
        return 1

    excludes: List[str] = args.exclude or []
    scanner = Scanner(exclude_patterns=excludes)
    analyzer = Analyzer()
    formatter = Formatter(args.format)

    progress = Progress("Scanning")
    files, errors = scanner.scan(root, progress=progress)
    progress.done()

    result = analyzer.analyze(root, files, errors)
    print(formatter.format_analysis(result))
    return 0


def cmd_compare(args: argparse.Namespace) -> int:
    path1 = Path(args.path1).expanduser().resolve()
    path2 = Path(args.path2).expanduser().resolve()

    for p in (path1, path2):
        if not p.is_dir():
            print(Color.error(f"Error: '{p}' is not a directory."), file=sys.stderr)
            return 1

    excludes: List[str] = args.exclude or []
    scanner = Scanner(exclude_patterns=excludes)
    comparator = Comparator()
    formatter = Formatter(args.format)

    progress1 = Progress(f"Scanning {path1.name}")
    files1, errors1 = scanner.scan(path1, progress=progress1)
    progress1.done()

    progress2 = Progress(f"Scanning {path2.name}")
    files2, errors2 = scanner.scan(path2, progress=progress2)
    progress2.done()

    result = comparator.compare(path1, path2, files1, files2, errors1 + errors2)
    print(formatter.format_compare(result))
    return 0


# ─────────────────────────────────────────────
# Argument Parser
# ─────────────────────────────────────────────

def build_parser() -> argparse.ArgumentParser:
