function fetchUserPosts(userId, callback) {
    const url = `https://jsonplaceholder.typicode.com/users/${userId}/posts`;
    https.get(url, (res) => {
        let data = '';
        res.on('data', (chunk) => { data += chunk; });
        res.on('end', () => {
            try {
                callback(null, JSON.parse(data));
            } catch (e) {
