    // ===== SIDEBAR TOGGLE =====
    let sidebarCollapsed = false;

    function toggleSidebar() {
      const sidebar = document.getElementById('sidebar');
      const overlay = document.getElementById('overlay');
      const isDesktop = window.innerWidth >= 1024;

      if (isDesktop) {
        sidebarCollapsed = !sidebarCollapsed;
        sidebar.classList.toggle('collapsed', sidebarCollapsed);
      } else {
        const isHidden = sidebar.classList.contains('collapsed');
        sidebar.classList.toggle('collapsed', !isHidden);
        overlay.classList.toggle('active', isHidden);
      }
    }

    // Initialize sidebar as collapsed on mobile
    window.addEventListener('resize', () => {
      const sidebar = document.getElementById('sidebar');
      const overlay = document.getElementById('overlay');
      if (window.innerWidth >= 1024) {
        overlay.classList.remove('active');
        if (!sidebarCollapsed) {
          sidebar.classList.remove('collapsed');
        }
      } else {
        sidebar.classList.add('collapsed');
        overlay.classList.remove('active');
      }
    });

    // Set initial state
    if (window.innerWidth < 1024) {
      document.getElementById('sidebar').classList.add('collapsed');
    }

    // ===== DATE PICKER =====
    function toggleDatePicker() {
      const picker = document.getElementById('datePicker');
      picker.classList.toggle('open');
    }

    function setDateRange(range) {
      document.getElementById('dateRangeLabel').textContent = range;
      document.getElementById('datePicker').classList.remove('open');
    }

    // ===== NOTIFICATIONS =====
    function toggleNotif() {
      const dropdown = document.getElementById('notifDropdown');
      const userDropdown = document.getElementById('userDropdown');
      const datePicker = document.getElementById('datePicker');
      userDropdown.classList.remove('open');
      datePicker.classList.remove('open');
      dropdown.classList.toggle('open');
    }

    // ===== USER MENU =====
    function toggleUserMenu() {
      const dropdown = document.getElementById('userDropdown');
      const notifDropdown = document.getElementById('notifDropdown');
      const datePicker = document.getElementById('datePicker');
      notifDropdown.classList.remove('open');
      datePicker.classList.remove('open');
      dropdown.classList.toggle('open');
    }

    // Close dropdowns on outside click
    document.addEventListener('click', (e) => {
      const notifBtn = e.target.closest('[onclick="toggleNotif()"]');
      const userBtn = e.target.closest('[onclick="toggleUserMenu()"]');
      const dateBtn = e.target.closest('[onclick="toggleDatePicker()"]');
      const notifDropdown = document.getElementById('notifDropdown');
      const userDropdown = document.getElementById('userDropdown');
      const datePicker = document.getElementById('datePicker');

      if (!notifBtn && !e.target.closest('#notifDropdown')) {
        notifDropdown.classList.remove('open');
      }
      if (!userBtn && !e.target.closest('#userDropdown')) {
        userDropdown.classList.remove('open');
      }
      if (!dateBtn && !e.target.closest('#datePicker')) {
        datePicker.classList.remove('open');
      }
    });

    // ===== CHART TOOLTIP =====
    function showTooltip(event, label, value) {
      const tooltip = document.getElementById('chartTooltip');
      tooltip.textContent = `${label}: ${value}`;
      tooltip.classList.add('visible');

      const rect = event.target.closest('svg').getBoundingClientRect();
      const svgRect = event.target.getBoundingClientRect();

      tooltip.style.left = (svgRect.left + svgRect.width / 2 - tooltip.offsetWidth / 2) + 'px';
      tooltip.style.top = (svgRect.top - 36) + 'px';
    }

    function hideTooltip() {
      document.getElementById('chartTooltip').classList.remove('visible');
    }

    // ===== ANIMATE PROGRESS BARS =====
    window.addEventListener('load', () => {
      setTimeout(() => {
        document.querySelectorAll('.progress-fill').forEach(bar => {
          const width = bar.style.width;
          bar.style.width = '0%';
          setTimeout(() => {
            bar.style.width = width;
          }, 100);
        });
      }, 300);
    });
  </script>
