<title>Premium Navigation System</title>
<style>
  /* ============================================
     CSS CUSTOM PROPERTIES
  ============================================ */
  :root {
    --nav-height: 72px;
    --color-bg: #0a0a0f;
    --color-surface: rgba(15, 15, 25, 0.85);
    --color-surface-solid: #0f0f19;
    --color-border: rgba(255, 255, 255, 0.08);
    --color-text: #e8e8f0;
    --color-text-muted: rgba(232, 232, 240, 0.55);
    --color-accent: #6c63ff;
    --color-accent-glow: rgba(108, 99, 255, 0.35);
    --color-accent-hover: #8b85ff;
    --color-cta: linear-gradient(135deg, #6c63ff 0%, #a855f7 100%);
    --color-dropdown-bg: rgba(12, 12, 22, 0.97);
    --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    --radius-sm: 6px;
    --radius-md: 12px;
    --radius-lg: 20px;
    --shadow-nav: 0 1px 0 rgba(255,255,255,0.06), 0 8px 32px rgba(0,0,0,0.4);
    --shadow-dropdown: 0 20px 60px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.06);
    --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-spring: 500ms cubic-bezier(0.34, 1.56, 0.64, 1);
  }

  /* ============================================
     RESET & BASE
  ============================================ */
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    font-family: var(--font-sans);
    background: var(--color-bg);
    color: var(--color-text);
    line-height: 1.6;
    min-height: 200vh;
    overflow-x: hidden;
  }

  a {
    text-decoration: none;
    color: inherit;
  }

  ul {
    list-style: none;
  }

  button {
    cursor: pointer;
    border: none;
    background: none;
    font-family: inherit;
  }

  /* ============================================
     DEMO PAGE CONTENT
  ============================================ */
  .page-hero {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 120px 24px 60px;
    background: radial-gradient(ellipse 80% 60% at 50% 0%, rgba(108,99,255,0.15) 0%, transparent 70%);
  }

  .page-hero h1 {
    font-size: clamp(2.5rem, 6vw, 5rem);
    font-weight: 800;
    letter-spacing: -0.03em;
    background: linear-gradient(135deg, #fff 0%, rgba(255,255,255,0.6) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 20px;
  }

  .page-hero p {
    font-size: 1.2rem;
    color: var(--color-text-muted);
    max-width: 560px;
    margin: 0 auto 40px;
  }

  .hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 6px 16px;
    background: rgba(108,99,255,0.15);
    border: 1px solid rgba(108,99,255,0.3);
    border-radius: 100px;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-accent-hover);
    letter-spacing: 0.05em;
    text-transform: uppercase;
    margin-bottom: 28px;
  }

  .hero-badge::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--color-accent);
    box-shadow: 0 0 8px var(--color-accent);
    animation: pulse 2s ease-in-out infinite;
  }

  @keyframes pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.5; transform: scale(0.8); }
  }

  .scroll-hint {
    margin-top: 60px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    color: var(--color-text-muted);
    font-size: 0.8rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    animation: float 3s ease-in-out infinite;
  }

  .scroll-hint svg {
    opacity: 0.5;
  }

  @keyframes float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(8px); }
  }

  /* ============================================
     NAVIGATION WRAPPER
  ============================================ */
  .nav-wrapper {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 1000;
    transition: background var(--transition-base), box-shadow var(--transition-base), backdrop-filter var(--transition-base);
  }

  .nav-wrapper.scrolled {
    background: var(--color-surface);
    backdrop-filter: blur(20px) saturate(180%);
    -webkit-backdrop-filter: blur(20px) saturate(180%);
    box-shadow: var(--shadow-nav);
  }

  /* ============================================
     DESKTOP NAVIGATION
  ============================================ */
  .nav-desktop {
    height: var(--nav-height);
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 32px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  /* Logo */
  .nav-logo {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-right: 16px;
    flex-shrink: 0;
  }

  .nav-logo-mark {
    width: 36px;
    height: 36px;
    background: var(--color-cta);
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 0 20px var(--color-accent-glow);
    transition: transform var(--transition-spring), box-shadow var(--transition-base);
  }

  .nav-logo:hover .nav-logo-mark {
    transform: rotate(-5deg) scale(1.05);
    box-shadow: 0 0 30px var(--color-accent-glow);
  }

  .nav-logo-mark svg {
    width: 20px;
    height: 20px;
    fill: white;
  }

  .nav-logo-text {
    font-size: 1.1rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    color: var(--color-text);
  }

  .nav-logo-text span {
    color: var(--color-accent);
  }

  /* Nav Links Container */
  .nav-links {
    display: flex;
    align-items: center;
    gap: 2px;
    flex: 1;
  }

  /* Nav Item */
  .nav-item {
    position: relative;
  }

  .nav-link {
    display: flex;
    align-items: center;
    gap: 5px;
    padding: 8px 14px;
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--color-text-muted);
    border-radius: var(--radius-sm);
    transition: color var(--transition-fast), background var(--transition-fast);
    white-space: nowrap;
    position: relative;
  }

  .nav-link:hover,
  .nav-item.active > .nav-link {
    color: var(--color-text);
    background: rgba(255,255,255,0.06);
  }

  .nav-item.active > .nav-link::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 50%;
    transform: translateX(-50%);
    width: 20px;
    height: 2px;
    background: var(--color-accent);
    border-radius: 2px;
    box-shadow: 0 0 8px var(--color-accent);
  }

  /* Dropdown Arrow */
  .nav-arrow {
    width: 14px;
    height: 14px;
    opacity: 0.5;
    transition: transform var(--transition-base), opacity var(--transition-fast);
    flex-shrink: 0;
  }

  .nav-item:hover .nav-arrow,
  .nav-item:focus-within .nav-arrow {
    transform: rotate(180deg);
    opacity: 1;
  }

  /* ============================================
     DROPDOWN MENU
  ============================================ */
  .dropdown {
    position: absolute;
    top: calc(100% + 12px);
    left: 50%;
    transform: translateX(-50%) translateY(-8px);
    min-width: 240px;
    background: var(--color-dropdown-bg);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-dropdown);
    padding: 8px;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity var(--transition-base), transform var(--transition-base), visibility var(--transition-base);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
  }

  /* Dropdown arrow pointer */
  .dropdown::before {
    content: '';
    position: absolute;
    top: -5px;
    left: 50%;
    transform: translateX(-50%) rotate(45deg);
    width: 10px;
    height: 10px;
    background: var(--color-dropdown-bg);
    border-top: 1px solid var(--color-border);
    border-left: 1px solid var(--color-border);
  }

  .nav-item:hover .dropdown,
  .nav-item:focus-within .dropdown {
    opacity: 1;
    visibility: visible;
    pointer-events: all;
    transform: translateX(-50%) translateY(0);
  }

  /* Wide dropdown */
  .dropdown-wide {
    min-width: 520px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4px;
    left: 0;
    transform: translateX(0) translateY(-8px);
  }

  .dropdown-wide::before {
    left: 80px;
    transform: translateX(0) rotate(45deg);
  }

