<script>
  // ============================================
  // STICKY NAV ON SCROLL
  // ============================================
  const navbar = document.getElementById('navbar');

  const handleScroll = () => {
    if (window.scrollY > 20) {
      navbar.classList.add('scrolled');
    } else {
      navbar.classList.remove('scrolled');
    }
  };

  window.addEventListener('scroll', handleScroll, { passive: true });
  handleScroll(); // Run on init

  // ============================================
  // MOBILE MENU TOGGLE
  // ============================================
  const hamburgerBtn = document.getElementById('hamburgerBtn');
  const mobileCloseBtn = document.getElementById('mobileCloseBtn');
  const mobileMenu = document.getElementById('mobileMenu');
  const mobileOverlay = document.getElementById('mobileOverlay');

  let isMenuOpen = false;
  let previouslyFocused = null;

  const openMenu = () => {
    isMenuOpen = true;
    previouslyFocused = document.activeElement;

    hamburgerBtn.classList.add('active');
    hamburgerBtn.setAttribute('aria-expanded', 'true');
    hamburgerBtn.setAttribute('aria-label', 'Close navigation menu');

    mobileMenu.classList.add('active');
    mobileMenu.setAttribute('aria-hidden', 'false');

    mobileOverlay.classList.add('active');
    mobileOverlay.setAttribute('aria-hidden', 'false');

    document.body.style.overflow = 'hidden';

    // Focus first focusable element in menu
    setTimeout(() => {
      mobileCloseBtn.focus();
    }, 100);
  };

  const closeMenu = () => {
    isMenuOpen = false;

    hamburgerBtn.classList.remove('active');
    hamburgerBtn.setAttribute('aria-expanded', 'false');
    hamburgerBtn.setAttribute('aria-label', 'Open navigation menu');

    mobileMenu.classList.remove('active');
    mobileMenu.setAttribute('aria-hidden', 'true');

    mobileOverlay.classList.remove('active');
    mobileOverlay.setAttribute('aria-hidden', 'true');

    document.body.style.overflow = '';

    // Return focus
    if (previouslyFocused) {
      previouslyFocused.focus();
    }
  };

  hamburgerBtn.addEventListener('click', () => {
    isMenuOpen ? closeMenu() : openMenu();
  });

  mobileCloseBtn.addEventListener('click', closeMenu);
  mobileOverlay.addEventListener('click', closeMenu);

  // Close on Escape key
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && isMenuOpen) {
      closeMenu();
    }
  });

  // ============================================
  // MOBILE ACCORDION SUBMENUS
  // ============================================
  const accordionBtns = mobileMenu.querySelectorAll('.mobile-nav-link[aria-controls]');

  accordionBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const targetId = btn.getAttribute('aria-controls');
      const submenu = document.getElementById(targetId);
      const parentItem = btn.closest('.mobile-nav-item');
      const isOpen = parentItem.classList.contains('open');

      // Close all other open submenus
      accordionBtns.forEach(otherBtn => {
        const otherItem = otherBtn.closest('.mobile-nav-item');
        const otherId = otherBtn.getAttribute('aria-controls');
        const otherSubmenu = document.getElementById(otherId);

        if (otherItem !== parentItem && otherItem.classList.contains('open')) {
          otherItem.classList.remove('open');
          otherBtn.setAttribute('aria-expanded', 'false');
          if (otherSubmenu) otherSubmenu.setAttribute('aria-hidden', 'true');
        }
      });

      // Toggle current
      if (isOpen) {
        parentItem.classList.remove('open');
        btn.setAttribute('aria-expanded', 'false');
        submenu.setAttribute('aria-hidden', 'true');
      } else {
        parentItem.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
        submenu.setAttribute('aria-hidden', 'false');
      }
    });
  });

  // ============================================
  // FOCUS TRAP IN MOBILE MENU
  // ============================================
  mobileMenu.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return;

    const focusableSelectors = [
      'a[href]',
      'button:not([disabled])',
      '[tabindex]:not([tabindex="-1"])'
    ].join(', ');

    const focusableElements = Array.from(
      mobileMenu.querySelectorAll(focusableSelectors)
    ).filter(el => !el.closest('[aria-hidden="true"]'));

    const firstEl = focusableElements[0];
    const lastEl = focusableElements[focusableElements.length - 1];

    if (e.shiftKey) {
      if (document.activeElement === firstEl) {
        e.preventDefault();
        lastEl.focus();
      }
    } else {
      if (document.activeElement === lastEl) {
        e.preventDefault();
        firstEl.focus();
      }
    }
  });

  // ============================================
  // DESKTOP DROPDOWN KEYBOARD SUPPORT
  // ============================================
  const desktopNavItems = document.querySelectorAll('.nav-desktop .nav-item');

  desktopNavItems.forEach(item => {
    const link = item.querySelector('.nav-link');
    const dropdown = item.querySelector('.dropdown');

    if (!dropdown) return;

    // Update aria-expanded on hover
    item.addEventListener('mouseenter', () => {
      link.setAttribute('aria-expanded', 'true');
    });

    item.addEventListener('mouseleave', () => {
      link.setAttribute('aria-expanded', 'false');
    });

    // Keyboard: Enter/Space opens dropdown
    link.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        const isExpanded = link.getAttribute('aria-expanded') === 'true';

        // Close all others
        desktopNavItems.forEach(otherItem => {
          const otherLink = otherItem.querySelector('.nav-link');
          if (otherLink && otherLink !== link) {
            otherLink.setAttribute('aria-expanded', 'false');
          }
        });

        link.setAttribute('aria-expanded', isExpanded ? 'false' : 'true');

        if (!isExpanded) {
          // Focus first dropdown item
          const firstItem = dropdown.querySelector('.dropdown-item');
          if (firstItem) setTimeout(() => firstItem.focus(), 50);
        }
      }

      if (e.key === 'Escape') {
        link.setAttribute('aria-expanded', 'false');
        link.focus();
      }
    });

    // Close dropdown when focus leaves
    item.addEventListener('focusout', (e) => {
      if (!item.contains(e.relatedTarget)) {
        link.setAttribute('aria-expanded', 'false');
      }
    });

    // Arrow key navigation within dropdown
    dropdown.addEventListener('keydown', (e) => {
      const items = Array.from(dropdown.querySelectorAll('.dropdown-item'));
      const currentIndex = items.indexOf(document.activeElement);

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        const next = items[currentIndex + 1] || items[0];
        next.focus();
      }

      if (e.key === 'ArrowUp') {
        e.preventDefault();
        const prev = items[currentIndex - 1] || items[items.length - 1];
        prev.focus();
      }

      if (e.key === 'Escape') {
        link.setAttribute('aria-expanded', 'false');
        link.focus();
      }
    });
  });
</script>

