    .interest-card.selected {
      border-color: #6366f1;
      background: linear-gradient(135deg, #eef2ff, #f0f9ff);
    }
    .interest-card.selected .card-check {
      opacity: 1;
      transform: scale(1);
    }
    .card-check {
      opacity: 0;
      transform: scale(0.5);
      transition: all 0.2s ease;
