  <script>
    // ===== STATE =====
    let currentStep = 1;
    const totalSteps = 4;
    const connectedAccounts = new Set();
    const selectedInterests = new Set();

    const stepTitles = [
      'Welcome aboard! 👋',
      'Your Interests 🎯',
      'Connect Accounts 🔗',
      'All Done! 🎉'
    ];

    const interests = [
      { id: 'ai', emoji: '🤖', label: 'AI & ML' },
      { id: 'web', emoji: '🌐', label: 'Web Dev' },
      { id: 'mobile', emoji: '📱', label: 'Mobile' },
      { id: 'design', emoji: '🎨', label: 'Design' },
      { id: 'data', emoji: '📊', label: 'Data Science' },
      { id: 'cloud', emoji: '☁️', label: 'Cloud' },
      { id: 'security', emoji: '🔐', label: 'Security' },
      { id: 'devops', emoji: '⚙️', label: 'DevOps' },
      { id: 'blockchain', emoji: '⛓️', label: 'Blockchain' },
      { id: 'gaming', emoji: '🎮', label: 'Gaming' },
      { id: 'ux', emoji: '✏️', label: 'UX Research' },
      { id: 'open', emoji: '🌍', label: 'Open Source' },
    ];

    // ===== INIT =====
    function init() {
      renderInterests();
      updateUI();
    }

    function renderInterests() {
      const grid = document.getElementById('interests-grid');
      grid.innerHTML = interests.map(i => `
        <div
          class="interest-card bg-white border-2 border-gray-100 rounded-2xl p-4 flex flex-col items-center gap-2 relative"
          id="card-${i.id}"
          onclick="toggleInterest('${i.id}', this)"
        >
          <div class="card-check absolute top-2 right-2 w-5 h-5 bg-indigo-500 rounded-full flex items-center justify-center">
            <svg class="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/>
            </svg>
          </div>
          <span class="text-3xl">${i.emoji}</span>
          <span class="text-sm font-semibold text-gray-700 text-center">${i.label}</span>
        </div>
      `).join('');
    }

    // ===== INTEREST TOGGLE =====
    function toggleInterest(id, el) {
      if (selectedInterests.has(id)) {
        selectedInterests.delete(id);
        el.classList.remove('selected');
      } else {
        selectedInterests.add(id);
        el.classList.add('selected');
      }
      clearError('interests-error');
    }

    // ===== CONNECT TOGGLE =====
    function toggleConnect(service, btn) {
      if (connectedAccounts.has(service)) {
        connectedAccounts.delete(service);
        btn.classList.remove('connected');
        btn.textContent = 'Connect';
        btn.style.background = '';
      } else {
        connectedAccounts.add(service);
        btn.classList.add('connected');
        btn.innerHTML = `
          <svg class="w-4 h-4 inline mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/>
          </svg>
          Connected
        `;
      }
    }

    // ===== PHOTO UPLOAD =====
    function handlePhotoUpload(event) {
      const file = event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (e) => {
        const preview = document.getElementById('photo-preview');
        const placeholder = document.getElementById('photo-placeholder');
        const area = document.getElementById('photo-area');
        preview.src = e.target.result;
        preview.classList.remove('hidden');
        placeholder.classList.add('hidden');
        area.classList.add('has-photo');
      };
      reader.readAsDataURL(file);
    }

    // ===== VALIDATION =====
    function validateStep(step) {
      if (step === 1) {
        const name = document.getElementById('name-input').value.trim();
        const role = document.getElementById('role-select').value;
        let valid = true;

        if (!name) {
          showError('name-error');
          document.getElementById('name-input').classList.add('error');
          valid = false;
        }
        if (!role) {
          showError('role-error');
          document.getElementById('role-select').classList.add('error');
          valid = false;
        }
        return valid;
      }

      if (step === 2) {
        if (selectedInterests.size < 2) {
          showError('interests-error');
          return false;
        }
        return true;
      }

      return true;
    }

    function showError(id) {
      document.getElementById(id).classList.remove('hidden');
    }

    function clearError(id) {
      const el = document.getElementById(id);
      if (el) el.classList.add('hidden');
      // Also clear input error state
      if (id === 'name-error') document.getElementById('name-input').classList.remove('error');
      if (id === 'role-error') document.getElementById('role-select').classList.remove('error');
    }

    // ===== NAVIGATION =====
    function goNext() {
      if (!validateStep(currentStep)) return;

      if (currentStep < totalSteps) {
        transitionStep(currentStep, currentStep + 1, 'forward');
        currentStep++;
        updateUI();

        if (currentStep === totalSteps) {
          populateSummary();
          setTimeout(launchConfetti, 300);
        }
      }
    }

    function goBack() {
      if (currentStep > 1) {
        transitionStep(currentStep, currentStep - 1, 'backward');
        currentStep--;
        updateUI();
      }
    }

    function transitionStep(from, to, direction) {
      const fromPanel = document.getElementById(`step-${from}`);
      const toPanel = document.getElementById(`step-${to}`);

      // Exit current
      fromPanel.classList.add('exit-left');
      fromPanel.classList.remove('active');

      setTimeout(() => {
        fromPanel.classList.remove('exit-left');
        fromPanel.style.display = 'none';

        // Enter new
        toPanel.style.display = 'block';
        toPanel.style.opacity = '0';
        toPanel.style.transform = direction === 'forward' ? 'translateX(40px)' : 'translateX(-40px)';

        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            toPanel.style.opacity = '1';
            toPanel.style.transform = 'translateX(0)';
            toPanel.classList.add('active');
          });
        });
      }, 200);
    }

    function updateUI() {
      // Progress bar
      const pct = (currentStep / totalSteps) * 100;
      document.getElementById('progress-fill').style.width = `${pct}%`;

      // Step counter
      document.getElementById('step-counter').textContent = `Step ${currentStep} of ${totalSteps}`;

      // Title
      document.getElementById('step-title').textContent = stepTitles[currentStep - 1];

      // Dots
      document.querySelectorAll('.step-dot').forEach((dot, i) => {
        const stepNum = i + 1;
        if (stepNum < currentStep) {
          dot.className = 'step-dot w-3 h-3 rounded-full bg-white';
          dot.style.boxShadow = '0 0 0 3px rgba(255,255,255,0.4)';
        } else if (stepNum === currentStep) {
          dot.className = 'step-dot w-4 h-4 rounded-full bg-white';
          dot.style.boxShadow = '0 0 0 3px rgba(255,255,255,0.5)';
        } else {
          dot.className = 'step-dot w-3 h-3 rounded-full bg-white/30';
          dot.style.boxShadow = 'none';
        }
      });

      // Back button
      const backBtn = document.getElementById('back-btn');
      backBtn.disabled = currentStep === 1;

      // Next button & footer
      const nextBtn = document.getElementById('next-btn');
      const navFooter = document.getElementById('nav-footer');
      const skipHint = document.getElementById('skip-hint');

      if (currentStep === totalSteps) {
        navFooter.style.display = 'none';
      } else {
        navFooter.style.display = 'flex';
        if (currentStep === 3) {
          nextBtn.innerHTML = `Finish <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>`;
          skipHint.textContent = 'Optional step';
        } else {
          nextBtn.innerHTML = `Next <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>`;
          skipHint.textContent = '';
        }
      }
    }

    // ===== SUMMARY =====
    function populateSummary() {
      const name = document.getElementById('name-input').value.trim();
      const roleEl = document.getElementById('role-select');
      const roleText = roleEl.options[roleEl.selectedIndex]?.text || '—';

      document.getElementById('summary-name').textContent = `${name} · ${roleText}`;

      const interestLabels = [...selectedInterests].map(id => {
        const found = interests.find(i => i.id === id);
        return found ? `${found.emoji} ${found.label}` : id;
      });
      document.getElementById('summary-interests').textContent =
        interestLabels.length ? interestLabels.join(', ') : 'None selected';

      const connList = [...connectedAccounts];
      document.getElementById('summary-connections').textContent =
        connList.length ? connList.map(c => c.charAt(0).toUpperCase() + c.slice(1)).join(', ') : 'None connected';
    }

    // ===== CONFETTI =====
    function launchConfetti() {
      const colors = ['#6366f1', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#ef4444'];
      const container = document.getElementById('confetti-container');
      const count = 60;

      for (let i = 0; i < count; i++) {
        setTimeout(() => {
          const piece = document.createElement('div');
          piece.className = 'confetti-piece';
          piece.style.left = Math.random() * 100 + 'vw';
          piece.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
          piece.style.width = (Math.random() * 10 + 6) + 'px';
          piece.style.height = (Math.random() * 10 + 6) + 'px';
          piece.style.borderRadius = Math.random() > 0.5 ? '50%' : '2px';
          piece.style.animationDuration = (Math.random() * 2 + 2) + 's';
          piece.style.animationDelay = '0s';
          container.appendChild(piece);
          setTimeout(() => piece.remove(), 4000);
        }, i * 40);
      }
    }

    // ===== DASHBOARD =====
    function goToDashboard() {
      const btn = event.target;
      btn.textContent = '✨ Launching...';
      btn.disabled = true;
      setTimeout(() => {
        alert('🚀 Welcome to your dashboard! (This would navigate to the app)');
        btn.textContent = 'Go to Dashboard 🚀';
        btn.disabled = false;
      }, 1500);
    }

    // ===== START =====
    init();
  </script>
</body>
</html>
