function renderContacts(filter = '') {
  const list = document.getElementById('contactsList');
  list.innerHTML = '';
  contacts.filter(c => c.name.toLowerCase().includes(filter.toLowerCase())).forEach(c => {
    const div = document.createElement('div');
    div.className = `contact-item${c.id === activeContact ? ' active' : ''}`;
    div.onclick = () => selectContact(c.id);
    div.innerHTML = `
      <div class="avatar-wrap">
        <div class="avatar-placeholder ${c.grad}" style="width:48px;height:48px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:17px;font-weight:700;color:white;">${c.initials}</div>
