function selectContact(id) {
  activeContact = id;
  const c = contacts.find(x => x.id === id);
  document.getElementById('headerName').textContent = c.name;
  document.getElementById('headerAvatar').textContent = c.initials;
  document.getElementById('headerAvatar').className = `avatar-placeholder ${c.grad}`;
  const statusEl = document.getElementById('headerStatus');
  statusEl.textContent = c.online ? '● Active now' : `● ${c.status}`;
  statusEl.className = c.online ? 'header-status' : 'header-status away';
  document.getElementById('headerOnlineDot').style.display = c.online ? 'block' : 'none';
  c.unread = 0;
  renderContacts(document.getElementById('searchInput').value);
  renderMessages();
  closeSidebar();
}

function renderMessages() {
  const container = document.getElementById('messagesContainer');
  container.innerHTML = '';
  const msgs = conversations[activeContact] || [];
  const c = contacts.find(x => x.id === activeContact);

  msgs.forEach(msg => {
    if (msg.type === 'date') {
      const div = document.createElement('div');
      div.className = 'date-divider';
      div.innerHTML = `<span>${msg.text}</span>`;
      container.appendChild(div);
      return;
    }

    if (msg.type === 'typing') {
      const row = document.createElement('div');
      row.className = 'typing-row';
      row.id = 'typingIndicator';
      row.innerHTML = `
        <div class="msg-avatar-placeholder ${c.grad}" style="color:white;">${c.initials}</div>
        <div>
          <div class="typing-bubble">
            <div class="typing-dot"></div>
            <div class="typing-dot"></div>
            <div class="typing-dot"></div>
          </div>
          <div class="typing-label">${c.name.split(' ')[0]} is typing...</div>
        </div>
      `;
      container.appendChild(row);
      return;
    }

    const row = document.createElement('div');
    row.className = `message-row ${msg.type}`;

    let avatarHtml = '';
    if (msg.type === 'received') {
      avatarHtml = `<div class="msg-avatar-placeholder ${c.grad}" style="color:white;">${c.initials}</div>`;
    }

    let bubbleContent = '';
    if (msg.img) {
      bubbleContent = `
        <div class="bubble img-bubble">
          <img src="${msg.img}" alt="Image" loading="lazy" onerror="this.src='https://picsum.photos/400/300'">
        </div>
        ${msg.caption ? `<div class="bubble-meta"><span class="msg-time">${msg.time}</span></div>` : ''}
      `;
    } else {
      const readIcon = msg.type === 'sent'
        ? `<span class="read-receipt ${msg.read ? '' : 'sent-only'}">${msg.read ? '✓✓' : '✓'}</span>`
        : '';
      bubbleContent = `
        <div class="bubble">${escapeHtml(msg.text)}</div>
        ${msg.reaction ? `<div class="reaction">${msg.reaction}</div>` : ''}
        <div class="bubble-meta">
          <span class="msg-time">${msg.time}</span>
          ${readIcon}
        </div>
      `;
    }

    row.innerHTML = `
      ${avatarHtml}
      <div class="bubble-wrap">${bubbleContent}</div>
    `;

    container.appendChild(row);
  });

  container.scrollTop = container.scrollHeight;
}

function escapeHtml(text) {
  return text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function sendMessage() {
  const input = document.getElementById('msgInput');
  const text = input.value.trim();
  if (!text) return;

  const now = new Date();
  const time = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  const msgs = conversations[activeContact];
  // Remove typing indicator temporarily
  const typingIdx = msgs.findIndex(m => m.type === 'typing');
  let typingMsg = null;
  if (typingIdx !== -1) {
    typingMsg = msgs.splice(typingIdx, 1)[0];
  }

  msgs.push({ type: 'sent', text, time, read: false });

  if (typingMsg) msgs.push(typingMsg);

  // Update contact preview
  const c = contacts.find(x => x.id === activeContact);
  c.lastMsg = text;
  c.time = 'now';

  input.value = '';
  input.style.height = 'auto';
  renderContacts(document.getElementById('searchInput').value);
  renderMessages();

  // Simulate read receipt after 1.5s
  setTimeout(() => {
    const sentMsgs = conversations[activeContact].filter(m => m.type === 'sent');
    if (sentMsgs.length > 0) sentMsgs[sentMsgs.length - 1].read = true;
    renderMessages();
  }, 1500);

  // Simulate reply after 2-4s
  if (activeContact === 1) {
    setTimeout(() => simulateReply(), 2500 + Math.random() * 1500);
  }
}

const autoReplies = [
  "That's so true! 😄",
  "Haha no way! 😂",
  "I was just thinking the same thing",
  "Okay okay you got me there 😅",
  "Wait really?? Tell me more!",
  "Lol I can't believe that 😂",
  "That's actually hilarious 🤣",
  "Okay but seriously though...",
  "You're the best 🙌",
  "Facts facts facts 💯"
];

function simulateReply() {
  const msgs = conversations[activeContact];
  const typingIdx = msgs.findIndex(m => m.type === 'typing');
  if (typingIdx !== -1) msgs.splice(typingIdx, 1);

  const now = new Date();
  const time = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const reply = autoReplies[Math.floor(Math.random() * autoReplies.length)];

  msgs.push({ type: 'received', text: reply, time });
  msgs.push({ type: 'typing' });

  const c = contacts.find(x => x.id === activeContact);
  c.lastMsg = reply;
  c.time = 'now';

  renderContacts(document.getElementById('searchInput').value);
  renderMessages();
}

function handleKey(e) {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    sendMessage();
  }
}

function autoResize(el) {
  el.style.height = 'auto';
  el.style.height = Math.min(el.scrollHeight, 120) + 'px';
}

function toggleEmoji() {
  const picker = document.getElementById('emojiPicker');
