  }
}

function showEmojiCat(cat) {
  currentEmojiCat = cat;
  document.querySelectorAll('.emoji-cat-btn').forEach(b => b.classList.remove('active'));
  event && event.target && event.target.classList.add('active');

  const grid = document.getElementById('emojiGrid');
  grid.innerHTML = '';
  (emojiData[cat] || []).forEach(emoji => {
    const btn = document.createElement('button');
    btn.className = 'emoji-btn';
    btn.textContent = emoji;
    btn.onclick = () => insertEmoji(emoji);
    grid.appendChild(btn);
  });
}

function insertEmoji(emoji) {
  const input = document.getElementById('msgInput');
  const start = input.selectionStart;
  const end = input.selectionEnd;
  input.value = input.value.slice(0, start) + emoji + input.value.slice(end);
  input.selectionStart = input.selectionEnd = start + emoji.length;
  input.focus();
  autoResize(input);
}

function triggerAttach() {
  document.getElementById('fileInput').click();
}

function handleFile(e) {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (ev) => {
    const now = new Date();
    const time = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const msgs = conversations[activeContact];
    const typingIdx = msgs.findIndex(m => m.type === 'typing');
    let typingMsg = null;
    if (typingIdx !== -1) typingMsg = msgs.splice(typingIdx, 1)[0];
    msgs.push({ type: 'sent', img: ev.target.result, time, read: false });
    if (typingMsg) msgs.push(typingMsg);
    renderMessages();
  };
  reader.readAsDataURL(file);
  e.target.value = '';
}

function filterContacts() {
  renderContacts(document.getElementById('searchInput').value);
}

function openSidebar() {
  document.getElementById('sidebar').classList.add('open');
  document.getElementById('overlay').classList.add('open');
}

function closeSidebar() {
  document.getElementById('sidebar').classList.remove('open');
  document.getElementById('overlay').classList.remove('open');
}

// Close emoji picker on outside click
document.addEventListener('click', (e) => {
  const picker = document.getElementById('emojiPicker');
  if (picker.classList.contains('open') &&
      !picker.contains(e.target) &&
      !e.target.closest('.action-btn')) {
    picker.classList.remove('open');
  }
});

// Touch/swipe support for mobile sidebar
let touchStartX = 0;
document.addEventListener('touchstart', e => { touchStartX = e.touches[0].clientX; });
document.addEventListener('touchend', e => {
  const dx = e.changedTouches[0].clientX - touchStartX;
  if (dx > 60 && touchStartX < 30) openSidebar();
  if (dx < -60) closeSidebar();
});

// Init
renderContacts();
selectContact(1);

// Show emoji cat buttons properly
document.querySelectorAll('.emoji-cat-btn').forEach((btn, i) => {
